window.__D("text/torat-shmuel/c045",{"p":[[2000470539,"ברישא חשוכא<sup data-n=\"5265\">43</sup> והדר נהורא כמו\"כ כאשר רואה האדם בכל יום שבתחילה מאפיל ואח\"כ מאיר הרי מובן שהקב\"ה מחדש אותם בכל יום, אבל באמת הרי הוא מחדשם בכל רגע ורגע, ושרש חידוש הישינות האלו הוא מטוב שלו העצמי והוא הוא המשגיח על כל פרטי פרטיות. ובזה יובן מה שאמר פרעה לא ידעתי את הוי', כי הוא הי' כופר בש' הוי', כי מש' אלקים ידע<sup data-n=\"5266\">44</sup> שיוסף הודיעו וכמ\"ש אלקים יענה<sup data-n=\"5267\">45</sup> כו'. אך שיוסף הודיע לו האלקים כמו שהוא מיוחד עם ש' הוי' אבל פרעה קיבל ממנו לפי טעותו רק ש' אלקים בלבד וכפר בש' הוי' ולכן עשה הקב\"ה אותות ומופתים בארץ שינוי הטבע באין מונע כלל, ועי\"ז ראו שאין ממש ביד המזלות, כי אם הי' בהם איזה כח לעשות רצונם הרי הי' מונעים ומעכבים, כמו ע\"ד האדם שמי שיש כח ויכולת ועושים נגד רצונו ה\"ה מונע ומעכב, ואם הי' ביד המזלות איזה כח ה\"ה הי' מעכבים, ובמצרים הי' שולט אז מזל טלה והקב\"ה עשה ביד המזלות עצמם כרצונו, הרי ראו שהוא המשגיח על כל פרט ולא כמו שהם אומרים עזב את הארץ. וזהו מ\"ש למען תדע כי אין כמוני בכל הארץ.\n<b>ובזה</b> יובן ענין העגל שאעפ\"י שראו האותות והמופתים שעשה הקב\"ה במצרים מ\"מ כאשר עלה משה בהר מצאו הערב רב מקום להטעות את ישראל ואמרו שלא מפני השגחתו של הקב\"ה הי' האותות והמופתים כ\"א שמזל שור נלחם עם מזל טלה וכבש אותו והוא עשה את האותות והמופתים, וע\"ד שמצינו בדניאל דכתיב שהמזלות לוחמים<sup data-n=\"5268\">46</sup>, ובאמת א\"א ללחום הם בעצמם דמה שאמר דניאל שהמזלות לוחמים הוא ע\"י ציווי הקב\"ה אבל בעצמם אינם יכולים לעשות כלום, ולכן עשו את העגל העלאת מ\"ן למזל שור וזהו כללות ענין חטא העגל. והנה הנשים לא נתקבל אצלם דעת זה כי נשים הם עלמא דנוקבא אשר שרשם ממל' והנה כתי' י\"ב בקר שהם י\"ב מזלות<sup data-n=\"5269\">48</sup> דרקיע<sup data-n=\"5270\">49</sup> והים עומד עליהם<sup data-n=\"5271\">47</sup> ים הוא מל' דאצי'<sup data-n=\"5272\">50</sup> והוא שולט ומושל עליהם וה\"ה יודעים שהמזלות אין בהם כלום ממש כי ה\"ה בעצמו מושל עליהם והנשים ששרשם ממל' ומל' הוא מקור הנבראים וממנו יכול להיות גילוי שיורגש בנפש האדם ולכן הרגישו הנשים זאת ולא קיבלו דיעה הזאת ולא פרקו נזמי הזהב שלהם, אבל האנשים ששרשם מז\"א שהוא מרוחק בערך בי\"ע הרי לא יוכלו<sup data-n=\"5273\">51</sup> להיות משם גילוי שיורגש בנפש האדם, והמל' שמשם יוכל להיות גילוי המורגש ה\"ז אינו השרש שלהם, ומאין ירגישו זאת, ולכן טעו אחר הערב רב לאמר שיש כח לצבא המזלות ועשו כדמות עגל העלאות מ\"ן למזל שור.",[["5265","43","<b>כברייתו. . ברישא חשוכא</b>: שבת עז, ב (כגי') רש\"י. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540050\" data-slug=\"torat-chaim\" data-id=\"2300540050\">תו\"ח וארא ח\"א מט, ג</a> ואילך. הנסמן בסה\"מ תרכ\"ז ע' תנד."],["5266","44","<b>פרעה. . מש' אלקים ידע</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370193\" data-slug=\"torah-or\" data-id=\"3901370193\">תו\"א מקץ מג, רע\"א</a>. סידור שער החנוכה ערא, סע\"ב."],["5267","45","<b>אלקים יענה</b>: מקץ מא, טז."],["5268","46","<b>בדניאל. . שהמזלות לוחמים</b>: ראה שם פ\"י ואילך."],["5269","48","<b>י\"ב בקר שהם י\"ב מזלות</b>: ראה פרדס שער פרטי השמות שכ\"א, פ\"ו."],["5270","49","<b>י\"ב מזלות דרקיע</b>: ברכות לב, ב. רמב\"ם הל' יסוה\"ת פ\"ג, ה\"ו."],["5271","47","<b>י\"ב בקר. . והים עומד עליהם</b>: ראה מלכים-א ז, כה. מד. דהי\"ב ד, טו."],["5272","50","<b>ים הוא מל' דאצי'</b>: ראה זהר בהעלותך קנ, ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תסג."],["5273","51","<b>יוכלו</b>: כ\"ה בהכת\"י."]]],[2000470540,"<b>ובזה</b> יובן מה שנתנו לנשים דוקא יו\"ט של ר\"ח. כי הנה בר\"ח מקבלת הלבנה אור חוזר מהשמש ועיקר אורה היא מהשמש<sup data-n=\"5274\">52</sup> ובנמשל הלבנה הוא מל'<sup data-n=\"5275\">53</sup> שהוא ש' אלקים<sup data-n=\"5276\">54</sup> שמקבל כל הכח שלו מש' הוי' וזהו ענין יחוד הוי' ואלקים, ולכן הנשים ששרשם ממל' ש' אלקים והם לא האמינו בעגל ולכן ניתן להם שכר איסור עשיית מלאכה של ר\"ח שהוא ענין היחוד דהוי' ואלקים, ולכן יש טעם ע\"פ נגלה מה שסתם ווסת הנשים הוא מל' לל' יום, ע\"ד מילוי הלבנה<sup data-n=\"5277\">55</sup>, וכמ\"ש באסתר ואני לא נקראתי<sup data-n=\"5278\">56</sup> לבוא אל המלך זה שלשים יום. ובנש\"י בעבודה הוא מ\"ש יפה כלבנה<sup data-n=\"5279\">57</sup>. ובזה יובן מה שנשמות ישראל מונים ללבנה<sup data-n=\"5280\">58</sup> ואומות העולם מונין לחמה, כי הגם שהחמה היא גדולה מהלבנה מכל מקום הרי זה ע\"ד רם כו' על השמים כו' אבל הלבנה היא קטנה מהשמש ולכן מקבלת אורה מהשמש. והרי זה מורה על יחוד הוי' ואלקים, ולכן ישראל מונין ללבנה דוקא. ובזה יובן פירוש הפסוק המגביה<sup data-n=\"5281\">59</sup> לשבת, כי אומות העולם אומרים רם על כל גוים הוי' על השמים רוממות א\"ס עצמותו ומהותו הוא מה שמשגיח רק בשמים בלבד. אבל נשמות ישראל הם מאמינים בני מאמינים<sup data-n=\"5282\">60</sup> משיבים כי אדרבה לפי שהוא מגביהי לשבת הרי שמים השפלה לפניו כמו הארץ הגשמי' ואם כן גם לפי טעותם הם אומרים שמשגיח בשמים כמו כן הוא משגיח בארץ וזהו מ\"ש מי כהוי' אלקינו המגביהי לשבת המשפילי לראות בשמים ובארץ, אלקינו דוקא, שנשמות ישראל יאמרו כן דוקא, כי הפסוק הזה מוציא גם כן השיתוף ובני נח אינם מצווים על השיתוף<sup data-n=\"5283\">61</sup> כי אם נשמות ישראל דוקא, ולכן אמר מי כהוי' אלקינו דוקא.",[["5274","52","<b>מקבלת הלבנה אור. . מהשמש</b>: ראה סידור שחרית לשבת קפב, ד. מאמרי אדה\"א דברים ח\"ג ע' תתפג. וש\"נ. סה\"מ תרל\"ח ע' נד. וש\"נ."],["5275","53","<b>הלבנה הוא מל'</b>: ראה פרדס שעה\"כ שכ\"ג מערכת לבנה."],["5276","54","<b>מל'. . אלקים</b>: ראה זהר בראשית כב, א. אחרי סה, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540393\" data-slug=\"torat-chaim\" data-id=\"2300540393\">תו\"ח וארא ח\"א עה, ב</a> הערה 202."],["5277","55","<b>ווסת הנשים. . הלבנה</b>: ראה אוה\"ת תשא כאן ע' א'תתקפז."],["5278","56","<b>ואני לא נקראתי</b>: אסתר ד, יא."],["5279","57","<b>יפה כלבנה</b>: שה\"ש ו, י."],["5280","58","<b>ישראל מונים ללבנה</b>: ראה סוכה כט, א."],["5281","59","<b>המגביה</b>: כ\"ה בהכת\"י."],["5282","60","<b>מאמינים בני מאמינים</b>: שבת צז, א. וראה אוה\"ת בראשית כרך ג ע' 1104. תשא ע' א'תתעט."],["5283","61","<b>ובני נח אינם מצווים על השיתוף</b>: ראה רמ\"א בשו\"ע או\"ח סקנ\"ו. סה\"מ תרכ\"ט ע' רנה ואילך. מלוקט א' ע' נב ואילך. וש\"נ. ספר הערכים חב\"ד כרך ב מערכת אוה\"ע ע' שמג. וש\"נ."]]],[2000470541,"<h3>כמים הפנים</h3>\n<b></b><b>בס\"ד פ' שמות שנת תר\"מ הנחה</b>\nשמות\n<b>כמים</b> הפנים<sup data-n=\"5284\">1</sup> כן לב האדם אל האדם<sup data-n=\"5285\">2</sup>, הנה נת\"ל<sup data-n=\"5286\">3</sup> בפי' האדם אל האדם דיש ב' בחי' אדם, אדם שבחיות המרכבה ואדם העליון שעל הכסא, ובכדי שיהי' נמשך מאדה\"ע שעל הכסא לד' חיות הוא ע\"י העלאות מ\"ן ואתעדל\"ת של האדם דלמטה, והעלאות מ\"ן הוא ע\"י הקרבנות כי ע\"י שמקריבין הבהמה הגשמי' ע\"ג המזבח עי\"ז היא נכללת באש שלמטה ובאש שלמעלה עד שנעשה אכילה לארי' שבמרכבה כמ\"ש בזהר ארי' דאכיל קרבנין<sup data-n=\"5287\">4</sup>, וענין אכילה הוא שנשתנה ממהות למהות, ממהות בע\"ח למהות חיות המרכבה, ועי\"ז מתעלה הארי' לאדה\"ע ועי\"ז נמשך אח\"כ מאדה\"ע לאדם שבמרכבה. והנה בעבודה בנפש האדם ישנו ג\"כ כל הבחי' הנ\"ל והענין דהנה ארז\"ל מיכאל עומד ומקריב נשמותיהן של ישראל<sup data-n=\"5288\">5</sup> ע\"ג המזבח, והגם שפעם ארז\"ל נשמותיהן של צדיקים<sup data-n=\"5289\">6</sup> המכוון הוא ג\"כ על כללות נש\"י כי ועמך כולם צדיקים<sup data-n=\"5290\">7</sup> כתי', וצ\"ל למה נצרכים נש\"י לההקרבה וההעלאה של מיכאל דבשלמא בקרבנות יתכן ענין ארי' דאכיל קרבנין שהו\"ע העלי' שע\"י הארי' שלמעלה, כי נפש הבהמה הגם ששרשה ג\"כ מחיות המרכבה<sup data-n=\"5291\">8</sup> מ\"מ ה\"ה נשתלשלה למטה עד שנעשה בהמה גשמיות ואח\"כ כשנעשית אכילה לארי' דלעילא ונת\"ל שענין אכילה הוא שמשתנה ממהות למהות וה\"ז עלי' גדולה שמשתנה ממהות בהמה גשמי' לארי' דלעילא, אבל נשמות ישראל שהם חלק אלקה<sup data-n=\"5292\">9</sup> ה\"ז אלקות ולמה צריכים צדיקים שהם נשמות דאצי' להעלי' שע\"י מיכאל, והגם שנת\"ל שכללות נשמות ישראל נקראים בש' צדיקים מ\"מ הרי כל הנשמה בפרט יש לה שרש מאצי' העליון וכמ\"ש בבינונים<sup data-n=\"5293\">10</sup> כי אפי' מי שאין לו רק נפש דמל' דמל' דעשי'<sup data-n=\"5294\">11</sup> שרש",[["5284","1","<b>כמים הפנים</b>: הנחה ממאמר הג' מהמשך זאת חנוכת המזבח [ושם הפתיחה ”והנה כו' מיכאל עומד ומקריב\" פרקים ו-ז] שנדפס לעיל בחלק המאמרים. וש\"נ."],["5285","2","<b>כמים הפנים. . אל האדם</b>: משלי כז, יט [בדילוג. ושם: לאדם]."],["5286","3","<b>נת\"ל</b>: (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ה."],["5287","4","<b>ארי' דאכיל קרבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שה\"א עט, ב הערה 13. לעיל (בחלק המאמרים) פ\"ה."],["5288","5","<b>מיכאל עומד ומקריב נשמותיהן של ישראל</b>: ראה זהר ס\"ת לך פ, סע\"א. רע\"מ צו לג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380631\" data-slug=\"likkutei-torah\" data-id=\"4001380631\">לקו\"ת פינחס עז, ד</a>. ש\"ש סז, ד."],["5289","6","<b>מיכאל. . נשמותיהן של צדיקים</b>: ראה חגיגה יב, ב (כגי' הע\"י). תוד\"ה ומיכאל מנחות קי, א. מאמרי אדה\"א ויקרא ח\"א ע' א. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540486\" data-slug=\"torat-chaim\" data-id=\"2300540486\">תו\"ח שמות ח\"א ה, א</a>. וש\"נ."],["5290","7","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["5291","8","<b>הבהמה. . מחיות המרכבה</b>: נסמן להלן הערה 76."],["5292","9","<b>נשמות. . חלק אלקה</b>: ראה איוב לא, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540089\" data-slug=\"torat-chaim\" data-id=\"2300540089\">תו\"ח וארא ח\"א נא, ד</a>. וש\"נ."],["5293","10","<b>כל הנשמה. . מאצי'. . בבינונים</b>: <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>."],["5294","11","<b>נפש דמל' דמל' דעשי'</b>: בתניא שם: נפש דנפש דמל' דעשי'. ראה גם לעיל (בחלק המאמרים) המשך מצה זו ספ\"דא. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויהי הענן והחשך על יד הערה 40. ד\"ה ישקני מנשיקות פיהו על יד הערה 26. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה וזהו שרש יונתיא על יד הערה 22. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה הא' על יד הערה 49 ועל יד הערה 58. ד\"ה עטרת תפארת שיבה על יד הערה 71. (בחלק ההנחות) הנחה ד\"ה יפה שעה הא' על יד הערה 47. שם על יד הערה 61א. סה\"מ תרל\"ח ע' תפג. וש\"נ."]]],[2000470542,"שרשו הוא מאצי' כי במל' דעשי' מלובש חכ' דעשי' אשר בו מלובש מל' דיצי' וחכ' דיצי' עד חכ' דאצי' שבו השראות אוא\"ס וא\"כ הרי כל נשמה שרשה מאצי' ומפני זה נק' חלק הוי' כמ\"ש כי חלק הוי' עמו<sup data-n=\"5295\">12</sup> ולמה צריכים לההקרבה של מיכאל, וא\"א לומר שנק' בש' חלק עש\"ז שנבדלת מהעצם דהלא כתי' חלק הוי' עמו וה\"ה נקראת גם אחר ירידתה למטה בש' חלק הוי' ה\"ה חלק מהעצם וה\"ה ג\"כ עצם<sup data-n=\"5296\">13</sup> שה\"ה חלק מכל העצם.\n<b>אך</b> הענין דהנה אנו אומרים נשמה שנתת בי טהורה אתה בראת<sup data-n=\"5297\">14</sup> יצרת נפחת וצ\"ל האיך שייך לומר טהורה קודם שבראת דהלא ידוע שענין הבריאה הוא בריאה יש מאין שהוא התחדשת לגמרי וכמ\"ש אם בריאה יברא<sup data-n=\"5298\">15</sup> ופרש\"י אם נברא מכבר מוטב ואם לא יברא עכשיו מחדש, והגם שהקשו כל המפרשים<sup data-n=\"5299\">16</sup> דהא אין כל חדש תחת השמש<sup data-n=\"5300\">17</sup> הרי תרצו ע\"ז תירוצים הרבה, דאם נפרש שפי' בריאה אינו התחדשות וא\"כ ה\"ז השתל' עילה ועלול<sup data-n=\"5301\">18</sup> הלא הי' גם הכופרים בבריאת העולם מודים שהרי הם אינם מאמינים רק בהתחדשות העולם בבריאה חדשה, אבל בהשתל' הרי הם מודים ואם הי' בריאת עולם ע\"י השתל' ה\"ה<sup data-n=\"5302\">*19</sup> גם הם מודים, אלא ע\"כ שהוא התחדשות לגמרי. ועוד דא\"א כלל לומר שבריאת עולם הוא ע\"י השתל' כי ענין השתל' עו\"ע הוא שהעלול הי' תחילה בהעלם בהעילה, ועד\"מ שכל ומדות<sup data-n=\"5303\">19</sup> שענין המדה הוא רצון לאיזה דבר ובכדי שיהי' מדות הגלויים הוא ע\"י שמבין היטב בשכלו האיך שנצרך להיות לו רצון לאותו הדבר ונעשה הטי' בשכלו לאותו הדבר, וה\"ז מדות שבשכל ומזה נעשה אח\"כ בלב מדה ממש מדות שבלב, וא\"כ הגורם למדה שבלב הוא השכל שיש בו מדה שבשכל וא\"כ מדות שבלב אינו התחדשות גמור כ\"א בתחילה הי' בהעלם בשכל מדות שבשכל, ואח\"כ יצאו לידי גילוי להיות מדה שבלב, וכמו\"כ מחשבה ודיבור<sup data-n=\"5304\">20</sup>. וזהו ענין השתל' דפי' השתל' הוא מלשון שלשלת<sup data-n=\"5305\">21</sup> שטבעת א' אחוז בחבירו והרי מחצה העליון של טבעת התחתון מלובש במחצה התחתון של העליון עד שנעשה שלשלת ארוכה, וא\"כ אם נאמר שבריאת עולמות הי' ע\"י השתל' הרי נצטרך לומר שעוה\"ז הגשמי' כמו שהוא הי' תחילה בהעלם בשרשו",[["5295","12","<b>כי חלק הוי' עמו</b>: האזינו לב, ט. ראה גם סה\"מ ליקוט ג' ע' רכח ואילך."],["5296","13","<b>חלק מהעצם וה\"ה ג\"כ עצם</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתכד. וש\"נ. פלח הרמון ויקרא ע' מד. וש\"נ."],["5297","14","<b>נשמה שנתת בי. . בראת</b>: ברכת אלקי נשמה (מברכות ס, ב)."],["5298","15","<b>אם בריאה יברא</b>: קרח טז, ל [ושם: ואם]. ראה רש\"י שם."],["5299","16","<b>שהקשו כל המפרשים</b>: ראה סנהדרין קי, סע\"א."],["5300","17","<b>אין כל חדש תחת השמש</b>: קהלת א, ט."],["5301","18","<b>עילה ועלול</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">לקו\"ת ברכה צה, ב</a>: הנזכר בספרים. שה\"ש א, ב: כמ\"ש בספרים. ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו."],["5302","*19","<b>ה\"ה</b>: הרי היו."],["5303","19","<b>עו\"ע. . שכל ומדות</b>: ראה סידור סדר הגדה רצה, סע\"ד ואילך. אוה\"ת תשא ע' א'תתקצב. סה\"מ תרל\"ח ע' שע. וש\"נ."],["5304","20","<b>עו\"ע. . מחשבה ודיבור</b>: ראה סידור שם. תו\"ח בשלח ח\"א קלט, א ואילך. ובהנסמן בריש המאמר שם."],["5305","21","<b>השתל'. . שלשלת</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370287\" data-slug=\"torah-or\" data-id=\"3901370287\">תו\"א בשלח סד, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540159\" data-slug=\"torat-chaim\" data-id=\"2300540159\">תו\"ח שמות ח\"א כד, ב</a> הערה 36."]]],[2000470543,"הרוחני, וזהו דבר שא\"א כלל לאומרו, ואף שהגשמי' מתהוה מהרוחני' מ\"מ הרי הכל מודים שהתהות הגשמי' מהרוחניות<sup data-n=\"5306\">22</sup> אין לך בריאה יש מאין גדול מזה.\n<b>ויובן</b> זה ממה שארז\"ל בפרקי דר\"א הארץ מהיכן נבראת<sup data-n=\"5307\">23</sup> משלג שתחת כסא הכבוד, ואם נאמר שהשלג הוא שלג גשמי' היו שואלים מהיכן נברא השלג, אלא ע\"כ שהשלג הוא שלג רוחני' והיינו כי השי\"ן<sup data-n=\"5308\">24</sup> הוא ג' מאות וה\"ה ג' במאות והלמ\"ד הוא ג' פעמים עשרה וה\"ה ג' בעשירית והג' הוא ג' ביחידות, ומהמדריגה שברוחניות הנק' יחידות עשירות מאות מזה נתהוה הארץ הגשמי, וה\"ה זה מובן לכל שא\"א לומר שהארץ כמו שהיא גשמי הי' שמה עומד בשרשו הרוחני אלא ע\"כ שהבריאה היא התחדשות לגמרי ולכן נק' בש' בריאה, וא\"כ מה שנאמר בנשמה אתה בראת הפי' ג\"כ בראת ע\"ש התחדשות לגמרי ולפ\"ז לא הי' עדיין מציאותה והאיך יתכן לומר טהורה קודם בראת שהרי שם טהור נופל לומר על איזה מציאות וכמ\"ש בלוים וכה תעשה להם לטהרם<sup data-n=\"5309\">25</sup> כי זהו ההפרש בין כהנים ללוים שהכהנים הם במדריגת קדושה ולוים במדרי' טהורה<sup data-n=\"5310\">26</sup>, ועכ\"פ השם טהרה נאמר על מציאות הלוים, וא\"כ איך שייך לומר כן קודם בריאת הנשמה כלל, וזה א\"א לומר ששם טהור קאי על הניצוץ האלקי המתלבש בהנשמה<sup data-n=\"5311\">27</sup>, אבל הנשמה עצמה היא בבחי' בריאה, כי זה לא יתכן כי הרי הנשמה עצמה נק' חלק הוי'.\n<b>אך</b> הענין דהנה פי' טהורה קאי על שרשה הקדומה של הנשמה כמו שהיתה באצי'<sup data-n=\"5312\">28</sup> העליון קודם שירדה להקרא בש' איזה מציאת גשם דהנה כל נשמה שרש שרשה מאצי' העליון כמשנת\"ל דאפי' נפש דמל' דמל' דעשי' הרי מלובש בו עד חכ' דאצי' שבה שורה אוא\"ס, ומה שיש פרטי נשמות שנק' בש' נשמות דאצי' והם נשמות דזרע אדם ההפרש ביניהם לבין נשמות דזרע בהמה<sup data-n=\"5313\">29</sup> כי נשמות דאצי' גם לאחר שירדו להתלבש למטה בגוף ונה\"ב ה\"ה דבוקים לאלקי' חיים כמו שהיו בשרשן באצי' וכמ\"ש בפרד\"ס בש' ספר הבהיר כל זמן היות אברם בעולם<sup data-n=\"5314\">30</sup> לא",[["5306","22","<b>שהתהוות הגשמי' מהרוחניות</b>: ראה (לעיל בחלק המאמרים) זאת חנוכת המזבח פ\"ד ובהערה 62."],["5307","23","<b>בפרקי דר\"א הארץ מהיכן נבראת</b>: ראה שם פ\"ג. ראה גם המשך מים רבים תרל\"ו פקנ\"ה. וש\"נ בפנים."],["5308","24","<b>שלג. . השי\"ן</b>: ראה גם סה\"מ תרכ\"ח ע' ב. תרכ\"ט ע' קס. המשך מים רבים שם פקנ\"ז. סה\"מ ליקוט ח\"ב ע' קכ. תרס\"ד מהדורת תשנ\"ד ע' קמא. תרצ\"ז ע' 216."],["5309","25","<b>וכה תעשה להם לטהרם</b>: בהעלותך ח, ז."],["5310","26","<b>ההפרש. . שהכהנים. . קדושה ולוים. . טהורה</b>: ראה לקו\"ת יו\"כ סט, א. סה\"מ תרח\"ץ ע' סג וש\"נ."],["5311","27","<b>הניצוץ האלקי המתלבש בהנשמה</b>: ראה סה\"מ השי\"ת ע' 115 בהערה."],["5312","28","<b>טהורה. . באצי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380824\" data-slug=\"likkutei-torah\" data-id=\"4001380824\">לקו\"ת פ' ראה כז, א</a> ובהנסמן במ\"מ לשם. מאמרי אדה\"א הנחות תקע\"ז ע' רב. וש\"נ."],["5313","29","<b>נשמות דזרע אדם. . דזרע בהמה</b>: ראה תו\"א ותו\"ח ר\"פ משפטים. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה וזהו שרש יונתי על יד הערה 13. סה\"מ תרכ\"ט ע' קכז. וש\"נ. תר\"ל ע' נז ואילך. המשך מים רבים תרל\"ו פמ\"א ואילך. פלח הרמון פקודי ע' שלט ואילך."],["5314","30","<b>וכמ\"ש בפרד\"ס. . בעולם</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערות 7-10."]]],[2000470544,"הוצרכתי לעשות מלאכתי שהרי אברהם עומד במקומי ושומר משמרתי ונת' הפי' במ\"א שהחליף לגמרי את מדת החסד<sup data-n=\"5315\">31</sup> עד שהוא הי' פועל כל פעולת מדת החסד, והאיך הוא הרי אברהם הי' למטה בגוף הגשמי', אלא ע\"כ שהי' למטה ג\"כ דבוק וקשור לאלקות כמו הנשמה בשרשה, ואף שכתי' אברהם אברהם ופסיק טעמא בגווייהו ונת' הפי' בתו\"א<sup data-n=\"5316\">32</sup> שאברהם כמו שירד למטה אינו דומה כמו אברהם בשרשו, היינו מחמת ירידת הנשמה להתלבש בגוף ונה\"ב אבל ע\"י עבודה שלו נעשה למטה בגוף כמו למעלה בשרשו<sup data-n=\"5317\">33</sup>, וזהו כללות העבודה דנשמות דאצי' שהגם שע\"י הירידה נעשה פסיק טעמא הם עושים בעבודתם שלא יהי' פסיק טעמא, אך זהו דוקא נשמות דאצי', אבל נשמות דבי\"ע לא כן עבודתם כמ\"ש במ\"א, אבל מ\"מ שרשם של כל הנשמות הם מאצי' ושם היתה בבחי' טהורה, ובכדי שתתלבשה בגוף ונה\"ב בכדי שיהי' בירור דנה\"ב שזהו עיקר הכוונה, הוצרכה להתלבש בתחילה בעולם הבריאה בכדי שיוכל להקרא עליה בש' גשם הבריאה כי שם בריאה מורה ע\"ש היותו דבר נבדל בעצמו נבדל משרשו, אך הבריאה היא גבוה למעלה במעלתה ממעלת היצירה כי בריאה הוא הנברא ראשון ממקורו ושרשו.\n<b>והענין</b> דהנה אנו אומרים יוצר אור ובורא חושך<sup data-n=\"5318\">34</sup>, ולכאורה הלא בריאה שהיא הגבה למעלה הי' צריך להיות להקרות בשם אור. אך הנה פי' חושך אינו חושך בעצם כי אדרבה שמה הוא ריבוי אור אלא כמו עד\"מ החשך הגשמי' א\"א לראות בו כלום וע\"י אור יכולים לראות וה\"ז מציאות מהות, ועד\"ז הוא עולם הבריאה מחמת ריבוי אור שבו ה\"ה העלם עד שנעלם מעין כל חי וע\"ד מארז\"ל ע\"פ במחשכים הושיבני זה תלמוד בבלי<sup data-n=\"5319\">35</sup>, ולכאורה הלא תלמוד בבלי ה\"ה עיקר המפרש ומבאר כל התורה שבו וע\"י הוא עיקר הבירור ולמה נק' בש' חושך. אלא שנק' בש' חשך ע\"ש שגנוז בו מאד האור וא\"א לבוא על האור שבו כ\"א ע\"י בירור שהם הקושיות שבגמרא ורמינהו או שארי קושיות ותירוצים ועי\"ז מתגלה האור, וא\"כ הרי אדרבה עש\"ז נק' חשך ע\"ש שגנוז בו מאד הריבוי אור, ועד\"ז הוא עולם הבריאה, אבל עולם היצי' אין בו כ\"א רק מיעוט אור עד שהוא בגדר השגה ולכן נק' בש' אור, ודרך כלל בריאה ויצירה הוא כמו חומר<sup data-n=\"5320\">37</sup> וצורה<sup data-n=\"5321\">36</sup> שהחומר אפשר להיות בלתי צורה והצורה א\"א להיות בלתי חומר כי ציור הצורה ה\"ה בהחומר, וא\"כ הצורה הוא",[["5315","31","<b>אברהם. . שהחליף. . מדת החסד</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה גור ארי' יהודה ובהערה 52."],["5316","32","<b>אברהם אברהם ופסיק טעמא. . ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370340\" data-slug=\"torah-or\" data-id=\"3901370340\">תו\"א</a></b>: וירא כב, יא. ראה שמו\"ר פ\"ב, ו. תו\"א משפטים עו, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680295\" data-slug=\"torat-chaim\" data-id=\"2300680295\">תו\"ח תולדות קמו, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550207\" data-slug=\"torat-chaim\" data-id=\"2300550207\">משפטים ח\"ב רעח, ב</a>. וש\"נ. סה\"מ תר\"ל שם ע' נו ואילך."],["5317","33","<b>ע\"י עבודה. . כמו למעלה בשרשו</b>: ראה גם סה\"מ תר\"ל ע' קו."],["5318","34","<b>יוצר אור ובורא חושך</b>: ישעי מה, ז. ראה פע\"ח שער הק\"ש ש\"ח, פ\"א. (לעיל בחלק המאמרים) המשך מצה זו פרק ג\"ן על יד הערה 1555 ואילך. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540181\" data-slug=\"torat-chaim\" data-id=\"2300540181\">תו\"ח בשלח ח\"א קמד, ג</a> הערה 41. סה\"מ תרכ\"ז ע' רפו. וש\"נ."],["5319","35","<b>במחשכים הושיבני. . בבלי</b>: איכה ג, ו. ראה סנהדרין כד, א. לעיל המשך מצה זו שם ובהערה 1558."],["5320","37","<b>חומר וצורה</b>: ראה מו\"נ ח\"א פי\"ז. הנסמן במאמרי אדה\"א דברים ח\"ד ע' קעו. שמות ח\"א ע' כג. סה\"מ תרכ\"ט ע' יז. וש\"נ."],["5321","36","<b>בריאה ויצירה. . חומר וצורה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381187\" data-slug=\"likkutei-torah\" data-id=\"4001381187\">לקו\"ת שה\"ש יד, סע\"ג</a> ואילך."]]],[2000470545,"מצטרך תמיד אל החומר. והנה עשי' הוא מרוחק לגמרי כי מחשבה ודיבור ה\"ה לבושים קרובים עדיין אבל מעשה הרי הוא מרוחק לגמרי כי הנה אנו רואים שכאשר האדם עושה איזה מלאכה הרי בעת עשיית המלאכה הרי המלאכה צ\"ל מחובר אל האדם אז אבל אחר עשיית הכלי ה\"ה נפרד לגמרי מהאדם העושה. ועד\"ז הוא עולם העשי', ולכן כתי' אף עשיתיו, אף הפסיק הענין<sup data-n=\"5322\">38</sup>, וכאשר ירדה הנשמה ע\"י התלבשותה בבי\"ע אח\"כ נתלבשה בגוף האדם וכמ\"ש ויפח באפיו נשמת חיים<sup data-n=\"5323\">39</sup> בכדי לברר הנה\"ב, אבל קודם התלבשותה בבי\"ע כאשר היתה עומדת באצי' היתה בבחי' טהורה שפי' טהור אינו מציאת דבר מה כ\"א שהוא מנוקה מכל דבר והוא ע\"ד שלילה שאין בו שום דבר, וכידועה ההפרש בין טמא לטהור שטמא הוא שנתלבש בלבושים טמאים ושורה עליו אור מקיף דטומאה, אבל הטהור הוא מנוקה לגמרי מכל אלו הלבושים וכמו גוון לבן שהוא גוון עצמי<sup data-n=\"5324\">41</sup> שאין בו דבר נוסף כי הדבר הצבועה<sup data-n=\"5325\">40</sup> הרי הצבע הוא דבר נוסף אבל בגוון לבן הוא גוון עצמי, או כמו בגד לבן שנתלבן מכל הכתמים, וכמו\"כ הו\"ע הנשמה בהיותה עומדת באצי'.\n<b>אך</b> הנה מ\"מ צ\"ל שהנשמה כמו שהיתה באצי' ה\"ה היתה איזה מציאות דבר מה וה\"ז קצת נפרד אך אינו דבר נבדל לגמרי כמו בריאה, שהרי אין שייך לומר שם טהור כ\"א על איזה מציאות דבר מה דאל\"כ על מי יחול שם טהרה וכמו למשל שאומרים על אדם שהוא טהור מכל דבר הרי נופל השם טהור על המציאות, כמו\"כ הנשמה הגם שהיתה בחי' טהורה מ\"מ ה\"ה איזה דבר מה, ובאמת ה\"ה מוכרח לומר כן דהרי כתי' חי הוי' אשר עמדתי לפניו<sup data-n=\"5326\">42</sup> ופי' עמידה למעלה הוא אהוי\"ר וכמ\"ש במלאכים ויעמידם לעד לעולם<sup data-n=\"5327\">43</sup> שהו\"ע עמידתם באהוי\"ר וכמש\"כ<sup data-n=\"5328\">44</sup> נשמות שעמידתם הוא באהוי\"ר, והנה ש' אהבה לא שייך כ\"א לזולתו כי אין שייך לומר שיהי' לאדם אהבה לעצמו והרי ע\"כ האהבה הוא לזולת וכמו\"כ יראה, וא\"כ הרי הנשמה הי' מציאות קצת איזה מהות שעמדה באהוי\"ר, וא\"א לומר דמ\"ש עמדתי קאי על הנשמה כמו שעמדה בגעה\"ת וגעה\"ע שהוא בבריאה ויצי'<sup data-n=\"5329\">45</sup>, שהרי גם נשמות",[["5322","38","<b>אף עשיתיו אף הפסיק הענין</b>: ישעי' מג, ז. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380586\" data-slug=\"likkutei-torah\" data-id=\"4001380586\">לקו\"ת בלק סז, סע\"א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540181\" data-slug=\"torat-chaim\" data-id=\"2300540181\">תו\"ח בשלח ח\"א קמד, ג</a>. וש\"נ."],["5323","39","<b>ויפח באפיו נשמת חיים</b>: בראשית ב, ז."],["5324","41","<b>גוון לבן שהוא גוון עצמי</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380198\" data-slug=\"likkutei-torah\" data-id=\"4001380198\">לקו\"ת אחרי כח, ג</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תפד. וש\"נ. דברים ח\"ד ע' א'רלו-א'רלז. (לעיל בחלק המאמרים) המשך מצה זו על יד הערה 1436."],["5325","40","<b>וכידועה. . הצבועה</b>: כ\"ה בהכת\"י."],["5326","42","<b>חי הוי' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60. לקמן הנחה ד\"ה הנה אנכי כורת ברית על יד הערה 10. לקמן ח\"ב (בחלק ההנחות) הנחה ד\"ה יפה שעה הא' על יד הערה 16. ד\"ה אני לדודי הב' על יד הערה 98. ד\"ה שובה ישראל הא' על יד הערה 77."],["5327","43","<b>ויעמידם לעד לעולם</b>: תהלים קמח, ו. ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א. וש\"נ. לקמן הנחה ד\"ה הנה אנכי כורת ברית בתחילתה. לקמן ח\"ב (בחלק הנחות) הנחה ד\"ה יפה שעה הא' פיסקא אך להבין. ד\"ה אני לדודי (הא') פיסקא ומעתה. (הב') פיסקא ולהבין זה."],["5328","44","<b>וכמש\"כ</b>: אוצ\"ל: וכש\"כ־ או וכמו\"כ."],["5329","45","<b>בגעה\"ת וגעה\"ע. . בבריאה ויצי'</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה כמגדל דוד צוארך ובהערה 10."]]],[2000470546,"דאצי' ה\"ה ג\"כ מרוחקים מהקו<sup data-n=\"5330\">46</sup> וא\"כ אפי' נשמות דאצי' ה\"ה ג\"כ איזה דבר מה ולכן נק' בשם חלק שהחלק מורה ג\"כ על היותו נבדל<sup data-n=\"5331\">*47</sup> כי הרי הוא רק חלק אחד ולא שנים ולא כולו. ובזה יובן מה שהנשמה צריכה לההקרבה דמיכאל דהנה שרש הנשמות הם מגרמוהי, וע\"י ההקרבה מתעלית לחיוהי.\n<b>והענין</b> דהנה אי' איהו וחיוהי חד איהו וגרמוהי חד<sup data-n=\"5332\">47</sup> וצ\"ל למה אמרו ב' פעמים חד הלא חד הוא לשון תרגום<sup data-n=\"5333\">48</sup> וה\"ה כמו תיבת אחד בלה\"ק ופי' אחד הוא אחדות לגמרי כי לכן למדו מצות ליחדו מפ' שמע ישראל<sup data-n=\"5334\">49</sup> הוי' אחד ומבואר במ\"א הקושי' שלכאורה הי' רבותא יותר לומר יחיד<sup data-n=\"5335\">50</sup> והתירוץ ע\"ז שתיבת אחד מורה יותר על אחדותו ית' מתיבת יחיד, וא\"כ לפ\"ז אם נאמר שאותו איהו בעצמו שמתייחד עם חיוהי הוא האיהו שמתייחד עם גרמוהי והיחוד דחיוהי וגרמוהי שוה א\"כ למה אמרו ב\"פ חד. ואין לומר שלכן אמרו ב\"פ חד מפני שהם שמות מחולקים כי חיוהי הוא לפי פי' אחד אורות וגרמוהי הם כלים<sup data-n=\"5336\">51</sup>, ולפי פי' א' חיוהי הוא מוחין וגרמוהי מדות<sup data-n=\"5337\">52</sup>, אבל היחוד דחיוהי וגרמוהי שוה, הרי מ\"מ אינו מובן למה אמרו ב\"פ חד שמאי נפ\"מ אם מתייחד בדבר א' או בשני דברים אם היחוד הוא שוה הי' צ\"ל פעם א' חד. אך ע\"כ צ\"ל דאינו שוה היחוד דגרמוהי להיחוד דחיוהי וממילא יובן שאותו האיהו שמתייחד עם גרמוהי אינו אותו האיהו בעצמו שמתייחד עם חיוהי. והענין דהנה גרמוהי מתאחד עמם אוא\"ס לברוא בהם וע\"י יש מאין<sup data-n=\"5338\">53</sup> והנה הבריאה הוא דבר פלא אשר הוא בחיק הבורא דוקא וכמארז\"ל אלמלא מתכנשין כל באי עולם<sup data-n=\"5339\">54</sup> א\"א לבראות אפי' כנף יתוש א' וליתן בו חיות, ואין הפי' שהנברא יכול ג\"כ להוות קצת אלא שלא יהי' כך טוב כמו ע\"י בריאת הקב\"ה, כ\"א הפי' הוא שהנברא אין יכול",[["5330","46","<b>נשמות. . מהקו</b>: לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן פ\"ו מציין: כמ\"ש באגה\"ק סי' ך' ד\"ה איהו וחיוהי."],["5331","*47","<b>נשמות. . נק' חלק. . נבדל</b>: ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ס\"ע רטו ואילך. ע' רס [שערי תשובה ע, ב ובהערה 20]. המשך תער\"ב ח\"א ע' תרי."],["5332","47","<b>איהו וחיוהי. . וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב. (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח כאן ובהערה 99."],["5333","48","<b>חד הוא לשון תרגום</b>: ראה ת\"א ותיוב\"ע לבראשית א, ה."],["5334","49","<b>מצות ליחדו מפ' שמע ישראל</b>: ואתחנן ו, ד. ראה סהמ\"צ להרמב\"ם מ\"ע ב. ולהצ\"צ נט, ב."],["5335","50","<b>הוי' אחד. . יחיד</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו פנ\"א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א וארא נה, ב</a>. מאמרי אדה\"א בראשית ע' תק. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540489\" data-slug=\"torat-chaim\" data-id=\"2300540489\">תו\"ח שמות ח\"א מז, א</a>. וש\"נ. סה\"מ תרכ\"ז ע' קע. וש\"נ. תרכ\"ט ע' לא. וש\"נ. תש\"ג ע' 66. וש\"נ."],["5336","51","<b>חיוהי. . אורות וגרמוהי הם כלים</b>: ראה לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן ובהערה 100."],["5337","52","<b>חיוהי. . מוחין. . וגרמוהי. . מדות</b>: ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"י. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה הא' פיסקא והנה להבין זה ובפיסקא וביאור: בזהר מפרשי הזהר. (בחלק ההנחות) הנחה ד\"ה יפה שעה הא' על יד הערה 71. סה\"מ תש\"ג ע' 104 בהערה. תש\"ח ע' 161 ובהערה כו. סה\"מ תרל\"ח ע' יד. וש\"נ."],["5338","53","<b>גרמוהי. . לברוא. . יש מאין</b>: ראה אגה\"ק שם."],["5339","54","<b>אלמלא מתכנשין כל באי עולם</b>: ראה ירושלמי סנהדרין ספ\"ז. ספרי ואתחנן ו, ה. ב\"ר פל\"ט, יד. וש\"נ. אוה\"ת בראשית כרך ו ע' 2040. המשך מים רבים תרל\"ו פכ\"ה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261455\" data-slug=\"likkutei-sichot\" data-id=\"1300261455\">לקו\"ש משפטים כרך כו ע' 366</a>."]]],[2000470547,"להוות כלל כי בריאה הוא בחיק הבורא ולא בחיק הנבראים והרי הבריאה הוא דבר פלא מ\"מ הרי הוא מקור התהות הנבראים שהוא מדריגה התחתונה. אבל מחיוהי א\"א להיות אפי' מקור ושרש להתהות הנבראים, וא\"כ היחוד בהם הוא נעלה למעלה מעלה ממעלת היחוד דגרמוהי.\n<b>אך</b> צ\"ל הלא אי' בעה\"ק הוא אינון ואינון הוא<sup data-n=\"5340\">55</sup>, הוא היינו אוא\"ס ואינון קאי על כללות ע\"ס, שכל הע\"ס בשוה גם גרמוהי הם אלקות ממש, אך הענין דהנה בכלים יש ב' בחי' הא' כלים דז\"א דאצי' ועליהם אי' בעה\"ק אינון הוא וכמארז\"ל הוא וחכמתו ורצונו אחד<sup data-n=\"5341\">56</sup>, ובחי' הב' שבכלים הם למ\"ד כלים דז\"א<sup data-n=\"5342\">57</sup> דאצילות כאשר נעשים נר\"נ בבי\"ע ועליהם שייך לומר שאין היחוד דאיהו עמם בשוה לחיוהי. ולפ\"ז יובן העלי' דנש\"י כי שרש נש\"י הם מפנימי' הכלים כידוע ששרש המלאכים הם מחיצוני' הכלים ונשמות ישראל מפנימי' הכלים<sup data-n=\"5343\">58</sup> שהם גרמוהי והעלי' הוא לחיוהי. וצ\"ל לפ\"ז ששרש נשמות ישראל הם מלמ\"ד כלים דז\"א שנעשים נר\"נ לבי\"ע, או אפ\"ל ששרשם מפנימיות הכלים דז\"א כמו שהוא באצי', ואעפי\"כ העלי' שמתעלים לחיוהי הוא גדולה מאוד, כי הגם שאמרו אינון הוא שהם כלים דע\"ס דאצי' מ\"מ כאשר נצרך לומר עליהם שהם אינון ה\"ה קצת דבר בעצמו עד שנצרך לומר עליהם שהם מתייחדין בא\"ס, ואפי' נשמות דאצי' ה\"ה מרוחקים מהקו, וע\"י ירידתן למטה נעשה העלי' אח\"כ לאשתאבא בגופא דמלכא<sup data-n=\"5344\">59</sup> ממש, והגם שנת' במ\"א שנש\"י שהם מפנימי' הכלים הם קרובים לגבי האור<sup data-n=\"5345\">*60</sup> מ\"מ הרי אין זה כ\"א קרובים אבל ע\"י העלי' הם מתייחדים עם האור ויחוד הו\"ע אחר לגמרי מקירוב<sup data-n=\"5346\">60</sup>.\n<b>והנה</b> העלי' הגדולה הוא ע\"י ירידת הנפ\"א להתלבש בגוף ונה\"ב המעלימים ומסתירים, ומגודל ההסתר נעשה תשוקה וצמאון בבחי' ולדבקה בו ית' וכמ\"ש ואתם הדבקים<sup data-n=\"5347\">61</sup> כו', ובכדי להבין זה הנה כתי' אחרי הוי' כו' ובו תדבקון<sup data-n=\"5348\">62</sup> ופרט בכאן ששה דברים ואי' בש\"ך על התורה<sup data-n=\"5349\">63</sup> שהששה דברים הם כנגד שית תיבין",[["5340","55","<b>בעה\"ק הוא אינון ואינון הוא</b>: ראה עבודת הקדש חלק היחוד פ\"ד. (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח כאן פ\"ו הערה 102."],["5341","56","<b>וכמארז\"ל </b>[ וכמאמר רבינו ז\"ל]<b> הוא וחכמתו ורצונו אחד</b>: ראה אגה\"ק סכ\"ו (קמד, א). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381182\" data-slug=\"likkutei-torah\" data-id=\"4001381182\">לקו\"ת שה\"ש יג, ב</a>."],["5342","57","<b>למ\"ד כלים דז\"א</b>: ראה ע\"ח שער הפרצופים ש\"ל, דרוש א. שער השמות שמ\"ד. סה\"מ תרכ\"ט ע' ז. וש\"נ. תרל\"ח ע' שלה. וש\"נ."],["5343","58","<b>המלאכים. . מחיצוני'. . מפנימי' הכלים</b>: ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א ובהערה 16."],["5344","59","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 51."],["5345","*60","<b>שנש\"י שהם מפנימי'. . קרובים לגבי האור</b>: ראה גם מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' נט."],["5346","60","<b>ויחוד הו\"ע אחר לגמרי מקירוב</b>: ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח כאן פ\"ו ובהנסמן שם."],["5347","61","<b>ואתם הדבקים</b>: ואתחנן ד, ד."],["5348","62","<b>אחרי הוי'. . תדבקון</b>: פ' ראה יג, ה."],["5349","63","<b>בש\"ך על התורה</b>: — שפתי כהן לר' מרדכי הכהן — עה\"פ. הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380807\" data-slug=\"likkutei-torah\" data-id=\"4001380807\">לקו\"ת פ' ראה כב, ד</a>. (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח כאן ספ\"ו."]]],[2000470548,"דיחו\"ע דפסוק שמע ישראל<sup data-n=\"5350\">64</sup> וא\"כ ובו תדבקון הוא כנגד הוי' אחד<sup data-n=\"5351\">65</sup>. והענין דהנה שמע הוא מלשון אסיפה וקיבוץ<sup data-n=\"5352\">66</sup> לקבץ כל הכוחות המפוזרים לאלקות, והנה יש בפסוק זה ג' דברים הא' הכנת ההתבוננות הב' עצם ההתבוננות הג' פעולת ההתבוננות. והנה הכנת התבוננות הוא עדיין יש גמור, וגם בעת ההתבוננות הוא עדיין מציאות נבדל שהרי יש מי שמתבונן, ופעולת ההתבוננות הוא הוי' אחד שהו\"ע לדבקה בו ית' שהו\"ע הדבקת באוא\"ס עד שלא יהי' שום מציאות נוסף על עצמותו. וזהו פי' הפסוק שמע הוא ש' עיי\"ן<sup data-n=\"5353\">67</sup> שהו\"ע הבירורים וידוע דענין הבירורים הוא לברר מהיש גמור, הוי' אלקינו הוא כמ\"ש אחרי הוי' אלקיכם תלכון<sup data-n=\"5354\">68</sup> שזהו ש' הוי' שבסדר השתל' ולכן נק' בש' אחרי, והנה ואותו תעבודו הוא ש' הוי' שלמעלה מסדר השתל' וזהו הוי' אחד שהו\"ע הדביקות בא\"ס עצמותו ומהותו ית' עד שאינו דבר נוסף על עצמותו כלל כי פי' דביקה הוא מלשון וטח את הבית<sup data-n=\"5355\">69</sup> וכמו למשל כאשר יטוחו את הבית הרי נראה ונגלה הטיחה עד שיוכל להקרות את הבית על שם הטיחה וה\"ז התדבקות משני דברים שיתאחדו לגמרי, אלא שאין לזה משל בגשמי' שיהי' שני דברים נפרדים לאחדים ממש כי א\"א להיות משל בגשמי' ע\"ז כי ענין הדביקות הוא יחו\"ע שכולו קמי' כלא חשיב<sup data-n=\"5356\">70</sup> ולמטה א\"א למצוא דבר שיהי' לפני זה הדבר כלא חשיב וממילא אינו משל ליחו\"ע כ\"א קצת משל לזה הו\"ע גוון לבן שאינו דבר נוסף על עצמותו, כמו\"כ הו\"ע הדביקות דהוי' אחד והוא ע\"י שמתבונן בתחילה איך ששרש הנשמה היא מד' גבוה שהוא בחי' טהורה והירידה הוא צורך עלי'<sup data-n=\"5357\">71</sup> להתאחד בבחי' חיוהי עי\"ז הוא בא לצמאון לדבקה בו ית'. וזהו ענין ההקרבה דנשמות ישראל.\n<b>והנה</b> ההקרבה דנשמות ישראל מה שמיכאל מקריב הוא הקרבה עליונה וגבוה מאד מההקרבה דארי' דאכיל קרבנין, והענין דהנה כתי' ואם האכל יאכל<sup data-n=\"5358\">72</sup> ארז\"ל בשתי אכילות הכתוב מדבר אחת אכילת מזבח ואחת אכילת אדם, כהנים אוכלים ובעלים מתכפרין<sup data-n=\"5359\">73</sup>. והנה לכאורה אכילת מזבח גבוה מאכילת אדם, אך",[["5350","64","<b>דיחו\"ע דפסוק שמע ישראל</b>: זהר בראשית יח, ב."],["5351","65","<b>ובו תדבקון כנגד הוי' אחד</b>: בש\"ך־ (לעיל בחלק המאמרים) בההמשך כאן ספ\"ו־ אוה\"ת פ' ראה ע' תרפד־ סה\"מ תרל\"ו ח\"ב ע' שמב וע' שנג: כנגד אחד."],["5352","66","<b>שמע. . אסיפה וקיבוץ</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381012\" data-slug=\"likkutei-torah\" data-id=\"4001381012\">לקו\"ת האזינו עב, ב</a>. שע\"ת ס, ג ובהערה 8. לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 147."],["5353","67","<b>שמע הוא ש' עיי\"ן</b>: זהר רע\"מ פינחס רלו, ב. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשמא. וש\"נ. סה\"מ תרל\"ח ס\"ע רכא ואילך. וש\"נ."],["5354","68","<b>תלכון</b>: בהכתוב: תלכו."],["5355","69","<b>וטח את הבית</b>: מצורע יד, מב. ראה גם סה\"מ תרל\"ח ע' קנד."],["5356","70","<b>שכולו </b>[שכולא ]<b> קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["5357","71","<b>והירידה הוא צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["5358","72","<b>ואם האכל יאכל</b>: צו ז, יח. זבחים יג, ב. ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח כאן פ\"ז. וש\"נ."],["5359","73","<b>כהנים אוכלים ובעלים מתכפרין</b>: פסחים נט, ב. ראה גם (לעיל בחלק המאמרים) בההמשך כאן פ\"ז. וש\"נ."]]],[2000470549,"באמת אינו כן שאכילת אדם גבוה הרבה מאכילת מזבח. והענין דהנה אנו רואים דע\"י כח האכילה יכול האדם לעשות מלאכה, דאם לא יאכל מתחלש וע\"י האכילה מתחזק כחו, והנה המאכל בעצמו אינו יכול לעשות כלום כי עיקר העושה הוא האדם אלא מפני שהנשמה ירדה למטה ה\"ה נצרכת להממוצע דהלחם בכדי שע\"י יהי' התחברות הנשמה בגוף, וכמ\"ש באליהו וילך בכח האכילה ההיא ארבעים יום<sup data-n=\"5360\">74</sup>, והרי אליהו הלך בציווי המקום ולמה נצרך ללחם הגשמי', אלא מפני שגם נשמתו נתלבשה למטה בגוף לכן הוצרך להממוצע דלחם וכמ\"ש ולחם לבב אנוש יסעד<sup data-n=\"5361\">75</sup>, ועד\"ז יובן בהלחם נש\"י דהנה הלחם ע\"י אכילת האדם מתעלה בעילוי אחר עילוי שתחילה הי' בחי' חי שהוא רחוק ממעלת האדם וכ\"ש צומח שהוא יותר רחוק, וע\"י האכילה נתכלל ונתהפך להיות במדריגת אדם, ועוד שע\"י האכילה ההיא לומד ומתפלל וה\"ה מקיים רצון העליון שציוה הבורא ית' וא\"כ המאכל נעשה כלי לרצון העליון ב\"ה וה\"ז עלי' גדולה להמאכל. ולפ\"ז יובן ההפרש בין אכילת מזבח לאכילת כהנים כי הנה אכילת מזבח הוא מה שמקריבין בהמה גשמי' והיא מתעלת<sup data-n=\"5362\">77</sup> ונכללת בשרשה בפני שור<sup data-n=\"5363\">76</sup>, אלא שפני שור הוא מהשמאל ועיקר העבודה הוא לאכללא שמאלא בימינא<sup data-n=\"5364\">80</sup>. ולכן מתעלית אח\"כ בבחי' פני ארי'<sup data-n=\"5365\">79</sup> אל הימין<sup data-n=\"5366\">78</sup>, אך צריכים להביא אש גם מן ההדיוט<sup data-n=\"5367\">81</sup> וה\"ז עלי' גדולה מאד. והנה הארי' הוא חיה וא\"כ העלי' הוא מחי לחי, אבל ע\"י אכילת כהנים ה\"ה מתעלה לבחי' אדם וה\"ז עלי' מחי למדבר, ומדבר הוא סוג ומין אחר מבע\"ח, שאין הפי' שמעלת המדבר שיש בו כל המעלות שיש בדצ\"ח<sup data-n=\"5368\">82</sup> ונוסף בו עוד מעלת מדבר דא\"כ גם בבע\"ח יש מדריגות חלוקות שיש לאחד יתרון על חבירו, אלא שמעלת מדבר הוא מד' גבוה ומחולקת לגמרי מדצ\"ח וכמ\"ש ויהי האדם לנפש חיה ות\"א לרוח ממללא<sup data-n=\"5369\">83</sup>. והגם שבבע\"ח כתי' ג\"כ כל אשר נשמת רוח חיים<sup data-n=\"5370\">84</sup> כו' אך זהו ענין אחר לגמרי.\n<b>והנה</b> אדם בגימט' מ\"ה<sup data-n=\"5371\">85</sup> ומ\"ה מברר ב\"ן<sup data-n=\"5372\">86</sup>, ואף שאכילת מזבח הוא ג\"כ מה שמ\"ה מברר ב\"ן אך זהו הבירור בבי\"ע. אבל אכילת אדם דכהנים מגעת עד בירור",[["5360","74","<b>וילך בכח האכילה ההיא ארבעים יום</b>: מלכים-א יט, ח."],["5361","75","<b>ולחם לבב אנוש יסעד</b>: תהלים קד, טו."],["5362","77","<b>מתעלת</b>: כנצ\"ל: מתעלית."],["5363","76","<b>בהמה. . בפני שור</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ח. מאמרי אדה\"א שמות ח\"א ע' כח. וש\"נ. סה\"מ תרל\"ח ע' יח. וש\"נ."],["5364","80","<b>לאכללא שמאלא בימינא</b>: ראה זהר ר\"פ קרח."],["5365","79","<b>בהמה. . בפני שור. . מהשמאל. . פני ארי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380352\" data-slug=\"likkutei-torah\" data-id=\"4001380352\">לקו\"ת במדבר יא, א</a>. סה\"מ תרל\"ח ע' לה."],["5366","78","<b>שפני שור הוא מהשמאל. . ארי' אל הימין</b>: יחזקאל א, י."],["5367","81","<b>להביא אש גם מן ההדיוט</b>: ראה תו\"כ ויקרא א, ז. ערובין סג, א. מאמרי אדה\"א דברים ח\"ד ע' א'תפה. וש\"נ."],["5368","82","<b>המדבר. . שיש בדצ\"ח</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370013\" data-slug=\"torah-or\" data-id=\"3901370013\">תו\"א בראשית ג, ד</a>. מאמרי אדה\"א דברים ח\"ג ע' תתסג. וש\"נ."],["5369","83","<b>ויהי האדם. . לרוח ממללא</b>: בראשית ב, ז ובתרגום אונקלוס שם."],["5370","84","<b>כל אשר נשמת רוח חיים</b>: נח ז, כב."],["5371","85","<b>אדם בגימט' מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670152\" data-slug=\"torat-chaim\" data-id=\"2300670152\">תו\"ח בראשית ט, א</a> הערה 14."],["5372","86","<b>ומ\"ה מברר ב\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."]]],[2000470550,"דמ\"ה דאצי' שמברר ב\"ן דאצי' כי על האדם כתי' נעשה אדם בצלמנו כדמותינו<sup data-n=\"5373\">87</sup> שהו\"ע יחו\"ת ויחו\"ע שהוא ד\"ע ודעת תחתון ובאדם גופא יש ג' בחי' כהנים לוים וישראלים, וכהנים הוא מדריגה הגבוה שבהג' מד' ואכילתו הוא ג\"כ רצון העליון שציוה ית' שיהי' כהנים אוכלים ובעלים מתכפרים ואדם הוא אדמה לעליון<sup data-n=\"5374\">88</sup> שפי' עליון הוא מה שלמעלה מהשכל וגם אדם בגימט' מ\"ה שמ\"ה הוא בלתי מהות<sup data-n=\"5375\">89</sup> לגמרי, ולכן ע\"י אכילת כהנים עי\"ז נעשה הבירור עליון שבאצי' מה שמ\"ה מברר ב\"ן דאצי'. ועד\"ז יובן מה שמיכאל כה\"ר<sup data-n=\"5376\">90</sup> חסד<sup data-n=\"5377\">91</sup> עליון מקריב נשמותיהן של ישראל הוא שע\"י בירור הנה\"ב עי\"ז יתעלה נפש האדם להתייחד בבחי' חיוהי ביחוד ממש. ולפ\"ז אפשר לומר פי' הפסוק אדם ובהמה תושיע הוי'<sup data-n=\"5378\">92</sup> היינו ע\"י בירור הנה\"ב עי\"ז מתעלים גם הנשמות דזרע בהמה להכלל בבחי' אדם מ\"ה דאצי' ועי\"ז תושיע הוי' שנמשך שע\"ה נהורין<sup data-n=\"5379\">93</sup> עילאין. והנה רז\"ל אמרו בני אדם שהם ערומים בדעת כאדם ומשימים את עצמם כבהמה<sup data-n=\"5380\">94</sup>, ואפ\"ל ג\"כ עד\"ז שע\"י בירור הנה\"ב הם ערומים כאדם ועי\"ז באים לביטול דבהמה שהוא למעלה מטעם ודעת<sup data-n=\"5381\">95</sup> והוא מדריגת אדם דלעילא.\n<b>ועפ\"ז</b> יובן הפסוק והנה טוב מאד<sup data-n=\"5382\">96</sup> וארז\"ל טוב זה יצ\"ט מאד זה יצה\"ר<sup data-n=\"5383\">97</sup>, דהנה היצה\"ר הוא תכלית הטוב אלא שהוא גנוז בלבושים רבים, כי כוונת היצה\"ר שלא יתפתה האדם אחריו וכמשל בן המלך עם הזונה<sup data-n=\"5384\">98</sup> שרצון המלך שלא ישמע הבן להזונה וגם רצון הזונה היא שלא יתפתה אחרי' כי עי\"ז היא מתעלית במעלה העליונה, אבל מי שמתפתה אחריו, לבד שאינו משלים רצון המלך אלא שגם רצון היצה\"ר ג\"כ אינו משלים, אלא שהוא צריך לפתות בכל מיני הסתות ופתויים בכל מיני דרכים שאפשר, וע\"י שהאדם כובש את יצרו עי\"ז מתגלה מדריגת מאד, והענין כי טוב הוא הגבלה כמו למשל שאומרים על אדם שהוא טוב ה\"ז הגבלה כי זה",[["5373","87","<b>נעשה אדם בצלמנו כדמותינו</b>: בראשית א, כו."],["5374","88","<b>ואדם אדמה לעליון</b>: ישעי' יד, יד. ראה עבוה\"ק ח\"א חלק היחוד פי\"ז. מאמרי אדה\"א דברים ח\"א ע' קכב. וש\"נ. בראשית ע' קסב. וש\"נ. סה\"מ תרל\"ח ע' שג. וש\"נ."],["5375","89","<b>שמ\"ה הוא בלתי מהות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550183\" data-slug=\"torat-chaim\" data-id=\"2300550183\">תו\"ח תרומה ח\"ב שיב, ב</a> ובהערה 66. (לעיל בחלק המאמרים) מאמר ד\"ה נעשה אדם פ\"ב."],["5376","90","<b>שמיכאל כה\"ר</b>: ראה זהר ס\"ת לך פ, סע\"א ואילך. הנסמן במאמרי אדה\"א בראשית ע' נו."],["5377","91","<b>שמיכאל. . חסד</b>: ראה זהר ויחי רלה, ב. נשא קמה, ב. סה\"מ תרל\"ח ע' קטז. וש\"נ."],["5378","92","<b>אדם ובהמה תושיע הוי'</b>: תהלים לו, ז."],["5379","93","<b>שע\"ה נהורין</b>: נסמן לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח כאן פ\"ז הערה 121."],["5380","94","<b>בני אדם. . כבהמה</b>: ראה חולין ה, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380292\" data-slug=\"likkutei-torah\" data-id=\"4001380292\">לקו\"ת בחוקותי נ, רע\"ג</a>."],["5381","95","<b>לביטול דבהמה שהוא למעלה מטעם ודעת</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380234\" data-slug=\"likkutei-torah\" data-id=\"4001380234\">לקו\"ת אמור לז, א</a>."],["5382","96","<b>והנה טוב מאד</b>: בראשית א, לא."],["5383","97","<b>טוב. . מאד זה יצה\"ר</b>: ילקוט שמעוני בראשית א, לא (רמז טז — ירושלים תשל\"ג ע' 46. וש\"נ). להבא לקמן ראה (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ב."],["5384","98","<b>וכמשל בן המלך עם הזונה</b>: ראה זהר תרומה קסג, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310014\" data-slug=\"tanya\" data-id=\"3401310014\">תניא פ\"ט</a> ופכ\"ט ובמ\"מ הגהות והע\"ק לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680131\" data-slug=\"torat-chaim\" data-id=\"2300680131\">תו\"ח מקץ רטז, ד</a> הערה 67."]]],[2000470551,"הלשון אינו נופל כ\"א על דבר המוגבל אבל מאד הוא בל\"ג<sup data-n=\"5385\">99</sup> ממש. וע\"י שהאדם כובש את יצרו ומעורר אצלו רצון ותשוקה לדבקה בו ית', וע\"ד מה שמצינו בשכם ותדבק נפשו<sup data-n=\"5386\">100</sup> כו' שכם בני חשקה נפשו<sup data-n=\"5387\">101</sup> כו' כי חפץ בבת יעקב<sup data-n=\"5388\">102</sup>, ועד\"ז יהי' לו רצון לאלקות בדביקה וחשיקה וחפיצה<sup data-n=\"5389\">103</sup> עי\"ז מתגלה מאד העליון שהוא בל\"ג ממש ועי\"ז מתעלה הנה\"א במקום אשר לא הי' יכול לבוא שמה מצ\"ע, ולכן היצ\"ט אינו כ\"א רק טוב בלבד אבל היצה\"ר הוא טוב מאד.\n<b>ובזה</b> יובן פי' הפסוק כמים הפנים לפנים, דהנה פי' מים כמ\"ש זכור אב נמשך אחריך כמים<sup data-n=\"5390\">104</sup>, אך זהו גופא יהי' בבחי' פנימי' ולא טבע והסכם בלבד, כי הסכם הוא רצון שהוא רק חיצוני', כ\"א יהי' בבחי' חפץ שהוא פנימי'<sup data-n=\"5391\">105</sup>, וחפצו יהי' לפנימי' אלקות וכמ\"ש לך אמר לבי בקשו פני<sup data-n=\"5392\">106</sup> את פניך כו'. ועי\"ז נמשך לב האדם אל האדם. אך לפ\"ז צריך לפרש לא ע\"ד מה שפי' בהקרבת הקרבנות שזהו ענין המשכת אדה\"ע שעל הכסא לאדם שבמרכבה, אלא ע\"י עבודת האדם מה שמיכאל מקריב נשמותיהן כו' נמשך מבחי' כי לא אדם<sup data-n=\"5393\">107</sup> אלא שנק' בש' אדם עש\"ז כי פי' אדם הוא מלשון אדמה לעליון והגם שפי' עליון הוא למעלה מהשתל' מ\"מ כאשר נופל לומר לשון התדמות לבחי' עליון הרי נופל גם על בחי' עליון לשון אדם, ומבחי' כי לא אדם שזהו האדם נמשך אל האדם דכללות ע\"ס, וע\"י העבודה נעשה המשכת א\"ס דכי לא אדם אל כללות ע\"ס דאצי' ע\"ד שע\"י עבודת האדם מתגלה מאד העליון וע\"ד ובו תדבקון כמו\"כ ע\"י עבודה שמבקש בפנימי' את פנימי' אלקות עי\"ז נמשך לב האדם דכי לא אדם אל האדם דאצי'.",[["5385","99","<b>מאד הוא בל\"ג</b>: ראה אגה\"ק סי\"ז. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370179\" data-slug=\"torah-or\" data-id=\"3901370179\">תו\"א מקץ לט, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540270\" data-slug=\"torat-chaim\" data-id=\"2300540270\">תו\"ח וארא ח\"א סא, ב</a> הערה 69. (לעיל בחלק המאמרים) המשך מצה זו פט\"ו. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פי\"ב. מאמר ד\"ה עשה צדקה ומשפט על יד הערה 21. (בחלק ההנחות) הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 3."],["5386","100","<b>ותדבק נפשו</b>: וישלח לד, ג."],["5387","101","<b>שכם בני חשקה נפשו</b>: וישלח שם, ח."],["5388","102","<b>כי חפץ בבת יעקב</b>: שם לד, יט."],["5389","103","<b>בדביקה וחשיקה וחפיצה</b>: ראה ב\"ר פ\"פ, ז. מדרש תהלים פכ\"ב, ט [כב]. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה עטרת תפארת שיבה על יד הערה 59. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה שם על יד הערה 50. שע\"ת ס, א. אמ\"ב שער התפילין קמה, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600529\" data-slug=\"or-hatorah-hb\" data-id=\"8316600529\">אוה\"ת</a> פ' ראה כרך ו' ס\"ע ב'שכא ואילך. מלאכי כרך א ע' תקכט. סה\"מ תרל\"ו ח\"ב ע' שעג."],["5390","104","<b>זכור אב נמשך אחריך כמים</b>: תפלת גשם. ראה גם המשך תער\"ב ח\"ג ע' א'רפט."],["5391","105","<b>חפץ שהוא פנימי'</b>: ראה שו\"ת הצ\"צ אבהע\"ז ח\"ב סרס\"ג (ח, ג). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש כח, ד</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540822\" data-slug=\"torat-chaim\" data-id=\"2300540822\">תו\"ח בא ח\"א קכה, ד</a> ובהערה 597. סה\"מ ליקוט ח\"ב ע' רעו."],["5392","106","<b>לך אמר לבי בקשו פני</b>: תהלים כז, ח. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380862\" data-slug=\"likkutei-torah\" data-id=\"4001380862\">לקו\"ת תצא לו, ב</a>. הובא (לעיל בחלק המאמרים) המשך מצה זו על יד הערה 600."],["5393","107","<b>כי לא אדם</b>: שמואל-א טו, כט."]]],[2000470552,"<h3>תכון תפלתי</h3>\n<b></b><b>בס\"ד פ' וארא שנת תר\"מ הנחה</b>\nוארא\n<b>תכון</b> תפלתי קטרת לפניך<sup data-n=\"5394\">1</sup> משאת כפי מנחת ערב<sup data-n=\"5395\">2</sup>, ופי' המפרשים<sup data-n=\"5396\">3</sup> שדוד המלך ע\"ה ביקש שנשיאת כפיים יקובל כמנחת ערב שהוא התמיד של בין הערבים, ותפילתו יקובל כקטורת, וצ\"ל מהו הבקשה שיקובל כתמיד של בין הערבים דוקא<sup data-n=\"5397\">4</sup> מהו מעלתו הלא בתורה הם כתובים בשוה כמ\"ש את הכבש א'<sup data-n=\"5398\">5</sup> תעשה בבקר ואת הכבש השני תעשה בין הערבים, ורז\"ל אמרו שפעולתם ג\"כ שוה כי תמיד של שחר<sup data-n=\"5399\">6</sup> מכפר על עבירות של לילה ושל בין הערבים מכפר על עבירות של יום. אך הנה רז\"ל אמרו לעולם יהא אדם זהיר בתפילת המנחה<sup data-n=\"5400\">7</sup> שהרי אליהו לא נענה אלא בתפילת המנחה. אך ג\"ז צ\"ל הלא אדרבא בתפילת השחר יש הרבה אריכות והתבוננות ובמנחה אין שם כ\"א תפלה בלבד ולמה גדלה מעלת המנחה דוקא. וגם צ\"ל הבקשה שיקובל תפילתו כקטורת איזה שייכות יש תפילה לקטורת<sup data-n=\"5401\">8</sup> הלא בגמ' אי' פלוגתא לחד מ\"ד תפלת אבות תקנום וא\"כ אינו שייך תפילה אפי' לקרבנות ומכש\"כ לקטורת ולחד מ\"ד הוא כנגד תמידים<sup data-n=\"5402\">9</sup> מ\"מ ה\"ה רק נגד קרבנות ולא כנגד קטורת. וגם צ\"ל דהלא ידוע דמעלות הקטורת גבהה מאד ואיך ביקש שיקובל תפילתו כקטורת, דבשלמא מה שביקש שיקובל כמו קרבנות ה\"ה דבר שהוא בערך אבל קטרת ה\"ה דבר שאינו בערך כלל. ובכדי להבין כ\"ז צ\"ל דהנה נת\"ל שיש בקרבנות ב' בחי' הא' מה שע\"י הקרבת הקרבן נכללת הבהמה באש שלמטה ובאש שלמעלה<sup data-n=\"5403\">10</sup>, ועי\"ז החיות נושאות את הכסא<sup data-n=\"5404\">11</sup> עם אדם העליון לבחי' כי לא אדם<sup data-n=\"5405\">12</sup>, ובחי' הב' מה שעי\"ז נעשה ריח ניחוח להוי'<sup data-n=\"5406\">13</sup> וכ\"ז הוא עדיין המשכה פנימי' וכמו\"כ בעבודה שהוא תפלה שכנגד תמידין הוא ג\"כ המשכה פנימי'.\n<b>והענין</b> דהנה כתי' אכלתי יערי עם דבשי<sup data-n=\"5407\">14</sup> ונת' בכ\"מ דיערי הוא יוצר אור ודבשי הוא המתיקות דק\"ש. וצ\"ל המשל. והענין דכמו שביער יש עצי",[["5394","1","<b>תכון תפלתי קטרת לפניך</b>: הנחה ממאמר הד' מהמשך זאת חנוכת המזבח [ושם הפתיחה: ”והנה. . אכלתי יערי\" פרקים ח-יו\"ד] שנדפס לעיל בחלק המאמרים. וש\"נ."],["5395","2","<b>תכון תפלתי. . ערב</b>: תהלים קמא, ב."],["5396","3","<b>ופי' המפרשים</b>: מצודת דוד."],["5397","4","<b>וצ\"ל. . הערבים דוקא</b>: להעיר מרד\"ק לתהלים שם: מנחת ערב והוא הדין למנחת הבקר."],["5398","5","<b>את הכבש א'</b>: פינחס כח, ד."],["5399","6","<b>תמיד של שחר</b>: במדב\"ר פכ\"א, כא ובהנסמן במת\"כ שם. מאמרי אדה\"א שמות ח\"ב ע' תקעא. וש\"נ."],["5400","7","<b>לעולם יהא אדם. . המנחה</b>: ברכות ו, ב."],["5401","8","<b>איזה שייכות יש תפילה לקטורת</b>: ראה אוה\"ת מלכים ע' עד. תרכ\"ז ע' נב. וש\"נ. סה\"מ תרמ\"ג ע' סד."],["5402","9","<b>תפלת </b>[תפלות ]<b> אבות תקנום. . תמידים</b>: ברכות כו, ב."],["5403","10","<b>נת\"ל. . ובאש שלמעלה</b>: ראה (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ה."],["5404","11","<b>החיות נושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג."],["5405","12","<b>כי לא אדם</b>: שמואל-א טו, כט. וראה גם לעיל הנחה ד\"ה כמים הפנים בסופה."],["5406","13","<b>הב'. . ריח ניחוח להוי'</b>: ויקרא א, ט<sup data-n=\"e289\">א</sup>. לפנינו ליתא. ואולי הכוונה שבעת אמירת הדרוש נתבאר זה."],["5407","14","<b>אכלתי יערי עם דבשי</b>: שה\"ש ה, א. ראה זהר פינחס רכו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380795\" data-slug=\"likkutei-torah\" data-id=\"4001380795\">לקו\"ת פ' ראה יט, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381266\" data-slug=\"likkutei-torah\" data-id=\"4001381266\">שה\"ש לד, ב</a>.\n\n<b>א</b>  ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301490060\" data-slug=\"likkutei-sichot\" data-id=\"1301490060\">לקו\"ש ויקרא כרך לב ע' 1</a> ואילך."]]],[2000470553,"היער והדבש שבו ויש ב' מיני דבש דבש תמרים ודבש דבורים, דבש תמרים בודאי שייך ליער ואפי' דבש דבורים שייך ג\"כ ליער שעושים כמו יער ומעמידים שמה הדבורים, ובנמשל היער הוא יוצר אור שהו\"ע ההתבוננות משרפים וחיות ואופנים שעומדים בביטול עצום לאלקות, ושרפים אומרים קדוש<sup data-n=\"5408\">15</sup> וחיות ואופנים לעומתם אומרים ברוך<sup data-n=\"5409\">16</sup>, ועי\"ז הוא בא למתיקות דק\"ש מהתבוננות דק\"ש בפסוק ראשון דיחו\"ע<sup data-n=\"5410\">17</sup> דכולא קמי' כל\"ח<sup data-n=\"5411\">18</sup> שהו\"ע יחו\"ע ואח\"כ ההתבוננות דיחו\"ת בפ' בשכמל\"ו<sup data-n=\"5412\">19</sup> האיך שכללות השתל' עולמות לא נתהוה כ\"א רק מזיו והארה בלבד. ונת' במ\"א דפי' שם כבוד מל' הוא כנגד ג' עולמות בי\"ע<sup data-n=\"5413\">20</sup> ששרש התהותם הוא רק מהארה דהארה דהארה שזהו פי' שם כבוד מל'. ועי\"ז בא למתיקות עריבות ידידות נעימות<sup data-n=\"5414\">21</sup> דק\"ש, ואי לזאת הבכן מזה הוא ואהבת<sup data-n=\"5415\">22</sup> כו' אהבה הוא משרש אבה<sup data-n=\"5416\">23</sup> שהוא לשון רצון שיהי' לו רצון בכל לבבך בשני יצריך<sup data-n=\"5417\">24</sup> ביצ\"ט וביצהר\"ע שגם היצה\"ר יהי' לו אהבה להוי', אך איך יבוא היצה\"ר לאהבת הוי' כי הנה היצה\"ר בעצם אינו רע<sup data-n=\"5418\">25</sup> כ\"א שהוא לבוש בלבושים רעים, ולכן בנקל שיבוא ג\"כ לאהבה, ועוד כי נת' במ\"א שהנה\"ב הוא רק כח המתאוה פשוט ואינו מכריח שיתלבש באהבה הבלי עולם וגשמי' העולם כ\"א יכולים להפכו<sup data-n=\"5419\">26</sup> לאהבת הוי'. ובזה יובן מה שנק' ק\"ש בש' דבש דהנה אנו רואים בכמה דוכתא בשו\"ע שפעולת הדבש הוא להפך<sup data-n=\"5420\">27</sup> הדבר שמניחים בו, והוא מפני שעצם הדבש התהותו הוא מדבר שנשתנה ולכן פעולתו ג\"כ לשנות הדבר, וכמו\"כ יובן בק\"ש שמתהפך מן הקצה אל הקצה.",[["5408","15","<b>ושרפים אומרים קדוש</b>: ישעי' ו, ג. ברכת יוצר. ראה חולין צא, ב. ובתוד\"ה ברוך (שם צב, רע\"א)."],["5409","16","<b>וחיות ואופנים. . ברוך</b>: יחזקאל ג, יב. ברכת יוצר. ראה חולין צב, רע\"א ובתוד\"ה ברוך. ראה גם סה\"מ תרל\"ד ע' רנד."],["5410","17","<b>דק\"ש בפסוק ראשון דיחו\"ע</b>: זהר בראשית יח, ב. ראה תו\"א שבהערה 19."],["5411","18","<b>דכולא קמי' כל\"ח</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["5412","19","<b>דיחו\"ת בפ' בשכמל\"ו</b>: זהר בראשית יח, ב. פסחים נו, א. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370514\" data-slug=\"torah-or\" data-id=\"3901370514\">תו\"א ויקהל קטו, ב</a>."],["5413","20","<b>שם כבוד מל'. . בי\"ע</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרמ. ע' תשטו. תקס\"ו ע' טז. סהמ\"צ להצ\"צ ע' קכב. המשך מים רבים תרל\"ו ע' סה."],["5414","21","<b>למתיקות. . ונעימות</b>: ראה אוה\"ח ר\"פ אחרי ד\"ה א\"י עז\"ה. מובא בכ\"מ בדא\"ח ומהם מאמרי אדה\"א בראשית ע' קעו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550246\" data-slug=\"torat-chaim\" data-id=\"2300550246\">תו\"ח תרומה ח\"ב שו, א</a>. וש\"נ."],["5415","22","<b>ואהבת</b>: ואתחנן ו, ה."],["5416","23","<b>אהבה הוא משרש אבה</b>: ראה שרש ישע שרש אבה הובא בס' החקירה להצ\"צ מערכת אהב (צב, רע\"א<sup data-n=\"e290\">ב</sup>). מאמרי אדה\"א הנחות תקע\"ז ע' רסד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540947\" data-slug=\"torat-chaim\" data-id=\"2300540947\">תו\"ח בשלח ח\"א קצט, ב</a>. וש\"נ. סה\"מ תרכ\"ז ע' עב. וש\"נ."],["5417","24","<b>בכל לבבך בשני יצריך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, א במשנה. ראה מאמרי אדה\"א בראשית ע' שסג ואילך. שערי אורה ו, א הערה 9. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פט\"ז."],["5418","25","<b>היצה\"ר בעצם אינו רע</b>: ראה (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ב."],["5419","26","<b>כח המתאוה. . יכולים להפכו</b>: ראה לקו\"ת חוקת נו, סע\"ג ואילך. סה\"מ תרל\"ח ע' קסג. וש\"נ."],["5420","27","<b>שפעולת הדבש הוא להפך</b>: ראה טוא\"ח סרט\"ז. טיו\"ד סוספ\"א. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תרפו ואילך (ובהנסמן בריש המאמר שם). במדבר ח\"ג ע' א'יט. וש\"נ.\n\n<b>ב</b>  במהדורת אותיות מרובעות (תשס\"ג) צד, א."]]],[2000470554,"<b>וכמארז\"ל</b> טוב מאד זה יצה\"ר<sup data-n=\"5421\">28</sup> היינו לאחר הבירור<sup data-n=\"5422\">29</sup> לכן נק' ק\"ש בשם דבש. אך לכאורה הוא לפי הפי' שהיצה\"ר הוא בעצם רע, אבל לפי הפי' שהיצה\"ר הוא בעצם טוב מהו ענין ההתהפכות שלו. אך באמת יתכן גם לפי פי' זה להקרות בש' דבש דהגם שהוא בעצמו טוב מ\"מ הלבושים שלו הם רעים, וצריך להפוך הלבושים שלו ולכן נק' בש' דבש. והנה כללות אה' דק\"ש הוא המשכה פנימי' כי בכל לבבך הוא בנה\"א ובנה\"ב שהם מלובשים בפנימי', ובכל נפשך הוא בכל כוחות הנפש ה\"ה ג\"כ פנימי', ואפי' האהבה דבכל מאדך שהוא אור מקיף אצל האדם שה\"ה בל\"ג מ\"מ ה\"ה ג\"כ רק פנימי' שהרי הבל\"ג הוא ג\"כ לפ\"ע הגבול כי בתחילה מודדים הגבול ויותר מכפי המדה הוא בל\"ג, וא\"כ הבל\"ג הוא ג\"כ על המדה שהוא כלי שהרי אם ימדדו המדה יותר גדולה לא יהי' בל\"ג, ובאמת הרי כתי' בכל מאדך שהוא מאד האדם<sup data-n=\"5423\">30</sup> ולגבי א\"ס הבל\"ג ה\"ה גבול, אלא שמחסד הבורא עלינו נמשך עי\"ז בל\"ג אמיתי אבל באמת ה\"ה למעלה מהגבלת האדם וה\"ה שייך להגבלת הכלי של האדם וא\"כ גם בבל\"ג שלו נגע הכלי וה\"ה ג\"כ או\"פ, ונמצא שק\"ש רובו ככולו הוא או\"פ, ועוד שהרי ק\"ש הוא הכנה לתפילה ותפילה הוא כנגד תמידים שהם או\"פ, והגם שבקרבנות כתי' ג\"כ ריח ניחוח וריח הוא מקיף מ\"מ ה\"ה רק המקיף השייך לפנימי.\n<b>והנה</b> בבהמ\"ק הי' עוד עבודה שהיא הקטורת שהו\"ע הריח ועל ריח ארז\"ל דבר שהנשמה נהנה<sup data-n=\"5424\">31</sup> ולא הגוף כי הנה המאכל אשר יאכל הוא נכנס בקיבה ואצטומכא וה\"ה פנימי' אבל הריח נכנס באף שנכנס בגידי ההרגש שהם נמשכים מהרצון שהרצון אין לו כלי מיוחד בנפש וה\"ה או\"מ, וזהו שאמרו שהנשמה נהנה ולא הגוף כי גם מהמאכל הנשמה נהנה, דהנה אנו רואים שכאשר האדם אוכל מאכל ערב וטעם טעם מתיקות יותר ומי הוא הטועם ה\"ה הנשמה כי הגוף בעצמו בלתי החיות ה\"ה דומם וע\"כ שהטועם הוא החיות, אלא שהמאכל נהנה ממנו רק החיות המתלבש בפנימי' וה\"ז כאלו הגוף טועם אבל מהריח נהנה החיות שאינו מלובש בפנימי' כ\"א המקיף ולזה אמרו ולא הגוף שאינו שייך להגוף והטעם לזה מפני שהריח נכנס לגידי ההרגש ששרשם מרצון שהוא או\"מ<sup data-n=\"5425\">32</sup>, ולכן כאשר לא ירצה האדם להנות מהריח לא יהנה, וכן אנו רואים שכאשר יתעלף האדם, אינם מקיצים אותו במאכל כ\"א בריח<sup data-n=\"5426\">33</sup> שע\"י הריח נעשה התפעלות ומעורר המקיף ועי\"ז יומשך",[["5421","28","<b>טוב מאד זה יצה\"ר</b>: ראה ב\"ר פ\"ט, ז [ושם דורש מתיבת והנה]. סה\"מ תרל\"ח ע' עט."],["5422","29","<b>יצה\"ר. . לאחר הבירור</b>: ראה (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370311\" data-slug=\"torah-or\" data-id=\"3901370311\">תו\"א יתרו סט, ד</a>. סה\"מ תרל\"ח ע' קלה ואילך ובהערה 703. וראה גם מאמרי אדה\"ז תקס\"ד ע' קד ואילך."],["5423","30","<b>בכל מאדך שהוא מאד האדם</b>: ואתחנן ו, ה. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370180\" data-slug=\"torah-or\" data-id=\"3901370180\">תו\"א מקץ לט רע\"ד</a>. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פי\"ב (ובשני ההנחות שם). (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה עשה צדקה על יד הערה 128. ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 152. ד\"ה אשריכם זורעי על כל מים על יד הערה 86. ד\"ה עטרת תפארת שיבה על יד הערה 127. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171115\" data-slug=\"likkutei-sichot\" data-id=\"1300171115\">לקו\"ש שמיני כרך יז ע' 115</a>. סה\"מ תרל\"ח ע' קלו. וש\"נ."],["5424","31","<b>ריח. . דבר שהנשמה נהנה</b>: ראה ברכות מג, ב. ראה גם ש\"א ז, ב. יא, ב."],["5425","32","<b>מרצון שהוא או\"מ</b>: ראה סה\"מ תרל\"ח ע' רנ. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540373\" data-slug=\"torat-chaim\" data-id=\"2300540373\">תו\"ח בא ח\"א פט, סע\"ג</a> ואילך. וש\"נ."],["5426","33","<b>יתעלף האדם. . בריח</b>: ראה גם המשך מים רבים תרל\"ו פ\"ו."]]],[2000470555,"בפנימי' ג\"כ, וזהו\"ע הקטורת שהוא אור מקיף. והנה הקרבנות הי' קריבים במזבח החיצון<sup data-n=\"5427\">34</sup> והקטורת במזבח הפנימי<sup data-n=\"5428\">35</sup> לבד בחנוכת המזבח שהי' הוראת שעה שהקריבו קטורת ג\"כ במזבח החיצון<sup data-n=\"5429\">36</sup>, והענין דהנה ענין החינוך הוא דהנה אנו רואים כאשר מוליכין תינוק לבית הסופר בפעם ראשון נותנים לו מתנות הרבה שלא ע\"ד ההרגל בשארי פעמים והולכים עמו גדולים למלמד דרדקי ושומעים הגדולים שיודעים ללמוד בטוב האיך שמרגילים התינוק<sup data-n=\"5430\">37</sup>, והיינו דבכדי שיוכל התינוק לקבל בפנימי' את הלימוד צריך להמשיך עליו תחילה או\"מ, וע\"י המתנות מרובות וההילוך דגדולים עי\"ז ממשיכים עליו אור מקיף. ועד\"ז יובן בענין חנוכת המזבח שבכדי שיומשך ע\"י הקרבת הקרבנות או\"פ הי' נצרך להמשיך תחילה או\"מ בכדי שיומשך אח\"כ בפנימי', ולכן הקריבו הקטורת לפי שעה במזבח החיצון כי ע\"י הקטורת נמשך או\"מ.\n<b>ובזה</b> יובן מ\"ש הבו לה' כבוד ועוז<sup data-n=\"5431\">38</sup> דלכאורה אינו מובן למה נצרך הקב\"ה לכבודנו הלא כתי' ה' צבאות הוא מלך הכבוד<sup data-n=\"5432\">39</sup>. וע\"י מה נותנים הכבוד. אך הענין דהנה אנו רואים שכבוד הוא בחי' מקיף כמו למשל אדם שמכבד א\"ע הוא מפני שמתחשב<sup data-n=\"5433\">40</sup> א\"ע ליש ודבר ומרומם בעיניו כאלו הוא מובדל מכל עד שאין שום אדם יכול לקרב אליו, וה\"ז בחי' מקיף וכמו\"כ כאשר נותנים לאדם כבוד הרי הכבוד הוא בחי' חיצוניות, והוא מפני שהכבוד הוא בחי' מקיף ומהמקיף א\"א לימשך כ\"א חיצוני', ומה שנותנים לאדם מכובד כבוד והכבוד נוגע לפנימיותו הוא המקיף שנמשך בבחי' פנימי. ועד\"ז יובן למעלה דהנה כתי' כי על כל כבוד חופה<sup data-n=\"5434\">41</sup> שיש ב' בחי' כבוד, כבוד נברא וכבוד נאצל<sup data-n=\"5435\">42</sup>, כבוד נאצל הוא ל\"ב נ\"ח<sup data-n=\"5436\">43</sup> כי כבוד בגימט' ל\"ב<sup data-n=\"5437\">44</sup>, אך הנה כתי' כולם בחכ' עשית<sup data-n=\"5438\">45</sup> שהחכ' נחשב כעשי' גשמי'<sup data-n=\"5439\">46</sup> לפניו שאינו תופס מקום כלל ובכדי שיומשך בפנימי' שהם הז' קולות<sup data-n=\"5440\">47</sup> שהם המשכה בפנימי',",[["5427","34","<b>הקרבנות. . במזבח החיצון</b>: ראה יתרו כ, כא. סהמ\"צ להרמב\"ם מ\"ע פד. רמב\"ם הל' ביהב\"ח פ\"א, ה\"ו. מעשה הקרבנות רפי\"ח."],["5428","35","<b>והקטורת במזבח הפנימי</b>: ראה תצוה ל, א. ז. ח. סהמ\"צ להרמב\"ם מ\"ע כח. רמב\"ם הל' כלי המקדש פ\"א, הי\"א. הל' תמידין ומוספין רפ\"ג."],["5429","36","<b>הוראת שעה. . במזבח החיצון</b>: נשא ז, יד וברש\"י שם ממנחות נ, א."],["5430","37","<b>החינוך. . תינוק. . מתנות. . התינוק</b>: ראה (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א ובהערה 5."],["5431","38","<b>הבו לה' כבוד ועוז</b>: תהלים כט, א."],["5432","39","<b>ה' צבאות הוא מלך הכבוד</b>: תהלים כד, י."],["5433","40","<b>שמתחשב</b>: אוצ\"ל: שמחשיב."],["5434","41","<b>כי על כל כבוד חופה</b>: ישעי' ד, ה."],["5435","42","<b>כבוד נברא וכבוד נאצל</b>: ראה ת\"ז בהקדמה ה, א. ו, ב. מאמרי אדה\"א דרושי חתונה ח\"א ע' ב ואילך. וש\"נ."],["5436","43","<b>כבוד. . הוא ל\"ב נ\"ח</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"א מערכת כבוד. מאמרי אדה\"א בראשית ע' ג ואילך. דברים ח\"ב ע' שפ. וש\"נ."],["5437","44","<b>כבוד בגימט' ל\"ב</b>: זהר רע\"מ צו לג, א."],["5438","45","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["5439","46","<b>שהחכ' נחשב כעשי' גשמי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא פ\"ב</a> בהגהה. (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ח ובהערה 142. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו על יד הערה 85. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה הא' על יד הערה 100. ד\"ה עשה צדקה על יד הערה 131. ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 30. (בחלק ההנחות) הנחה ד\"ה יפה שעה הא' על יד הערה 86."],["5440","47","<b>הז' קולות</b>: תהלים כט, ג ואילך."]]],[2000470556,"צ\"ל<sup data-n=\"5441\">*48</sup> להמשיך תחילה בחי' המקיף דהיינו שיהי' בחי' מקיף דכבוד ועי\"ז נמשך אח\"כ בהמשכה פנימי' דז' קולות, וע\"ד שמצינו בשמחת חתן וכלה נותנים מתנות<sup data-n=\"5442\">48</sup> מרובות שבתחילה נותן אב ואם ואח\"כ נותנים אחרים. והענין דהנה חתן הוא מל' נחות דרגא<sup data-n=\"5443\">49</sup>, דהנה כתי' ע\"כ יעזוב איש את אביו ואת אמו<sup data-n=\"5444\">50</sup>, אב ואם הוא חו\"ב<sup data-n=\"5445\">51</sup>, ומדכתי' יעזוב משמע שתחילה הי' קשורים ודבוקים לחו\"ב דאל\"כ אינו שייך לומר לשון עזיבה, והענין דהנה חתן הוא ז\"א ונק' בש' חתן כי בז\"א הוא הביטול דיחו\"ע כמ\"ש לך הוי' הגדולה<sup data-n=\"5446\">52</sup> שהם בטלים בתכלית לגבי א\"ס ב\"ה. ועיקר הכוונה הוא שיהי' השפעה במל' שזהו מ\"ש ודבק באשתו<sup data-n=\"5447\">53</sup> וכמו שהוא בטל לגבי א\"ס א\"א להיות ממנו השפעה כי איידי דטריד למבלע<sup data-n=\"5448\">54</sup> לא פליט. והכוונה הוא כדי שיומשך במל' בכדי להוליד נשמות חדשות, ופי' חדש הוא התחדשות לגמרי מה שלא הי' עדיין, וההולדה צ\"ל בדומה לו ממש, ומהתחדשות לגמרי שיהי' דומה לו ה\"ז גופא התחדשות גדול, ואפי' נשמות שהי' כבר בעולם ה\"ה נתעלו כבר ובכדי שירדו ויומשכו עוד למטה ה\"ז ג\"כ התחדשות, ובכדי שיהי' הולדה הוא ע\"י שירד החתן ממדריגתו ויעזוב את התקשרותו לחו\"ב, וכלה הוא ג\"כ מל' כלתה נפשי<sup data-n=\"5449\">55</sup> וצ\"ל תחילה שכחי עמך<sup data-n=\"5450\">56</sup> ובית אביך, ולזאת נצרך להמשיך כח מלמעלה מעלה שיהי' הירידה בשניהם ויהי' ההולדה, והגם שהחתן הוא בדרך ירידה והכלה הוא בדרך עלי' מ\"מ הרי הם שניהם שלא במקומם, ולזאת נותנים מתנות מרובות שזה מורה על המשכת המקיף בכדי שיוכל להיות אח\"כ יחוד פנימי, ועד\"ז הו\"ע חנוכת המזבח ולכן הקריבו אז קערות כסף וכפות זהב משא\"כ שארי מנחת נדבה הי' מביאים בכלי נצרים<sup data-n=\"5451\">57</sup>, והו\"ע מתנות מרובות להורות על המשכת המקיף.\n<b>ולפ\"ז</b> יובן ג\"כ מפני מה בחנוכת המזבח כתי' ביום המשח<sup data-n=\"5452\">58</sup> ואח\"כ כתי' אחרי המשח<sup data-n=\"5453\">59</sup>, והענין דהנה שמן הוא פנימי' ובהשמן הי' בשמים ראש ומר דרור<sup data-n=\"5454\">60</sup> שהוא בחי' ריח שהו\"ע מקיף, ומפני שיש בהשמן משני הבחי' מאו\"פ ואו\"מ לכן בו וע\"י נמשך המקיף בפנימי'. והגם שמחמת המקיף בעצמו יוכל לימשך בכ\"מ כי לגבי מקיף אינו תופס מקום, מ\"מ הרי צריך לעשות הכנה שיהי' חומר מוכן",[["5441","*48","<b>צ\"ל</b>: אוצ\"ל: צריך."],["5442","48","<b>בשמחת חתן וכלה נותנים מתנות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380425\" data-slug=\"likkutei-torah\" data-id=\"4001380425\">לקו\"ת נשא כט, ב</a>. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה והוא כחתן ובהערה 50."],["5443","49","<b>חתן. . נחות דרגא</b>: ראה יבמות סג, א."],["5444","50","<b>ע\"כ יעזוב. . ואת אמו</b>: בראשית ב, כד."],["5445","51","<b>אב ואם הם חו\"ב</b>: ראה ע\"ח שער עתיק שי\"ב, פ\"א."],["5446","52","<b>לך הוי' הגדולה</b>: דבהי\"א כט, יא."],["5447","53","<b>ודבק באשתו</b>: בראשית ב, כד."],["5448","54","<b>איידי דטריד למבלע</b>: ראה חולין קח, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצה. תו\"ח נח סג, ג הערה 44."],["5449","55","<b>וכלה. . כלתה נפשי</b>: תהלים פד, ג. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540075\" data-slug=\"torat-chaim\" data-id=\"2300540075\">תו\"ח בשלח ח\"א רח, א</a> ובהערה 19."],["5450","56","<b>שכחי עמך</b>: תהלים מה, יא. ראה מאמרי אדה\"א בראשית ע' שכט ואילך (ובהנסמן בריש המאמר שם)."],["5451","57","<b>מנחת נדבה. . בכלי נצרים</b>: ראה (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ח ובהערה 148."],["5452","58","<b>ביום המשח</b>: נשא ז, פד."],["5453","59","<b>אחרי המשח</b>: נשא ז, פח."],["5454","60","<b>בשמים. . ומר דרור</b>: תשא ל, כג."]]],[2000470557,"לקבל, והשמן עושה במקבל שיהי' חומר מוכן לקבל. ולכן בעת חנוכת המזבח שהו\"ע המשכת המקיף כתי' ביום המשח אותו שאז הי' נצרך השמן לעשות המקבל שיהי' ראוי לקבל, אבל אח\"כ בקרבנות דכתי' כל הבקר לעולה<sup data-n=\"5455\">61</sup> שאז כבר נמשך בפנימי' ואינו נצרך לשמן לכן כתי' אחרי המשח.\n<b>ובזה</b> יובן ענין קריאת שם חנוכה<sup data-n=\"5456\">62</sup> דהלא עיקר הנס הי' שגברו מלכות חשמונאי ולזה הי' נצרך לקבוע השם, ואם מפני שנעשה נס בשמן הי' נצרך לקרות שמן טהור, אך ענין חנוכה הו\"ע א' עם חנוכת המזבח<sup data-n=\"5457\">63</sup>. והענין דהנה ארז\"ל טמאו כל השמנים שבהיכל<sup data-n=\"5458\">64</sup>, דהנה שמן הוא חכ'<sup data-n=\"5459\">65</sup> וכמו שיש חכ' בקדושה כמו\"כ יש חכ' בלעו\"ז<sup data-n=\"5460\">66</sup> ויש חכ' בק\"נ וחכ' דג' קה\"ט, והנה החכ' דלעו\"ז מלבשת ומקפת את חכ' דקדושה כי שם טומאה אינו על הרגש פנימי כ\"א על מקיף, ולכן הרחיקו כל ספרי מוסר לימוד חכ' חיצוני'<sup data-n=\"5461\">67</sup> לגמרי, וכמארז\"ל אימתי מותר ללמוד חכמת יוונית והשיבו בזמן שאינו לא יום ולא לילה<sup data-n=\"5462\">68</sup>, וא\"כ הפי' שאסור ללמוד כלל. ואפ\"ל שהמכוון הוא שביום או בלילה יוכל להדבק ליום או ללילה, וזהו שאינו לא יום ולילה דהיינו להפריד זאת מיום ולילה. ולכן אי' בבינונים שהפגם מלימוד חכ' חיצוני' מטמא את הנפש יותר מכל הפגמים כי מטמא את חב\"ד שבנפשו<sup data-n=\"5463\">69</sup>, לבד ע\"ד מה שלמדו הרמב\"ם ורמב\"ן כמ\"ש שם בבינונים, ולכן ארז\"ל על מינות כל באיה לא ישובון<sup data-n=\"5464\">70</sup>, ולכן אנו רואים שמי שעוסק בחכמות אלו אינו יכול להיות לו כלל איזה שמץ פתיחת הלב והמוח לאיזה דבר אלקות לא בתורה ולא בתפלה ולא לכל דבר הנוגע לעניני אלקות, כי המוח שלו מלא מחכ' זאת, דהיינו שהמשיך ע\"ע או\"מ דטומאה עד שהלביש את המוח והלב מכל צדדיו כאלו אין מקום מאין שיכנוס בו דבר אלקות, והיוונים כאשר נכנסו הסיטו את השמן וע\"י מגעם המשיכו או\"מ דטומאה על כל השמנים גם על שמן המשחה<sup data-n=\"5465\">71</sup> ולא הי' מקום מהיכן שיהי' השראת הקדושה בישראל, ומצאו פך א' של שמן חתום בחותמו<sup data-n=\"5466\">72</sup> של כה\"ג דהנה שמן הוא פנימי' וחותם הוא בכדי שלא יוכל לגשת זר אליו כידוע ענין החותם שעושים",[["5455","61","<b>כל הבקר לעולה</b>: נשא ז, פז."],["5456","62","<b>קריאת שם חנוכה</b>: ראה (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א."],["5457","63","<b>חנוכה. . חנוכת המזבח</b>: ראה גם ש\"א טו, ב ובהערה 21."],["5458","64","<b>טמאו כל השמנים שבהיכל</b>: שבת כא, ב. ראה (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ט כאן ובהערה 158."],["5459","65","<b>שמן הוא חכ'</b>: נסמן (לעיל בחלק המאמרים) כאן פ\"ט הערה 159."],["5460","66","<b>חכ' בקדושה. . חכ' בלעו\"ז</b>: נסמן לעיל שם."],["5461","67","<b>ספרי מוסר לימוד חכ' חיצוני'</b>: ראה גם הל' ת\"ת לאדה\"ז פ\"ג, ה\"ז ובהנסמן בהערות וציונים לשם. (לעיל בחלק המאמרים) כאן פ\"ט ובהערה 161."],["5462","68","<b>חכמת יוונית. . לילה</b>: ראה מנחות צט, ב (הובא בהל' ת\"ת שם)."],["5463","69","<b>בבינונים. . מטמא את חב\"ד שבנפשו</b>: ספ\"ח וראה מ\"מ הגהות והע\"ק שם."],["5464","70","<b>כל באיה לא ישובון</b>: משלי ב, יט. ראה ע\"ז יז, א. כש\"ט קה\"ת סשי\"ט (מב, א)."],["5465","71","<b>גם על שמן המשחה</b>: כ\"ה בהכת\"י. ראה יומא נב, ב. רמב\"ם רפ\"ד מהל' בית הבחירה."],["5466","72","<b>פך. . חתום בחותמו</b>: ראה שבת כא, ב. (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ט כאן הערה 166."]]],[2000470558,"באגרת בכדי שלא יכול לקרות הזולת כ\"א מי שנשלח לו, והאיך הי' חתום הפך ע\"כ שהי' מוקף צמיד פתיל וה\"ז בחי' מקיף, וא\"כ הרי הי' בהיפך<sup data-n=\"5467\">73</sup> משני הבחי' מאו\"מ ואו\"פ, והחותם הי' ממדריגה גבוה שהו\"ע חותמו של כה\"ג ולכן בו וע\"י הי' יכול להיות השראת הקדושה בישראל, ולא הי' בו אלא כדי להדליק יום א' כדרך שנמשך תמיד מאו\"מ על יום א' בבחי' פנימי', ונעשה בו נס והדליקו שמונה ימים שהו\"ע המשכת הבינה שהוא שומר המקיף, כי בינה הוא מקור כל המקיפים<sup data-n=\"5468\">74</sup> וממנו נמשך לכל ז' הימים שהם ז' ימי ההיקף שהם ז\"מ. ובזה יובן קריאת שם חנוכה דעיקר השם הזה לא נתקן על ההצלה הגשמי' כי ע\"ז קבעוהו ג\"כ בגשמי' שמחת מריעים<sup data-n=\"5469\">75</sup>, אלא עיקר שם זה נתקן על רוחני' הדבר, שאילו הי' הצלה בלבד שגברו מלכי חשמונאי מ\"מ לא הי' מקום מהיכן להיות השראת הקדושה בישראל, וע\"ש שמצאו פך של שמן שהפך הזה רומז לב' בחי' דאו\"מ ואו\"פ שזהו ג\"כ ענין חנוכת המזבח ולכן קראו ג\"כ שמו חנוכה להורות שהוא ענין א' עם חנוכת המזבח, ולכן קורין בחנוכה פ' הנשיאים<sup data-n=\"5470\">76</sup>, ונמצא מובן ענין חנוכת המזבח שע\"י שהקריבו הקטורת עי\"ז נמשך או\"מ ועי\"ז הי' נמשך אח\"כ או\"פ בהקרבת הקרבנות דפרים ואילים וכבשים.\n<b>אך</b><sup data-n=\"5471\">77</sup> בכדי שיהי' ההמשכה הי' צ\"ל תחילה ההעלאה ע\"י אהרן כמ\"ש מחוץ לפרכת<sup data-n=\"5472\">78</sup> יערוך אותו אהרן, והענין דהנה אהרן הי' מז' רועים<sup data-n=\"5473\">79</sup> שרועים ומפרנסים את נש\"י. דהנה כמו שהרועה רועה את צאנו במרעה טוב ומחפש מקום הראוי למרעה וכמ\"ש ומשה הי' רועה<sup data-n=\"5474\">80</sup> צאן יתרו אחר המדבר בכדי שיהי' בריאים וחזקים ויוכלו לילך ולרוץ כמקדם, כמו\"כ יובן בעבודה בנש\"י דכדי שיוכלו נשמות דבי\"ע לעלות לאצי' הוא ע\"י אהרן כי אהרן הוא המעלה לנש\"י כמ\"ש בהעלותך את הנרות<sup data-n=\"5475\">81</sup> ובהעלות אהרן את הנרות<sup data-n=\"5476\">82</sup>, נרות הם נש\"י<sup data-n=\"5477\">83</sup> כמ\"ש נר הוי' נשמת אדם<sup data-n=\"5478\">84</sup>, ולכן נק' אהרן שושדמ\"ט<sup data-n=\"5479\">85</sup> שהוא המוליך ומעלה לנשמות דבי\"ע שיתעלו לאצי', כי נשמות דאצי' אינם צריכים לשושבינת דאהרן כי באצי' איהו וחיוהי חד איהו וגרמוהי חד<sup data-n=\"5480\">86</sup> ולכן אינם צריכים לסיוע מהמזלות<sup data-n=\"5481\">87</sup> וכמארז\"ל דלכל נשמות כשמתעלים",[["5467","73","<b>בהיפך</b>: כנצ\"ל: בהפך."],["5468","74","<b>בינה הוא מקור כל המקיפים</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"ג. לקו\"ת להאריז\"ל תהלים סנ\"ג."],["5469","75","<b>קבעוהו. . שמחת מריעים</b>: ראה שו\"ת דברי נחמי' חאו\"ח השלמות לשו\"ע רז\"ל סעת\"ר, ס\"ג [נדפס גם בהוספות לשו\"ע אדה\"ז ח\"ג-ד מהדורת קה\"ת]."],["5470","76","<b>קורין בחנוכה פ' הנשיאים</b>: ראה (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א ובהערה 8."],["5471","77","<b>אך</b>: ראה (לעיל בחלק המאמרים) שם הערה 172."],["5472","78","<b>מחוץ לפרכת</b>: תצוה כז, כא־ אמור כד, ג [בדילוג]."],["5473","79","<b>אהרן הי' מז' רועים</b>: ראה תיקונים לז\"ח קד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201655\" data-slug=\"likkutei-sichot\" data-id=\"1300201655\">לקו\"ש חנוכה כרך כ ע' 643</a>. בהעלותך כרך לח ע' 193."],["5474","80","<b>ומשה הי' רועה</b>: שמות ג, א [בדילוג]."],["5475","81","<b>בהעלותך את הנרות</b>: בהעלותך ח, ב."],["5476","82","<b>ובהעלות אהרן את הנרות</b>: תצוה ל, ח."],["5477","83","<b>נרות הם נש\"י</b>: ראה לקו\"ת ר\"פ בהעלותך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550614\" data-slug=\"torat-chaim\" data-id=\"2300550614\">תו\"ח תצוה ח\"ב שלו, ג</a>. וש\"נ."],["5478","84","<b>נר הוי' נשמת אדם</b>: משלי כ, כז."],["5479","85","<b>אהרן שושדמ\"ט</b>: ראה זהר רע\"מ ויקרא כ, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קג. מאמרי אדה\"א שמות ח\"ב ע' שטו וע' שמ."],["5480","86","<b>איהו וחיוהי. . וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב."],["5481","87","<b>מהמזלות</b>: כ\"ה בהכת\"י."]]],[2000470559,"מלאכים קא סלקין ונחתין עמה לבר מגהורקא דר\"ח<sup data-n=\"5482\">88</sup> דמנפשי' קא סליק, כי ר\"ח הי' גם למטה נשמה דאצי'<sup data-n=\"5483\">89</sup> ולכן לא הי' צריך לסיוע ממלאכים, ולכן כאשר רצה א' להסתכל בעליית ר\"ח אתיין תרין שלהובין דנורא ובטשין לי' לעיני', כי לנשמות דבי\"ע גם הראי' בעלי' דנשמות דאצי' מזקת, וזהו מ\"ש מחוץ לפרכת שהוא בי\"ע יערוך כו'. והענין דהנה פרוכת ת\"א פרסא<sup data-n=\"5484\">90</sup>, והנה יש כמה פרסות וכמ\"ש והבדילה הפרוכת<sup data-n=\"5485\">91</sup> לכם בין הקודש ובין קודה\"ק, והפרסא האמורה כאן הוא הפרסא המפסקת בין בי\"ע לאצי'<sup data-n=\"5486\">92</sup> שהיא מעלמת לגמרי, דהנה כתי' שמש ומגן<sup data-n=\"5487\">93</sup> הוי' אלקים דכמו שהמגן ונרתק מעלים ומסתיר על אור הוי' וקדושתו שהוא הי' הוה ויהי'<sup data-n=\"5488\">94</sup>, דאם הי' מתגלה אור הוי' כמו שהוא לא הי' יכול להיות התהות עולמות ליש ודבר, והכוונה הי' שיהי' עולמות נבראים, ולכן שם אלקי' הוא בגימט' הטבע<sup data-n=\"5489\">95</sup> שנראה עולם כמנהגו נוהג, והגם כי טבע הוא ג\"כ נסים תכופים<sup data-n=\"5490\">96</sup> וכמארז\"ל ע\"פ לעושה נפלאות גדולות לבדו אין בעל הנס<sup data-n=\"5491\">97</sup> מכיר בניסו מ\"מ הרי הוא מלובש בלבושי הטבע, ובכדי שיוכלו הנבראים שמחוץ לפרסא שהם נשמות דבי\"ע להתעלות ויהי' בהם ביטול היש הוא ע\"י אהרן דוקא, וזהו מחוץ לפרכת שהוא חוץ לפרסא יערוך אותם אהרן להכניס אותם בפנים היינו לאצי' ולכן נק' אהרן בש' שושבין.\n<b>אך</b> צ\"ל הלא ענין השושבין הוא בעת החתונה דוקא אבל אח\"כ ה\"ה איש ואשה ולמה הי' נצרך לשושבינות דאהרן בכל יום. אך הענין דז\"ע הטבת הנרות",[["5482","88","<b>דלכל נשמות. . מגהורקא </b>[מגוהרקא ]<b> דר\"ח</b>: ראה ב\"מ פה, ב."],["5483","89","<b>ר\"ח. . נשמה דאצי'</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויהי הענן והחשך על יד הערה 42. סה\"מ תרכ\"ז ס\"ע תסז ואילך. אבל במאמרי אדה\"ז תקס\"ב ח\"ב ע' שפג: ”מהארת האצי' בבריאה ולא מבריאה לבד\". ועד\"ז באוה\"ת מג\"א [מהדורת תש\"נ] ע' ל. וראה גם סידור ערב שבת קסג, א. ש\"א ס\"ע כא ושם: ”להיותו מאותן נשמות שמעה\"ח שלא הי' בעה\"ד\"."],["5484","90","<b>פרוכת ת\"א פרסא</b>: נסמן (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"י הערה 183."],["5485","91","<b>והבדילה הפרוכת</b>: תרומה כו, לג."],["5486","92","<b>הפרסא. . בי\"ע לאצי'</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא."],["5487","93","<b>שמש ומגן</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך."],["5488","94","<b>הוי'. . הי' הוה ויהי'</b>: ראה שער היחוד והאמונה פ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680292\" data-slug=\"torat-chaim\" data-id=\"2300680292\">תו\"ח מקץ ריט, ד</a> הערה 62."],["5489","95","<b>אלקי' הוא בגימט' הטבע</b>: ראה שבילי אמונה — לר' מאיר אבן אלדבי — הנתיב הראשון (ט, ב). פרדס שער הנתיבות שער י\"ב, פ\"ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקעג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540086\" data-slug=\"torat-chaim\" data-id=\"2300540086\">תו\"ח שמות ח\"א לח, א</a> הערה 20."],["5490","96","<b>טבע. . נסים תכופים</b>: ”כ\"כ חכמי המחקר ג\"כ בכוזרי מאמר א' סי' עז ובפירוש האו\"נ [ד\"ה כשירחיק מהם החכמה] שם\" אוה\"ת (יהל אור) תהלים ע' קנד."],["5491","97","<b>לעושה נפלאות. . אין בעל הנס</b>: תהלים קלו, ד. ראה לקח טוב חוקת כא, טו. (מדרש תהלים־ יל\"ש והמכירי לתהלים קלו, ד). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370227\" data-slug=\"torah-or\" data-id=\"3901370227\">תו\"א שמות נ, ג</a>. אוה\"ת פ' ראה ע' תשנה<sup data-n=\"e291\">ג</sup>. (יהל אור) תהלים ע' קנג. סה\"מ תרכ\"ז ע' קסא בשולי היריעה. (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה תעשה לי על יד הערה 69. המשך תער\"ב ח\"ב ע' תתסא. ס\"ע א'קפז ואילך. (סה\"מ תש\"ד ע' 48 וע' 54). ובנדה לא, א עה\"פ תהלים עב, יח. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011273\" data-slug=\"likkutei-sichot\" data-id=\"1300011273\">לקו\"ש קדושים ח\"א ע' 259</a>.\n\n<b>ג</b>  ושם נדפס: ספ\"ז. וצ\"ל: ספ\"ג."]]],[2000470560,"שהי' בין הערבים<sup data-n=\"5492\">98</sup>, והענין דהנה כתיב ויהי ערב ויהי בוקר<sup data-n=\"5493\">99</sup> שתחילה הוא ערב ואח\"כ בוקר, והגם שבאכילת קדשים הלילה הולך אחר היום<sup data-n=\"5494\">100</sup>, זהו דוקא באכילת קדשים אבל בכל הענינים הוא כברייתו של עולם ברישא חשוכא<sup data-n=\"5495\">101</sup> והדר נהורא. והנה ביום הוא בירורי ניצוצות של יום ובלילה הוא בירורי הניצוצות של לילה, וכמ\"ש ותקם בעוד לילה ותתן טרף<sup data-n=\"5496\">102</sup>, טרף הוא רפ\"ח עם הכולל<sup data-n=\"5497\">103</sup>, שהרפ\"ח ניצוצים<sup data-n=\"5498\">104</sup> נפלו בשבירה וצריך לברר ולהעלות אותם, ובין הערבים הוא בירור הניצוצות דיום ולילה, ובכדי שיוכלו הנשמות דבי\"ע לברר על חלקו<sup data-n=\"5499\">105</sup> לזאת נצרך עזר ושושבינת דאהרן, ולכן נצרכים לההעלאה שע\"י אהרן בכל יום כי בכל יום הוא בירור הניצוצות ולזאת ירדה הנשמה, כי הנשמה כמו שהיתה למעלה היתה בבחי' טהורה<sup data-n=\"5500\">106</sup> שהיא נקי<sup data-n=\"5501\">107</sup> מכל דבר שאינו דבר נוסף על עצמותו כי ה\"ה רק חלק אלקה עצמיות אלקות<sup data-n=\"5502\">108</sup> ולמה ירדה למטה להתלבש בגוף ונה\"ב, אלא שלא ירדה כ\"א בשביל הבירורים, ובכדי שיוכלו הנשמות דבי\"ע לברר בכ\"י לזה נצרך לאהרן כה\"ר בכל יום.\n<b>ובזה</b> יובן פי' הפסוק תכון תפלתי קטורת לפניך וכו' שדוד המלך ע\"ה ביקש שבירור הניצוצות שבירור על חלקו<sup data-n=\"5503\">109</sup> יקובל ככללות הבירורים של בין הערבים וזהו משאת כפי מנחת ערב, והכח לזה הוא מ\"ש תפלתי קטורת דכמו שיהי' המשכת פנימי' הוא ע\"י הכח דאו\"מ דקטורת כמו\"כ הכח דקטורת יהי' שיקובל בירור הניצוצות שלו כבירור הכללי דבין הערביים. ובעבודה הו\"ע תפילת המנחה, והענין דהנה תפילת שחרית<sup data-n=\"5504\">110</sup> כאשר מתפלל האדם אינו חידוש כ\"כ כי זהו תיכף בקומו משינתו שאז ה\"ה ברי' חדשה<sup data-n=\"5505\">111</sup>, ואף שזהו רק חידוש הישינות שאינו התחדשות גמור",[["5492","98","<b>הטבת הנרות שהי' בין הערבים</b>: רמב\"ם הל' תמידין ומוספים פ\"ג, ה\"י. הל' עבודת יוה\"כ פ\"ב, ה\"ב ובכ\"מ שם."],["5493","99","<b>ויהי ערב ויהי בוקר</b>: בראשית א, ה. חולין פג, סע\"א במשנה."],["5494","100","<b>שבאכילת קדשים. . היום</b>: חולין שם."],["5495","101","<b>כברייתו. . ברישא חשוכא</b>: שבת עז, ב (כגי') רש\"י. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540050\" data-slug=\"torat-chaim\" data-id=\"2300540050\">תו\"ח וארא ח\"א מט, ג</a> ואילך. הנסמן בסה\"מ תרכ\"ז ע' תנד. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380055\" data-slug=\"likkutei-torah\" data-id=\"4001380055\">לקו\"ת פקודי ג, ד</a> הובא לעיל (בחלק המאמרים) המשך מצה זו פ\"מ על יד הערה 1256."],["5496","102","<b>ותקם. . טרף</b>: משלי לא, טו."],["5497","103","<b>טרף הוא רפ\"ח עם הכולל</b>: ראה פע\"ח שער ק\"ש שעהמ\"ט שט\"ז, פ\"ה. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקלא. מאמרי אדה\"א בראשית ע' קמו. וש\"נ."],["5498","104","<b>שהרפ\"ח ניצוצים</b>: ראה ע\"ח שער רפ\"ח שי\"ח, פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151537\" data-slug=\"likkutei-sichot\" data-id=\"1300151537\">לקו\"ש וישב כרך טו ע' 524</a> (אג\"ק שלו ח\"ב ע' כא). וש\"נ. מאמרי אדה\"א דברים ח\"ד ע' א'קעד. וש\"נ."],["5499","105","<b>לברר על חלקו</b>: כ\"ה בהכת\"י — ראה גם בסמוך על יד הערה 109."],["5500","106","<b>הנשמה. . טהורה</b>: ראה (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"י ובהערה 193."],["5501","107","<b>נקי</b>: אוצ\"ל: נקי'."],["5502","108","<b>חלק אלקה עצמיות אלקות</b>: ראה איוב לא, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540089\" data-slug=\"torat-chaim\" data-id=\"2300540089\">תו\"ח וארא ח\"א נא, ד</a>. וש\"נ."],["5503","109","<b>שבירור על חלקו</b>: ראה גם לעיל על יד הערה 105."],["5504","110","<b>תפלת המנחה. . תפילת שחרית</b>: ראה סדר היום סדר תפלת מנחה (ד\"ה עוד טעם לעניית ע' 32). מובא גם בסה\"מ תרכ\"ז ע' נב, וש\"נ. תרל\"ח ע' תסז בשם המגיד. וש\"נ."],["5505","111","<b>האדם. . ברי' חדשה</b>: ראה שו\"ע אדה\"ז מהדו\"ק דיני נט\"י ס\"ד, ס\"א. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פכ\"ג ובהערה 593."]]],[2000470561,"מ\"מ הרי הוא התחדשות, כי המו\"מ של אתמול כבר עבר וכלא הי' ולא ראה עדיין עולם ולא הי' עדיין משוקע בתאות ורצונות ובאמת הרי תפילה הוא ראשית כל העבודה האלקות<sup data-n=\"5506\">112</sup> וכמ\"ש ראשית עריסותיכם<sup data-n=\"5507\">113</sup> תתנו לכהן<sup data-n=\"5508\">114</sup>, כהן הוא הקב\"ה כמארז\"ל אלקיכם כהן הוא<sup data-n=\"5509\">115</sup> וכמארז\"ל על תפילתו שיהא סמוכה למטתו<sup data-n=\"5510\">116</sup> ואין זה חידוש, אבל מנחה כאשר האדם טרוד ומוטרד כל היום ויש לו יצה\"ר המסית ומדיח וראה עולם עם תאוותיו והוא נפנה מכל ומתפלל מנחה ה\"ז כמו התחדשות, והגם שבתפילה של שחרית הוא אריכות ההתבוננות ובמנחה אינו כ\"א רק תפלה, מ\"מ הרי מחמת זה עצמו התפלה של שחר אינו התחדשות מפני שאז הוא ברי' חדשה ואריכות ההתבוננות, ולכן אלי' לא נענה כ\"א בתפלת המנחה. והענין דהנה אליהו אמר אם הוי' הוא האלקי'<sup data-n=\"5511\">117</sup> לכו אחריו ואם הבעל לכו אחריו וצ\"ל האיך דומה<sup data-n=\"5512\">*118</sup> אותם אליהו, אך הענין הוא דכמו שיש סטרא דקדושה כמו\"כ יש סטרא דלעו\"ז והם מתגברים להיות שוה עם הקדושה, ועיקר העבודה הוא דכמו שהוא שוה, ישבור אותה לגמרי ויוכלל בקדושה. וע\"ד השני שעירים להוי' ולעזאזל שמצותם שיהי' שוים במראה בקומה ובדמים<sup data-n=\"5513\">118</sup> ומ\"מ יהי' גורל של שם עולה בימין<sup data-n=\"5514\">119</sup>. וזהו שאמר אליהו אם הוי' הוא האלקי' לכו אחריו ואם כו' שהחזיר אותם בתשובה לגמרי. ולכן אמרו ב\"פ הוי' הוא האלקים<sup data-n=\"5515\">120</sup> כי ע\"י התשובה שלהם נמשך ב\"פ אנכי שהם הב' חצאים שבכתר<sup data-n=\"5516\">121</sup>. ולפ\"ז צ\"ל שפירש הפסוק לא כמו שפירשו המפרשים שתכון תפילתי כו' ומשאת כפי כו' הם שני דברים, כ\"א שהוא ענין אחד, קטורת עם מנחה, דהנה עיקר מעלת הקטורת הוא מפני שהוא הבירור מלעו\"ז כי בקטורת הי' י\"א סממנים<sup data-n=\"5517\">122</sup> שהוא כנגד י\"א<sup data-n=\"5518\">126</sup> כתרין<sup data-n=\"5519\">123</sup> דמסאבותא<sup data-n=\"5520\">125</sup> שהם י\"א<sup data-n=\"5521\">127</sup> ארורים<sup data-n=\"5522\">124</sup>, וע\"י בירור הקטורת עולה ריח",[["5506","112","<b>האלקות</b>: כנצ\"ל: האלקית."],["5507","113","<b>ראשית עריסותיכם תתנו לכהן</b>: שלח טו, כ [ושם: ראשית עריסותיכם חלה תרימו תרומה]. כא [ושם: מראשית עריסותיכם תתנו לה' תרומה]. ראה ג\"כ אג\"ק כ\"ק אדמו\"ר מהוריי\"צ ח\"ב ע' תקמח."],["5508","114","<b>תתנו לכהן</b>: ראה רמב\"ם הל' בכורים פ\"א ופ\"ה. ובסהמ\"צ מ\"ע קל\"ג."],["5509","115","<b>אלקיכם כהן הוא</b>: סנהדרין לט, א."],["5510","116","<b>תפלתו. . למטתו</b>: ראה ברכות ה, ב."],["5511","117","<b>אם הוי' הוא האלקי'</b>: מלכים-א יח, כא [בהוספת תיבת: הוא, וכ\"ה גם בסמוך]."],["5512","*118","<b>דומה</b>: כ\"ה בהכת\"י."],["5513","118","<b>השני שעירים. . במראה בקומה ובדמים</b>: אחרי טז, ה ואילך. ראה משנה רפ\"ה דיומא סב, א."],["5514","119","<b>גורל של שם עולה בימין</b>: ראה משנה רפ\"ד דיומא לט, א. שם ב."],["5515","120","<b>ב\"פ הוי' הוא האלקים</b>: מלכים-א יח, לט. ראה לקו\"ת ש\"ש סה, ב."],["5516","121","<b>ב\"פ אנכי. . שבכתר</b>: ישעי' מג, כה. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381271\" data-slug=\"likkutei-torah\" data-id=\"4001381271\">לקו\"ת שה\"ש לה, סע\"ג</a>."],["5517","122","<b>בקטרת הי' י\"א סממנים</b>: ראה תשא ל, לד. כריתות ו, א."],["5518","126","<b>כתרין דמסאבותא</b>: ראה זהר סבא משפטים צד, ב. שמיני מא, ב. אחרי ע, א. אד\"ר נשא קמג, סע\"א וריש ע\"ב."],["5519","123","<b>בקטרת הי' י\"א סממנים. . כנגד י\"א כתרין</b>: ראה ע\"ח שבהערה הבאה. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370094\" data-slug=\"torah-or\" data-id=\"3901370094\">תו\"א תולדות כ, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380399\" data-slug=\"likkutei-torah\" data-id=\"4001380399\">לקו\"ת נשא כב, ד</a>. המשך תער\"ב ח\"א ע' תכד."],["5520","125","<b>י\"א כתרין דמסאבותא</b>: ראהד) ע\"ח שם. פע\"ח שער הקדישים ש\"ו, פ\"ד. עמה\"מ שער עולם התהו ש\"ו, פ\"ה. מאמר ד\"ה הללו את ה' כל גוים (שבת חוהמ\"ס) וד\"ה ויתן לך (ש\"פ תולדות) תשכ\"ח."],["5521","127","<b>י\"א ארורים</b>: תבוא כז, טו ואילך. ראה מאמרי אדה\"ז תקס\"ז ע' שלד. הנסמן במאמרי אדה\"א קונטרסים ע' שמב."],["5522","124","<b>י\"א סממנים. . י\"א כתרין. . י\"א ארורים</b>: ראה ע\"ח שער המלכים שי\"א, פ\"י."]]],[2000470562,"ניחוח עד א\"ס עצמותו ומהותו, והנה מנחה הוא גם כן בירור הלעו\"ז דיצה\"ר כי כאשר טרוד ומוטרד כל היום והיצה\"ר מסית ומדיח בכל מיני הפתיות, ואחר כך הוא נפנה להתפלל תפילת מנחה, והרי זה ענין תשובה שהוא החזרת הנפש, ועל ידי זה נעשה טוב מאד ומתגלה על ידי זה גילוי א\"ס כמו על ידי קטורת, וזהו שביקש דוד המלך ע\"ה שיקובל תפלתו כקטורת שהוא תפילת המנחה, ולא דוקא התפילה כ\"א ג\"כ השירות ותשבחות שלו יקובל גם כן כתפילת מנחה שהוא במקום קטורת.",[]],[2000470563,"<h3>איתא כו' הנביאים והכתובים</h3>\n<b>נאמר פורים ש' תר\"ם </b>\nהנחה\nאיתא<sup data-n=\"5523\">1</sup> בירושלמי<sup data-n=\"5524\">2</sup> ובמד\"ר<sup data-n=\"5525\">3</sup> הנביאים והכתובים עתידים להבטל ומגלת אסתר והלכות אין עתידין להבטל. הנה צ\"ל מהו יתרון ומעלה דמגילת אסתר שאין עתידים להבטל לכאורה הלא נביאים וכתובים הוא גילוי יותר גבוה ממגילת אסתר, להבין זאת הנה ארז\"ל במד\"ר שמות פ\"ב<sup data-n=\"5526\">4</sup> אסתר ירקרקות היתה<sup data-n=\"5527\">5</sup> אלא שחוט של חסד משוך עלי', והענין הוא הנה כתי' שקר החן והבל היופי<sup data-n=\"5528\">6</sup> אשה יראת היא תתהלל, וארז\"ל במד\"ר<sup data-n=\"5529\">7</sup> שקר החן זה דורו של משה והבל היופי זה דורו של יהושע אשה יראת ה' היא תתהלל זה דורו של חזקי', איכא דאמרי שקר החן זה דורו של משה ויהושע הבל היופי זה דורו של חזקי' אשה יראת ה' זה דורו של ר' יהודה ב\"ר אלעאי.\n<b>הנה</b> כתיב אם לא תדעי לך היפה בנשים<sup data-n=\"5530\">8</sup>, פי' היפה בנשים גימט' ארור המן ברוך<sup data-n=\"5531\">9</sup> מרדכי<sup data-n=\"5532\">10</sup>. להבין זאת הנה מצינו שלפעמים נק' כנס\"י בשם רחל<sup data-n=\"5533\">11</sup> ולפעמים",[["5523","1","<b>איתא בירושלמי ובמד\"ר הנביאים והכתובים</b>: הנחה ממאמר כ\"ק אדמו\"ר מהר\"ש.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפס לעיל (בחלק הנחותיו). וראה בהנסמן שם בריש המאמר."],["5524","2","<b>איתא בירושלמי. . ומגילת אסתר והלכות. ֿ. להבטל</b>: ראה שם מגילה פ\"א, ה\"ה."],["5525","3","<b>ובמד\"ר</b>: עד\"ז הובא גם לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן."],["5526","4","<b>במד\"ר שמות פ\"ב</b>: כ\"ה בהכת\"י."],["5527","5","<b>אסתר ירקרקות היתה</b>: ראה מגילה יג, א."],["5528","6","<b>שקר החן והבל היופי</b>: משלי לא, ל."],["5529","7","<b>וארז\"ל במד\"ר</b>: ראה סנהדרין כ, א. ילקוט שמעוני שמואל-א כה, מד (רמז קלו)."],["5530","8","<b>אם לא תדעי לך היפה בנשים</b>: שה\"ש א, ח."],["5531","9","<b>היפה בנשים גימט' ארור המן ברוך מרדכי</b>: ראה בדרושים שבהערה הבאה: גימט' ארור המן וגם גימ' ברוך מרדכי."],["5532","10","<b>היפה בנשים גימט' ארור המן ברוך מרדכי</b>: מובא גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158100043\" data-slug=\"or-hatorah-hb\" data-id=\"8158100043\">אוה\"ת שה\"ש ח\"א ע' קלו<sup data-n=\"e292\">א</a></sup>. שם כרך ג ע' תתמו וע' תתנח. סה\"מ תרכ\"ז ס\"ע קפז. ע' קפט. ע' קצא. תרכ\"ח ס\"ע קד. ראה גם לקוטי לוי יצחק הערות לזהר ח\"ש ריש ע' פד."],["5533","11","<b>נק' כנס\"י בשם רחל</b>: ראה זהר וארא כט, ב. ב\"ר פע\"א, ב. תניא פמ\"ה. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370425\" data-slug=\"torah-or\" data-id=\"3901370425\">תו\"א מג\"א צד, ד</a>.\n\n<b>א</b>  נדפס גם באוה\"ת ואתחנן ע' תלג."]]],[2000470564,"בשם אסתר<sup data-n=\"5534\">12</sup> וכתי' ורחל היתה יפת תואר ויפת<sup data-n=\"5535\">13</sup> מראה<sup data-n=\"5536\">14</sup>, פי' יפת תואר בציור האברים לפי תכונתם במדתם ובמזיגתם שכל אבר הוא במדידה, ויפת מראה בזיו הוד קלסתר פנים, וע\"כ אנו רואים שיש בנ\"א שהם בתואר האברים בתכלית היופי ובמראה אינם ביופי, ויש בני אדם שהם במראה פנים בתכלית היופי ותואר האברים אינו במדידה יפה, ובעבודה תואר קאי על מ\"ע כי רמ\"ח פקודין רמ\"ח אברים דמלכא<sup data-n=\"5537\">15</sup> שיהי' קיום מ\"ע כדבעי למהוי שלא יעשה בקרירות כמצות אנשים מלומדה<sup data-n=\"5538\">16</sup> ולא עוד שיעשה<sup data-n=\"5539\">*17</sup> כדבעי. ומראה קאי על שמירת מל\"ת כי מל\"ת תלוים בי\"ה<sup data-n=\"5540\">17</sup> וכתי' חכמת אדם תאיר פניו<sup data-n=\"5541\">18</sup> שהארת הפנים נמשך מחכמה וע\"כ אנו רואים שבמצות ל\"ת לא נמצא כלים שע\"י כלים א\"א להמשיך רק ע\"י שלילה דלא<sup data-n=\"5542\">19</sup> כו', אך כ\"ז היינו תואר ומראה, וענין יפת תואר ויפת מראה, יפת תואר קאי על מזיגת והתכללות המדות כי רמ\"ח היינו מבחי' ז\"א שז\"א הוא בעל ט' ספירות וטפ\"ט פ\"א וראש תוך וסוף הוא רמ\"ג וה\"ח<sup data-n=\"5543\">20</sup> המגדילים הוא רמ\"ח פקודין ומדות נמשכין מהשכל וצריך להמשיך מוחין במדות כדי שתהי' התכללות המדות כמו שאנו רואים שעיקר היופי כאשר יש התכללות מכמה גוונים דמדבר א' לא נמצא בזה יופי אלא כאשר הוא כלול מכמה גוונים אז יש בזה יופי, כך עיקר היופי היינו שיהי' התכללות המדות חסד שבגבורה וגבורה שבחסד<sup data-n=\"5544\">21</sup> והיינו כאשר ממשיכים מוחין במדות אז אפשר להיות התכללות המדות, ויפת מראה היינו כאשר נמשך מלמעלה מן השכל, מה שאנו אומרים כי מדות נמשכים מהשכל זהו רק הנהגת המדות שהנהגת המדות נמשכים מהשכל אבל בעצם שרש המדות הוא מלמעלה מהשכל<sup data-n=\"5545\">22</sup>, ומראה היינו חכמת אדם תאיר פניו ויפת מראה היינו כאשר נמשך מלמעלה מהשכל כי שרש המדות הוא מלמעלה מהשכל.\n<b>וכ\"ז</b> הוא בזמן הבית כאשר קיימו מ\"ע ומל\"ת שאז נק' כנס\"י רחל יפת תואר ויפת מראה דהיינו קיום מ\"ע ומל\"ת, וע\"כ נאמר ויאהב יעקב לרחל<sup data-n=\"5546\">23</sup> מפני",[["5534","12","<b>נק' כנס\"י. . בשם אסתר</b>: ראה תו\"א שם צג, ד. צד, רע\"ד. מאמרי אדה\"א נ\"ך ע' תצג. וש\"נ."],["5535","13","<b>ורחל היתה יפת תואר ויפת מראה</b>: ויצא כט, יז."],["5536","14","<b>יפת תואר ויפת מראה</b>: ראה רש\"י ויצא שם. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קסט וע' 11 ואילך. תו\"ח ויצא קעד, ג ואילך. (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 10."],["5537","15","<b>רמ\"ח פקודין רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא</a> רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["5538","16","<b>כמצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נג, ב</a>). (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 12."],["5539","*17","<b>שיעשה</b>: אוצ\"ל: אלא שיעשה."],["5540","17","<b>מל\"ת תלוים בי\"ה</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם ובהערה 124."],["5541","18","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["5542","19","<b>שבמצות ל\"ת. . ע\"י שלילה דלא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380067\" data-slug=\"likkutei-torah\" data-id=\"4001380067\">לקו\"ת פקודי ו, ד</a>."],["5543","20","<b>שז\"א הוא בעל ט' ספירות. . וה\"ח</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"ו. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370172\" data-slug=\"torah-or\" data-id=\"3901370172\">תו\"א מקץ לז, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">שע\"ת מב, ב</a> ובהערה 13."],["5544","21","<b>התכללות מכמה גוונים. . חסד שבגבורה וגבורה שבחסד</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 19."],["5545","22","<b>שרש המדות הוא מלמעלה מהשכל</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע שלא ואילך. סה\"מ תרל\"ח ע' שע. וש\"נ."],["5546","23","<b>ויאהב יעקב לרחל</b>: ויצא כט, יח [ושם: את רחל]. ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 29."]]],[2000470565,"שיעקב היה בריח התיכון<sup data-n=\"5547\">24</sup> שמבריח מן הקצה אל הקצה מקצה השמים דלעילא כו' וממשיך למטה מטה כו' וע\"כ ויאהב את רחל הגם שלאה היא עלמא דאתכסי'<sup data-n=\"5548\">25</sup> שהוא בחי' גבוה יותר, מ\"מ ויאהב את רחל מפני שעיקר המכוון שיומשך בעלמא דאתגליא<sup data-n=\"5549\">26</sup> דוקא וע\"כ אלה תולדות יעקב יוסף<sup data-n=\"5550\">27</sup> שעיקר הגילוים של יעקב הוא ע\"י יוסף דוקא מפני שנולד מרחל שהיא עדאת\"ג. אבל בזמן הגלות נק' בשם אסתר כי בזמן הגלות הוא בתכלית ההסתר וההעלם, לא שלא נמצא כלל אלא שיש כל הגילוים בזמן הגלות ג\"כ רק שהוא בתכלית ההסתר וההעלם, אך ההסתר הוא ג\"כ אלקות כמ\"ש אכן אתה אל מסתתר<sup data-n=\"5551\">28</sup>, שאל מסתתר הוא מבחי' אתה. וזהו אם לא תדעי לך היפה בנשים, פי' היפה בנשים גימט' שני אבות<sup data-n=\"5552\">29</sup> תק\"ב<sup data-n=\"5553\">30</sup>, כי מעשה אבות סימן לבנים<sup data-n=\"5554\">31</sup>, אם לא תדעי ע\"ד עד דלא ידעי<sup data-n=\"5555\">32</sup> בין ארור המן לברוך מרדכי פי' ברוך מרדכי היינו מ\"ע וארור המן מל\"ת ואפי' בזמן הגלות דלא ידעי מ\"מ ע\"י יפת תואר ויפת מראה מ\"ע ומל\"ת אפשר להמשיך המשכת אלקות, וע\"כ ארז\"ל אסתר מן התורה מנין<sup data-n=\"5556\">33</sup> דכתי' אנכי הסתיר אסתיר<sup data-n=\"5557\">34</sup> פני ביום ההוא שאפי' בחי' ביום ההוא הוא ג\"כ בהסתר. וזהו שקר החן והבל היופי פי' שקר החן היינו דורו של משה כי בדורו של משה הי' רק אתעדל\"ע בלא אתעדל\"ת כמו יצי\"מ וקרי\"ס שכ\"ז הי' גילוי מלמעלה בלא אתעדל\"ת רק מפני נשיאת חן, והבל היופי כי הנה הבל הבלים אמר קהלת<sup data-n=\"5558\">35</sup> כי הכל הבל ז' הבלים כנגד ז' ימי בראשית שהוא בחי' ז' מדות והם ג\"כ הבל וזהו והבל היופי בחי' יפת תואר, אשה יראת ה' היא תתהלל היינו דורו של ר' יהודה ב\"ר אלעאי שאז הי' גזירות ושמדים מ\"מ למדו תורה במס\"נ וזהו עיקר המכוון שדוקא מתוך ההסתר ע\"כ היא תתהלל. וזהו",[["5547","24","<b>שיעקב היה בריח התיכון</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["5548","25","<b>שלאה היא עלמא דאתכסי'</b>: ראה הערה הבאה."],["5549","26","<b>רחל. . בעלמא דאתגליא</b>: ראה זהר סתרי תורה ויצא קנב, א. וארא כט, ב. ע\"ח שער מוחין דצלם שכ\"ג, פ\"ד."],["5550","27","<b>אלה תולדות יעקב יוסף</b>: וישב לז, ב. ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 40."],["5551","28","<b>אכן אתה אל מסתתר</b>: ישעי' מה, טו. ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 33."],["5552","29","<b>היפה בנשים גימט' שני האבות תק\"ב</b>: מובא בכ\"מ ומהם: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640136\" data-slug=\"or-hatorah-hb\" data-id=\"8316640136\">אוה\"ת שה\"ש ח\"א ע' קלו</a> וע' קלט. שם כרך ג ע' תתמו. וש\"נ. לעיל הערה 10. סה\"מ תרכ\"ו ע' רג. פלח הרמון אחרי ע' ריא."],["5553","30","<b>שני האבות תק\"ב</b>: שאברהם חי קע\"ה שנה ויצחק ק\"פ ויעקב קמ\"ז שהוא תק\"ב (סה\"מ תרכ\"ז ע' קצא)."],["5554","31","<b>מעשה אבות סימן לבנים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370121\" data-slug=\"torah-or\" data-id=\"3901370121\">תו\"א וישלח כו, רע\"א</a>. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' צא. רמב\"ן לך יב, ו. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251123\" data-slug=\"likkutei-sichot\" data-id=\"1300251123\">לקו\"ש תולדות כרך כה ע' 123</a>. וש\"נ."],["5555","32","<b>עד דלא ידעי</b>: מגילה ז, ב."],["5556","33","<b>אסתר מן התורה מנין</b>: חולין קלט, ב."],["5557","34","<b>אנכי הסתיר אסתיר</b>: וכ\"ה בסמוך בפנים<sup data-n=\"e293\">ב</sup> — וילך לא, יח [ושם: ואנכי הסתר<sup data-n=\"e294\">ג</sup>]."],["5558","35","<b>הבל הבלים אמר קהלת</b>: קהלת א, ב. קה\"ר וילקוט שמעוני עה\"פ. שוח\"ט רפצ\"ב.\n\n<b>ב</b>  ראה גם לקמן הנחה ד\"ה ויהי בימי אחשורוש על יד הערה 9. (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) שם על יד הערה 15.\n\n<b>ג</b>  וכ\"ה בסמוך בפנים."]]],[2000470566,"אסתר ירקרקות היתה רק שחוט של חסד משוך עלי' מפני כי שקר החן והבל היופי כו'.\n<b>עפ\"ז</b> יובן מרז\"ל נביאים וכתובים עתידים להבטל<sup data-n=\"5559\">36</sup> מפני כי ענין נביאים היינו שממשיכים המשכה מעלמא דאתכסיא בעדאת\"ג ובד\"כ המשכה היינו רק הארה ולא עצם אבל לע\"ל שיהי' גילוי עצם עדאתכ\"ס שרגא בטיה' מאי אהני'<sup data-n=\"5560\">37</sup> ע\"כ תתבטל שאינו צריך לזה, כמ\"ש ואמר ביום ההוא<sup data-n=\"5561\">38</sup> הנה אלקינו זה פי' זה הוא בחי' גילוי והוא בחי' סתים ולע\"ל שבחי' הוא סתים יהי' בבחי' זה גילוי שיאיר מבחי' עלמין סתימין בעדאת\"ג ע\"כ נביאים וכתובים עתידים להבטל, אבל אסתר לא תבטל כמ\"ש אנכי הסתר אסתיר פני ביום ההוא שאפי' ביום ההוא לע\"ל יהי' בבחי' הסתר והעלם ע\"כ לא תבטל וכן חמשה חומשי תורה ג\"כ לא תיבטל כמ\"ש וזכרו לא יסוף מזרעם<sup data-n=\"5562\">39</sup> ובמ\"ת כתי' קול גדול ולא יסף<sup data-n=\"5563\">40</sup> פי' התרגום לא פסיק וכמו שמ\"ת לא פסיק כך מגילת אסתר לא תיבטל, נביאים וכתובים עתידים להבטל מפני שלע\"ל יהי' גילוי עצם מעדאתכ\"ס ע\"כ תיבטל כמו שרגא בטיהרא מאי אהני, אבל מגילת אסתר לא תיבטל מפני שאפי' ביום ההוא יהי' ג\"כ בבחי' הסתר והעלם אנכי הסתר ע\"כ צריך להמשיך וע\"כ לא תיבטל כו'.",[["5559","36","<b>נביאים וכתובים עתידים להבטל</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 35."],["5560","37","<b>שרגא בטיה' מאי אהני'</b>: חולין ס, ב."],["5561","38","<b>ואמר ביום ההוא</b>: ישעי' כה, ט."],["5562","39","<b>וזכרו לא יסוף מזרעם</b>: אסתר ט, כח [ושם: וזכרם]. ראה ירושלמי מגילה פ\"א, ה\"ה."],["5563","40","<b>קול גדול ולא יסף</b>: ואתחנן ה, יט."]]],[2000470567,"<h3>ויהי בימי אחשורוש</h3>\n<b>נאמר עוד הפעם פורים</b>\n<b>ויהי</b> בימי<sup data-n=\"5564\">1</sup> אחשורוש<sup data-n=\"5565\">2</sup> כו' ואח\"כ כתי' ויאמר המן למלך אחשורוש<sup data-n=\"5566\">3</sup> ואיתא במדרש<sup data-n=\"5567\">4</sup> שהמן הוא מדת הדין אחשורוש שראשית ואחרית שלו<sup data-n=\"5568\">5</sup>. אך לכאורה צ\"ל הלא כל מקום שנאמר ויהי אינו אלא לצרה<sup data-n=\"5569\">6</sup> ר\"ל ואיך אנו אומרים שראשית ואחרית שלו הלא זה קאי על הקב\"ה כו'. והענין הוא הנה איתא בזוהר שתיבת ו\"י<sup data-n=\"5570\">7</sup> יו\"ד קאי על",[["5564","1","<b>ויהי בימי אחשורוש</b>: הנחה ממאמר כ\"ק אדמו\"ר מהר\"ש. הנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפס לעיל (בחלק הנחותיו). וראה הנסמן שם בריש המאמר.\nבהכותרת כאן נרשם: נאמר עוד הפעם פורים. השווה הכותרת לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן."],["5565","2","<b>ויהי בימי אחשורוש</b>: אסתר א, א."],["5566","3","<b>ויאמר המן למלך אחשורוש</b>: אסתר ג, ח."],["5567","4","<b>ואיתא במדרש</b>: ראה (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 3."],["5568","5","<b>אחשורוש שראשית ואחרית שלו</b>: ראה לעיל שם ובהערה 5."],["5569","6","<b>כל מקום שנאמר ויהי אינו אלא לצרה</b>: ראה פתיחתא דאסת\"ר יא־ ילקוט שמעוני לך יד, א רמז עב (מהדורת ירושלים תשל\"ג ע' 275. וש\"נ). לעיל שם ובהערה 7."],["5570","7","<b>איתא בזוהר שתיבת ו\"י</b>: ראה גם לעיל שם בפנים ובהערות."]]],[2000470568,"השפעה שנמשך בעולמות וכאשר הוא\"ו ממשיך היו\"ד אז נק' וי. והנה בתוכחה מצינו שלפעמים נאמר הוי ולפעמים אוי<sup data-n=\"5571\">8</sup>, ולהבין ההפרש בין הוי לאוי, הנה כתי' אנכי הסתיר אסתיר פני'<sup data-n=\"5572\">9</sup> כו' קודב\"ה בגלותא סליק לעילא ולעילא<sup data-n=\"5573\">10</sup>, לעילא היינו בחי' הסתיר כי רחל מבכה על בני' כי איננו<sup data-n=\"5574\">11</sup> ואיתא בזוהר כי אינה מיבעי לי'<sup data-n=\"5575\">12</sup> שהוא\"ו מיותר אלא שהוא\"ו היינו בחי' ז\"א<sup data-n=\"5576\">13</sup> כי איננו היינו שז\"א אינו מאיר במל' וסליק לעילא היינו בבינה, והיינו בחי' הסתיר שה' היינו ה' עילאה בחי' בינה<sup data-n=\"5577\">15</sup>, ולעילא היינו אסתיר<sup data-n=\"5578\">14</sup> שאלף קאי על בחי' כתר<sup data-n=\"5579\">16</sup> וסליק בבחי' כתר ומצד זה אפשר להיות שיומשך גם למקום שאינו ראוי אם צדקת מה תתן לו<sup data-n=\"5580\">17</sup> ורבו פשעיך מה תעשה לו<sup data-n=\"5581\">18</sup> מה מידך יקח<sup data-n=\"5582\">19</sup> שאינו תופס מקום כלל ע\"כ משם אפשר להיות גם ויהי כו' וזהו הוי ואוי שהוי קאי על בחי' הסתיר ואוי קאי על אסתיר שמצד בחי' אוי אינו תופס מקום כלל ע\"כ א\"ל ויהי כו'.\n<b>והסימן</b> לזה המלך מהדו ועד כוש<sup data-n=\"5583\">20</sup> שארז\"ל (מגילה י\"א<sup data-n=\"5584\">21</sup> ) מהודו מסוף העולם ועד כוש עד סופו וח\"א כחדא נינהו כשם שמולך מהודו ועד כוש כך הוא מולך מסוף העולם ועד סופו, הנה הודו היינו בחי' ד\"ע סוכ\"ע ששם אינו מושג ע\"פ השכל אלא ע\"י בחי' הודאה וביטול שהגם שאינו משיג ע\"פ השכל מ\"מ מודה שכך הוא, וכוש קאי על בחי' אלביש שמים קדרות<sup data-n=\"5585\">22</sup> ושק אשים כסותם שתכלית ההסתר וההעלם שמשם אם צדקת אפשר להיות יניקת החיצוני' וזהו לפי מד\"א שפי' מהודו ועד כוש מסוף העולם ועד סופו שרחוקים זמ\"ז כך בחי' הודו ועד כו\"ש רחוקים זמ\"ז, ולפי מד\"א כחדא נינהו פי' כוש היינו בחי' ישת חשך סתרו<sup data-n=\"5586\">23</sup> שמצד ריבוי אור א\"א להתגלות כמו כבני כושיים אתם לי<sup data-n=\"5587\">24</sup>, מפני שהיו מלובנים ביותר ע\"כ נק' כושיים שמי שמלובן ביותר נק' כושי<sup data-n=\"5588\">25</sup> א\"כ לפי פי' זה",[["5571","8","<b>הוי ולפעמים אוי</b>: (הוי) מלכים-א יג, כ. (אוי) ישעי' ג, ט. יא. ועוד. ראה גם לעיל שם בהערות 12-13."],["5572","9","<b>אנכי הסתיר אסתיר פני'</b>: וילך לא, יח [ושם: ואנכי הסתר אסתיר פני]. ראה לעיל הנחה ד\"ה איתא וכו' הנביאים והכתובים ובהערה 34."],["5573","10","<b>קוב\"ה. . לעילא ולעילא</b>: ראה זהר ויגש רי, א. ויקרא כ, ב. (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 16."],["5574","11","<b>רחל מבכה על בני' כי איננו</b>: ירמי' לא, יד [בדילוג]."],["5575","12","<b>ואיתא בזוהר כי אינה מיבעי לי'</b>: ראה זהר ויגש רי, א. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי בחגוי הסלע הערה 44."],["5576","13","<b>שהוא\"ו. . ז\"א</b>: ראה ע\"ח שער סדר אצי' ש\"ג, פ\"א."],["5577","15","<b>ה'. . בינה</b>: ראה פרדס שער האותיות שער כז, פ\"ח. הנסמן במאמרי אדה\"א בראשית ע' רלג."],["5578","14","<b>הסתיר.. אסתיר</b>: הכוונה לתיבות הסתר. . אסתיר (שבהערה 9)."],["5579","16","<b>שאלף. . כתר</b>: ראה ת\"ז תמ\"ט. מאמרי אדה\"א ויקרא ח\"ב ע' תרסא. וש\"נ."],["5580","17","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["5581","18","<b>ורבו פשעיך מה תעשה לו</b>: איוב לה, ו."],["5582","19","<b>מה מידך יקח</b>: סיום הכתוב אם צדקת."],["5583","20","<b>המלך מהודו ועד כוש</b>: אסתר א, א."],["5584","21","<b>מגילה י\"א</b>: ראה שם ע\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381154\" data-slug=\"likkutei-torah\" data-id=\"4001381154\">לקו\"ת שה\"ש ו, ב</a>."],["5585","22","<b>אלביש שמים קדרות</b>: ישעי' נ, ג."],["5586","23","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["5587","24","<b>כבני כושיים אתם לי</b>: עמוס ט, ז."],["5588","25","<b>שמי שמלובן ביותר נק' כושי</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381177\" data-slug=\"likkutei-torah\" data-id=\"4001381177\">לקו\"ת שה\"ש</a> כאן מציין לרש\"י בהעלותך [יב, א] ולזהר תרומה דק\"ל ריש ע\"א [ומעתיק לשונו]."]]],[2000470569,"כחדא נינהו, א\"כ לפי זה מצד בחי' אחשורוש אינו תופס מקום כלל שמשם אפשר שיומשך למקום שאינו ראוי ג\"כ וע\"כ נא' ויהי, וע\"כ אנו רואים שאחשורוש מתחלה נתן טבעת להמן ואח\"כ נתן הטבעת למרדכי<sup data-n=\"5589\">26</sup> שמצדו שניהם שוים שאינו תופס מקום כלל אך ע\"י שעמדו במס\"נ והגיעו מה ראו על ככה<sup data-n=\"5590\">27</sup> ומה הגיע אליהם עי\"ז בעבור זה עשה ה' לי ולא לו<sup data-n=\"5591\">28</sup>, וע\"כ לא נזכר שום שם במגילת אסתר<sup data-n=\"5592\">29</sup> לבד יבוא<sup data-n=\"5593\">30</sup> המלך והמן<sup data-n=\"5594\">31</sup> נזכר יה\"ו משם ה' שזהו מפני שהיינו בחי' אסתר שאלקות בתכלית ההסתר ואסתר הגביע את המן<sup data-n=\"5595\">32</sup> למעלה מאד כדי שיפול למטה מאד אם תגביה כנשר משם אורידך<sup data-n=\"5596\">33</sup> כו' אך באמת יש במגילת אסתר הכל ששם מרדכי מורה על בחי' מירא דכיא<sup data-n=\"5597\">34</sup>, וז' הנערות היינו ז' היכלות<sup data-n=\"5598\">35</sup> דבריאה שזהו בחי' גבוה מאד ויש הכל במג\"א רק שזהו בתכלית ההסתר אך ע\"י מס\"נ שלהם הגיעו לבחי' מה ראו על ככה, לי ולא לו, ע\"כ קיימו וקבלו היהודים<sup data-n=\"5599\">36</sup> שארז\"ל שקיימו מה שקיבלו כבר שהתחלת הקבלה הי' במ\"ת וגמר הקבלה הי' בימי אחשורוש<sup data-n=\"5600\">37</sup> ע\"י מס\"נ שלהם הגיעו לבחי' מה ראו על ככה כו', וזהו מצד אחשורוש אינו תופס מקום כלל שא\"ל ויהי אם צדקת, אך ע\"י מס\"נ שעמדו אז הגיעו לבחי' מה ראו על ככה, לי ולא לו, וזהו ויהי בימי אחשורוש כו'.",[["5589","26","<b>שאחשורוש מתחלה נתן טבעת להמן. . למרדכי</b>: אסתר ג, י. ח, ב."],["5590","27","<b>מה ראו על ככה</b>: אסתר ט, כו [ושם: ומה]."],["5591","28","<b>בעבור זה עשה הוי' לי ולא לו</b>: בא יג, ח. הגדה של פסח."],["5592","29","<b>לא נזכר שום שם במגילת אסתר</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 29."],["5593","30","<b>לבד יבוא</b>: כנראה שחסר כאן וצ\"ל כמ\"ש לעיל שם: לבד ”בר\"ת כמו י'בוא ה'מלך ו'המן ה'יום הוי' בר\"ת\" יבוא."],["5594","31","<b>יבוא המלך והמן</b>: אסתר ה, ח. ראה גם לעיל שם ובהערה 31."],["5595","32","<b>ואסתר הגביע </b>[הגביהה ]<b> את המן</b>: ראה תו\"א מג\"א צג, ד. מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע שפב ואילך. תקס\"ה ח\"א ע' תג ואילך. מאמרי אדה\"א נ\"ך ע' שעא. ע' תקה ואילך. ע' תקיא ואילך."],["5596","33","<b>אם תגביה כנשר משם אורידך</b>: עובדי' א, ד [בדילוג]."],["5597","34","<b>מרדכי. . מירא דכיא</b>: ראה חולין קלט, ב."],["5598","35","<b>וז' הנערות היינו ז' היכלות</b>: ראה זהר פקודי רס, ב."],["5599","36","<b>קיימו וקיבלו היהודים</b>: אסתר ט, כז. ראה שבת פח, א. (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 35."],["5600","37","<b>וגמר הקבלה הי' בימי אחשורוש</b>: ראה סה\"מ מלוקט ג' ע' סז בשולי הגליון."]]],[2000470570,"<h3>הנה אנכי כורת עמך ברית</h3>\n<b>בס\"ד פ' כי תשא תר\"מ</b>\n<b>הנה</b> אנכי כורת עמך ברית<sup data-n=\"5601\">1</sup> נגד כל עמך אעשה נפלאות אשר לא נבראו בכל הארץ<sup data-n=\"5602\">2</sup>, וצ\"ל דמשמע מזה הפסוק שעיקר נפלאות הי' אחר כריתת ברית דמשה והלא כל הנפלאות הי' קודם מ\"ת<sup data-n=\"5603\">3</sup> כמו יצי\"מ וקרי\"ס והמן ואח\"כ הי' מתן תורה, וגם צ\"ל פי' אשר לא נבראו כו' האיך שייך בריאה בנפלאות<sup data-n=\"5604\">4</sup> הלא הוא דבר הנפלא, ועוד דמשמע שע\"י כריתות ברית יהי' הנפלאות הגדולות אשר לא נבראו בארץ אבל הנפלאות הראשונים הי' בארץ האיך שייך דבר הפלא לארץ<sup data-n=\"5605\">5</sup> הלא הוא למעלה מעלה מבחי' ארץ. אך בכדי להבין זה צ\"ל תחלה מהו ענין הכפל דכריתות ברית עם משה והלא כבר כרת ברית עם אברהם וכמ\"ש ביום ההוא כרת ה'<sup data-n=\"5606\">6</sup> את אברם ברית כו' לזרעך נתתי את הארץ, דהנה כל עיקר ענין כריתות ברית שהגם שהשכל לא יתחייב התקשרות דבר ההוא מ\"מ לא יבטל ההתקשרות<sup data-n=\"5607\">7</sup> וא\"כ למה נצרך עוד לכריתות ברית פעם ב' עם משה דממ\"נ או די כריתות ברית או לא נצרך לשני<sup data-n=\"5608\">8</sup>. אך בכדי להבין כל זה צריך להקדים להבין כללות ענין ירידת הנשמה בגוף שידוע שהוא לצורך עלי'<sup data-n=\"5609\">9</sup> ולכאורה אינו מושג העלי' והירידה מושגת דהנה בנשמות כתי' חי הוי' אשר עמדתי לפניו<sup data-n=\"5610\">10</sup>, ופי' עמדתי כמ\"ש במלאכים ויעמידם לעד<sup data-n=\"5611\">11</sup> כו' שעומדים תמיד באהבה ויראה וביטול גדול לאלקות וכמ\"כ היתה הנשמה עומדת למעלה באהוי\"ר, ואחר כל היגיעות שיבוא לאהוי\"ר אין ערוך לגבי האהוי\"ר שהי' לה קודם וא\"כ מהו עוד העלי' יותר, אך הנה כתיב ואנשי קודש תהיון לי<sup data-n=\"5612\">12</sup> שנש\"י ע\"י עבודה דתומ\"צ מתעלים לקדש העליון.\n<b>ולהבין</b> צריך<sup data-n=\"5613\">13</sup> להבין תחלה ענין עבודת המלאכים שאומרים קדוש<sup data-n=\"5614\">14</sup>, דלכאורה אינו מובן למה הם צריכים לעבודה, הלא פי' עבודה הוא מלשון תיקון",[["5601","1","<b>הנה אנכי כורת עמך ברית</b>: הנחה ממאמר כ\"ק אדמו\"ר מהר\"ש.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לעיל (בחלק הנחותיו). וראה בהנסמן שם בריש המאמר."],["5602","2","<b>הנה אנכי. . בכל הארץ</b>: תשא לד, י [בהוספת תיבת: עמך]."],["5603","3","<b>כל הנפלאות. . מ\"ת</b>: בסה\"מ פר\"ת כאן ע' שא: והקשה הרמב\"ן. ראה גם רקאנטי כאן. אוה\"ת תשא ע' ב'ז. כרך ח ע' ג'קטז. פלח הרמון תשא ע' רצו. סה\"מ תר\"ל ע' קב. תרנ\"ד ע' קעג."],["5604","4","<b>האיך שייך בריאה בנפלאות</b>: ראה גם אוה\"ת תשא־ פלה\"ר־ סה\"מ פר\"ת שם."],["5605","5","<b>האיך שייך דבר הפלא לארץ</b>: ראה גם אוה\"ת תשא־ סה\"מ פר\"ת (ובהנחה שם ע' שיד) שם."],["5606","6","<b>ביום ההוא כרת ה'</b>: לך טו, יח."],["5607","7","<b>כריתות ברית. . לא יבטל ההתקשרות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370058\" data-slug=\"torah-or\" data-id=\"3901370058\">תו\"א לך יג, ג</a> ואילך. בהדרושים שבהערה 3. הנסמן במאמרי אדה\"א דברים ח\"א ע' רפט."],["5608","8","<b>דממ\"נ. . נצרך לשני</b>: ראה לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן. וראה גם אוה\"ת תשא ע' א'תתמז."],["5609","9","<b>ירידת הנשמה. . לצורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["5610","10","<b>חי הוי' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["5611","11","<b>ויעמידם לעד</b>: תהלים קמח, ו. ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א. וש\"נ."],["5612","12","<b>ואנשי קדש תהיון לי</b>: משפטים כב, ל. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380432\" data-slug=\"likkutei-torah\" data-id=\"4001380432\">לקו\"ת בהעלותך ל, סע\"ג</a> ואילך. יו\"כ סט, ב."],["5613","13","<b>ולהבין צריך</b>: אוצ\"ל: ולהבין זה צריך."],["5614","14","<b>המלאכים שאומרים קדוש</b>: נסמן בסמוך הערה 18."]]],[2000470571,"כמו עורות עבודים<sup data-n=\"5615\">15</sup> שבתחלה אינם ראוים לכלום וע\"י עבודה הם מתתקנים שהם ראוים למלאכה וא\"כ למה צריכים לעבודה הלא ארז\"ל כשבקשו המלאכים את התורה השיבו להם כלום יצה\"ר יש בכם<sup data-n=\"5616\">16</sup>, ועוד שהם נבראו מששת ימי בראשית<sup data-n=\"5617\">17</sup> שיעמדו בביטול גדול לאלקות וגם אין להם דבר המונע ומעכב וא\"כ למה צריכים לעבודה, ובאמת מצינו שיש להם עבודה שהרי הם אומרים ג\"פ קדוש בי\"ב שעות היום<sup data-n=\"5618\">18</sup>, שאומרים פעם אחת קדוש ועומדים ד' שעות בביטול, אך הענין דהנה כתיב בדבר הוי' שמים נעשו<sup data-n=\"5619\">19</sup> וברוח פיו כל צבאם ששרש התהוות המלאכים הוא מבחי' דבר ה'<sup data-n=\"5620\">20</sup> שהדיבור נראה כמו שנפרד דהגם שאפי' במשל אצל האדם אינו נפרד לגמרי<sup data-n=\"5621\">21</sup> שהרי יכול לקשר ולחבר את הזולת ע\"י הדבור והאיך יהי' הדיבור בעצמו כמו נפרד מ\"מ הרי הוא נראה כמו שנפרד ואינו כמו המחשבה שהגם שדיבור ומח' הם שניהם אותיות והם לבושי הנפש<sup data-n=\"5622\">22</sup> מ\"מ המחשבה הוא לבוש המתאחד<sup data-n=\"5623\">23</sup> עם עצם הנפש שמיוחד עצמיות כחות נפשו עם האדם, אבל הדיבור הוא נראה כמו שנפרד, וע\"י אמירת קדוש שלהם דהיינו שמשיגים איך שא\"ס הוא קדוש ומובדל מגדר עולמות עי\"ז מגיעים לביטול היותר גדול, כי מה שהם נבראו שיעמדו בביטול הוא רק ביטול היש אבל ע\"י השגתם הם מגיעים לביטול אמיתי שהוא הביטול דבחי' מ\"ה כמ\"ש ונחנו מ\"ה<sup data-n=\"5624\">24</sup> ועי\"ז ממשיכים מא\"ס שהוא קדוש ומובדל לשרש ומקור התהוותם.\n<b>וע\"ד</b> מה שמצינו בנש\"י שע\"י עבודתם הם עושים שיהי' יחוד קוב\"ה ושכינתי'<sup data-n=\"5625\">25</sup>, שכינה הוא בחי' ממכ\"ע שהוא רק ההארה שהוא מקור המחי' עולמות עולם הדיבור וע\"י עבודתם ממשיכים מא\"ס הסוכ\"ע לבחי' ממכ\"ע, כמ\"כ הוא בעבודת המלאכים אלא שהמלאכים א\"א להם להמשיך מעצם קדש כי קדש מילה בגרמי'<sup data-n=\"5626\">26</sup> ולכן הם אומרים קדוש שהוא קדש וא\"ו דהיינו רק המשכה<sup data-n=\"5627\">27</sup> והארה קו בעלמא",[["5615","15","<b>עבודה. . עורות עבודים</b>: ראה שבת מט, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550470\" data-slug=\"torat-chaim\" data-id=\"2300550470\">תו\"ח יתרו ח\"ב רסח, ב</a>. וש\"נ. סה\"מ תרל\"ח ע' שפ. וש\"נ."],["5616","16","<b>כלום יצה\"ר יש בכם</b>: שבת פט, א."],["5617","17","<b>נבראו מששת ימי בראשית</b>: ראה ב\"ר פ\"א, ג. סה\"מ תש\"ג ע' 73. וש\"נ. מאמרי אדה\"ז הנחות הר\"פ ע' קעג בין החצ\"ע."],["5618","18","<b>ג\"פ קדוש. . בי\"ב שעות היום</b>: ישעי' ו, ג. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381246\" data-slug=\"likkutei-torah\" data-id=\"4001381246\">לקו\"ת שה\"ש כט, ב</a> ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקע\"א ע' קפה. מאמרי אדה\"א נ\"ך ע' שלו. וש\"נ. קונטרסים ע' רמז."],["5619","19","<b>בדבר הוי' שמים נעשו</b>: תהלים לג, ו. ראה גם סה\"מ פר\"ת כאן ע' שב."],["5620","20","<b>התהוות המלאכים. . מדבר ה'</b>: ראה אגה\"ת פ\"ד. ש\"א ח, ב ובהערה 39."],["5621","21","<b>שהדיבור. . אינו נפרד לגמרי</b>: ראה לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן שמציין בד\"ה וככה — המשך וככה תרל\"ז פע\"ט. בפיסקא הבאה."],["5622","22","<b>שהדיבור ומח'. . לבושי הנפש</b>: ראה תניא פ\"ד."],["5623","23","<b>המחשבה הוא לבוש המתאחד</b>: ונק' לבוש מחובר בלשון כ\"ק אדמו\"ר שליט\"א [פלה\"ר בחוקותי ע' תמ]."],["5624","24","<b>ונחנו מה</b>: בשלח טז, ז. ח. ראה גם מאמרי אדה\"א בראשית ע' כב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540049\" data-slug=\"torat-chaim\" data-id=\"2300540049\">תו\"ח שמות ח\"א מג, א</a>. וש\"נ."],["5625","25","<b>יחוד קוב\"ה ושכינתי'</b>: ראה גם תו\"ח וארא ח\"א נא, ג."],["5626","26","<b>קדש מילה בגרמי'</b>: זהר אמור צד, ב."],["5627","27","<b>קדוש שהוא קדש וא\"ו. . המשכה</b>: ראה מאמרי אדה\"א הנחות תקע\"ז ע' רסג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540094\" data-slug=\"torat-chaim\" data-id=\"2300540094\">תו\"ח וארא ח\"א נח, ב</a>. וש\"נ. ראה גם (לעיל בחלק המאמרים) המשך מצה זו רפכ\"ט."]]],[2000470572,"לשרש ומקור התהוותם וה\"ז עלי' גדולה להם שהרי הם נבראו מדיבורו ית' שהדיבור נראה כמו שנפרד שהגם שאינו נפרד ממש שהרי יכול לקשר ולחבר הזולת והאיך יהי' הדיבור בעצמו בבחי' נפרד וא\"כ אפי' באדם אינו נפרד לגמרי ומכ\"ש למעלה הנה אין שייך כלל לומר נפרד כי אין לך דבר שחוץ ממנו, מ\"מ הרי אנו רואים באדם שלגבי עצמו אינו נצרך לו כלל הדבור כ\"א שהוא אינו רק כח הגילוי לגבי הזולת דכאשר נצרך לגלות לאדם איזה השכלה או שארי דברים הוא מגלה לו ע\"י הדבור כי מהמחשבה לא ידע הזולת גם אם יחשוב כל היום, משא\"כ המחשבה הוא לבוש המתאחד עם הנפש שהוא גילוי ההעלם העצמי לגבי עצמו ולכן נראה הדיבור כמו שנפרד. ועד\"ז יובן למעלה שדיברה תורה כלשון בני אדם<sup data-n=\"5628\">28</sup> שנראה כמו שנפרד ג\"כ ולכן מתהווה מדיבורו ית' נבראים נפרדים וכמ\"ש ומשם יפרד כו' שהגם שבאמת גם הנבראים אינם נפרדים לגמרי אלא נראים נפרדים כמו שהדבור אינו רק נראה כמו שנפרד מ\"מ ה\"ה נראה כמו שנפרד וע\"י עבודתם הם ממשיכים הארה מא\"ס הקדוש ומובדל לשרש ההתהוותם וה\"ז עלי' גדולה ולזה הוא ענין עבודתם.\n<b>ועפ\"ז</b> יובן ג\"כ ענין עליית הנשמה דהגם דשרש הנשמות הם ממחשבה עליונה כמארז\"ל ישראל עלו במחשבה<sup data-n=\"5629\">29</sup> מ\"מ הרי הוא רק לבוש אלא שהוא לבוש הפנימי והלבוש הרי פושטין ולובשין אותו ואין זה עצם אבל ע\"י ירידתה בגוף עי\"ז מתעלית לא\"ס דקדש עליון ונכללות בעצמות דקודש שהוא לאשתאבא בגופא דמלכא<sup data-n=\"5630\">30</sup> וה\"ז עלי' גדולה מלבוש לעצם. אך ע\"י מה מתעלית הנשמה הוא ע\"י העבודה דתורה ומצות כי תומ\"צ נתלבשו בדברים הגשמי' ציצית מצמר הגשמי תפילין מקלף הגשמי ד' מיני' שבלולב בצמחים גשמי' מצה וכמ\"כ<sup data-n=\"5631\">*31</sup> כל המצות, והנה שרש הגשמי' הוא מעולם התהו שקדם לתיקון<sup data-n=\"5632\">31</sup> אלא שנפל בשבה\"כ וע\"י שהאדם מקיים המצוה עי\"ז מעלה הניצוצות לשרשם הקדומה, והוא כי המצוה נותנת כח לאדם שעי\"ז יהי' אתכפי' בגוף ונה\"ב כי הנה\"ב הוא מלא רצונות ותאוות המעלימים ומסתירים והגוף הוא חומר גס ועב ובמ\"א נת' שהוא ממשכא דחויא<sup data-n=\"5633\">32</sup>, וע\"י המצוה נעשה אתכפייא ואז יהי' קיום המצות כדבעי למהוי ועי\"ז יהי' בירורי הניצוצות ויתעלו לשרשם, ועי\"ז מתעלית הנה\"א ג\"כ לשרשו, ולכן ארז\"ל עתידים צדיקים שיאמרו לפניהם קדוש<sup data-n=\"5634\">33</sup> כדרך שאומרים לפני הקב\"ה כי שם צדיק הוא ע\"ש",[["5628","28","<b>שדיברה תורה כלשון בני אדם</b>: ברכות לא, ב. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670114\" data-slug=\"torat-chaim\" data-id=\"2300670114\">תו\"ח וירא צח, ב</a>."],["5629","29","<b>ישראל עלו במחשבה</b>: ראה ב\"ר פ\"א, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380278\" data-slug=\"likkutei-torah\" data-id=\"4001380278\">לקו\"ת בחוקותי מז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381196\" data-slug=\"likkutei-torah\" data-id=\"4001381196\">שה\"ש טז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381206\" data-slug=\"likkutei-torah\" data-id=\"4001381206\">יט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381200\" data-slug=\"likkutei-torah\" data-id=\"4001381200\">יז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381202\" data-slug=\"likkutei-torah\" data-id=\"4001381202\">יח, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540558\" data-slug=\"torat-chaim\" data-id=\"2300540558\">שע\"ת קטו, ב</a>. תו\"ח שמות ח\"א לב, ב ובהערה 248."],["5630","30","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 51."],["5631","*31","<b>מצה וכמ\"כ</b>: כ\"ה בהכת\"י."],["5632","31","<b>התהו שקדם לתיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370293\" data-slug=\"torah-or\" data-id=\"3901370293\">תו\"א בשלח סה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380237\" data-slug=\"likkutei-torah\" data-id=\"4001380237\">לקו\"ת אמור לז, ד</a>. וש\"נ. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת הערה 51."],["5633","32","<b>ממשכא דחויא</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א (מ, ב</a>) ובמ\"מ הגהות והע\"ק שם. ס' שיעורים בספר ה<a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא כאן (פמ\"ה</a>) ע' 613 הערה 3. הנסמן באוה\"ת חוקת כרך ו ע' א'תתצג־ מאמרי אדה\"א נ\"ך ע' תלד."],["5634","33","<b>עתידים צדיקים שיאמרו לפניהם קדוש</b>: ראה ב\"ב עה, ב."]]],[2000470573,"קיום התומ\"צ וע\"י התומ\"צ מתעלים נש\"י לקדש עליון וממילא ימשיכו מהם המלאכים המשכה והארה שהוא קדוש קדש וא\"ו, רק שממשיכים עכשיו מקדש עליון שהרי נש\"י יוכללו ג\"כ שמה.\n<b>וביאור</b> הענין דהנה ארז\"ל זרע הקב\"ה תומ\"צ<sup data-n=\"5635\">34</sup> כדי להנחילם לישראל לעוה\"ב, לא הניח דבר שאין בו מצוה, בנה אדם בית יש בו מצות מעקה לגגיך ומזוזה<sup data-n=\"5636\">35</sup>, בשדה לקט שכחה ופאה<sup data-n=\"5637\">36</sup> וכן כולם, והענין דהנה מצינו שנק' המצות בשם זריעה<sup data-n=\"5638\">37</sup> כמ\"ש אשריכם זורעי על כל מים<sup data-n=\"5639\">38</sup>, זורע צדקות<sup data-n=\"5640\">39</sup> כו', זרעו לכם לצדקה<sup data-n=\"5641\">40</sup>, וענין הזריעה הוא בשביל הצמיחה תוספת וריבוי וכמ\"ש ויזרע יצחק כו' וימצא מאה שערים<sup data-n=\"5642\">41</sup>, והנה משל הזריעה הוא דכמו למשל שזורעין גרעין ונצמח מזה אילן וענפים ועלין ופירות, וע\"כ שישנו בהעלם בהגרעין האילן והענפים ואפי' הפירות<sup data-n=\"5643\">42</sup> דאל\"כ מאין הי' נצמח האילן, והנה הגרעין בעצמו אין בו טעם וריח כלל, כמ\"כ יובן במעשה המצות דהגם שנתלבשו בגשמיות ציצית בצמר הגשמי תפילין בקלף הגשמי מ\"מ יש בהם בהעלם אורות עליונים וכמ\"ש אור זרוע לצדיק<sup data-n=\"5644\">43</sup> שבמצות נזרע בהם אורות עליונים כי תרי\"ג מצות דאורייתא<sup data-n=\"5645\">44</sup> וז' דרבנן<sup data-n=\"5646\">46</sup> הם תר\"ך<sup data-n=\"5647\">45</sup> עמודי אור<sup data-n=\"5648\">47</sup> וכמו בד' בתים דתפילין יש בהם אור מד' מוחין<sup data-n=\"5649\">48</sup> עליונים, ול\"ב ציצית יש בהם אור ל\"ב נח\"כ<sup data-n=\"5650\">49</sup>, ובמצה",[["5635","34","<b>זרע הקב\"ה תומ\"צ</b>: בהמשך מצה זו (לעיל בחלק המאמרים) על יד הערה 1822 מציין: במד\"ר ס\"פ שלח. וש\"נ. ראה גם (בהנחת כ\"ק אדמו\"ר מהורש\"ב — לעיל בחלק הנחותיו) הנחה ד\"ה בן פורת יוסף הא' על יד הערה 47 ואילך. וראה גם מאמרי אדה\"ז הנחות הר\"פ ס\"ע קמג ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640020\" data-slug=\"or-hatorah-hb\" data-id=\"8316640020\">אוה\"ת שה\"ש כרך א ע' כ</a>."],["5636","35","<b>מעקה לגגיך ומזוזה</b>: תצא כב. ח. ואתחנן ו, ט."],["5637","36","<b>בשדה לקט שכחה ופאה</b>: קדושים יט, ט. תצא כד, יט. — כ\"ז לא הובא במדרש שם."],["5638","37","<b>המצות נק' בשם זריעה</b>: ראה תו\"א שמות נג, ג. פסוקים דבסמוך הובאו בתו\"א כאן בשינוי הסדר. ראה גם להמובא בסמוך אוה\"ת תשא ע' ב'ח."],["5639","38","<b>אשריכם זורעי על כל מים</b>: ישעי' לב, כ."],["5640","39","<b>זורע צדקות</b>: ברכת יוצר."],["5641","40","<b>זרעו לכם לצדקה</b>: הושע י, יב."],["5642","41","<b>ויזרע יצחק. . שערים</b>: תולדות כו, יב [בדילוג]."],["5643","42","<b>בהעלם בגרעין האילן והענפים ואפי' הפירות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670508\" data-slug=\"torat-chaim\" data-id=\"2300670508\">תו\"ח בראשית כח, ג</a> ובהערה 37. שער האמונה צב, א ובהערה 7."],["5644","43","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["5645","44","<b>תרי\"ג מצות דאורייתא</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטיליא מערכת שש מאות [צפת תשנ\"ב ע' 208]. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261512\" data-slug=\"likkutei-sichot\" data-id=\"1300261512\">לקו\"ש יתרו כרך כו ס\"ע 424</a> ואילך. אג\"ק שלו ח\"ג ע' רג."],["5646","46","<b>וז' דרבנן</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה סמכוני באשישות הערות 62-63."],["5647","45","<b>תרי\"ג. . וז'. . תר\"ך</b>: ראה תורת העולה להרמ\"א ח\"ג פל\"ח (לב, א). של\"ה יתרו שיו, א. מאו\"א מערכת תר\"ך סנ\"ו. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שלח."],["5648","47","<b>תר\"ך עמודי אור</b>: ראה לקו\"ת להאריז\"ל חבקוק. מאמרי אדה\"א ויקרא ח\"ב ע' תסא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670571\" data-slug=\"torat-chaim\" data-id=\"2300670571\">תו\"ח בראשית מה, ג</a> הערה 32."],["5649","48","<b>דתפילין. . מד' מוחין</b>: ראה זהר ואתחנן רסב, א. סידור שער התפילין ז, א. אמרי בינה שער התפילין קיב, א ואילך. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ד ע' א'רמא. וש\"נ."],["5650","49","<b>ול\"ב ציצית. . ל\"ב נח\"כ</b>: ראה זח\"ג תוספת שא, א. בחיי שלח טו, לח ד\"ה וע\"ד הקבלה (ירושלים תשל\"ב ס\"ע קא). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקטז ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380523\" data-slug=\"likkutei-torah\" data-id=\"4001380523\">לקו\"ת קרח נב, ב</a>. ד."]]],[2000470574,"קטנות אבא<sup data-n=\"5651\">50</sup>, וע\"י עבודת האדם ממשיך אותם מהעלם אל הגילוי ועי\"ז מתעלה האדם לקדש העליון. והנה הזריעה צ\"ל בארץ דאם לא יזרעו בארץ לא יצמח, והנה הארץ הוא כנס\"י<sup data-n=\"5652\">51</sup> וכמ\"ש דור הולך ודור בא והארץ לעולם עומדת, ואמרו במד\"ר<sup data-n=\"5653\">52</sup> שהארץ הוא כנס\"י וכמ\"ש כי תהיו לי אתם ארץ חפץ<sup data-n=\"5654\">53</sup>, שנש\"י הם הארץ אשר בהם יצמח החפץ ה', וכמ\"ש ה' חפץ למען צדקו<sup data-n=\"5655\">54</sup> יגדיל תורה ויאדיר, צדקו הם כללות כל המצות שנק' בשם צדקה וכמ\"ש וצדקה תהי' לנו<sup data-n=\"5656\">55</sup> כו', וחפץ הוא התורה שהוא החפץ ה', ונש\"י הם הארץ שע\"י יגדל החפץ ורצון ה' כי שרש המצות הם רצה\"ע אלא שנתלבשו בדברים גשמיים וע\"י שנש\"י מקיימים המצות הם ממשיכים האורות מהעלם לגילוי, וזהו דוקא נש\"י<sup data-n=\"5657\">56</sup> כי אם אחר יקיים המצות לא ימשיך כלום, ואדרבה נכרי ששבת<sup data-n=\"5658\">57</sup> כו', וכמ\"ש מגיד דבריו ליעקב<sup data-n=\"5659\">58</sup> כו' לא עשה כן<sup data-n=\"5660\">59</sup> כו'.\n<b>ובזה</b> יובן ענין הכריתות ברית שעם אברהם שהוא על הארץ דוקא, דהיינו שבכדי שיהי' נש\"י דוקא הם הארץ להצמיח אורות עליונים דמעשה המצות ולא אחר לזה נצרך לכריתות ברית שהוא למעלה מהטעם ודעת, אך כ\"ז כאשר מקיימים המצות<sup data-n=\"5661\">61</sup> אז הרי הם נקראים בשם ארץ ועי\"ז נעשה הצמיחה, אך אם פגם האדם במעשה המצות מ\"מ אל יאמר נואש כי לזה הי' ענין הכריתות ברית שעם משה<sup data-n=\"5662\">60</sup> שהוא ע\"י התשובה וכמאמר רז\"ל אין לך דבר שעומד בפני התשובה<sup data-n=\"5663\">62</sup>, כי ע\"י התשובה נמשך י\"ג מדה\"ר שהם נק' ג\"כ בשם כריתות ברית וכמארז\"ל ברית כרותה לי\"ג מדה\"ר<sup data-n=\"5664\">63</sup> שאינן חוזרות ריקם, והכריתות ברית דמשה הוא למעלה",[["5651","50","<b>ובמצה. . קטנות אבא</b>: ראה סידור סדר הגדה חצר, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540710\" data-slug=\"torat-chaim\" data-id=\"2300540710\">תו\"ח בא ח\"א צד, ד</a> הערה 393."],["5652","51","<b>הארץ הוא כנס\"י</b>: נסמן בהערה הבאה."],["5653","52","<b>דור הולך. . במד\"ר</b>: קהלת א, ד. קה\"ר שם (פיסקא והארץ)."],["5654","53","<b>כי תהיו לי אתם ארץ חפץ</b>: מלאכי ג, יב [בהוספת תיבת: לי — וכ\"ה בסה\"מ פר\"ת ע' שג. באוה\"ת שבהערה 37: אתם לי]."],["5655","54","<b>ה' חפץ למען צדקו</b>: ישעי' מב, כא. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ולקחתם לכם על יד הערה 48."],["5656","55","<b>כל המצות. . וצדקה תהי' לנו</b>: ואתחנן ו, כה. ראה (לעיל בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 65."],["5657","56","<b>המצות. . דוקא נש\"י</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370240\" data-slug=\"torah-or\" data-id=\"3901370240\">תו\"א שמות נג, ד</a>. (לעיל הנחת כ\"ק אדמו\"ר מהורש\"ב — בחלק הנחותיו) הנחה ד\"ה בן פורת יוסף הא' ובהערות 54. 57."],["5658","57","<b>נכרי ששבת</b>: סנהדרין נח, סע\"ב. ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 167."],["5659","58","<b>מגיד דבריו ליעקב</b>: תהלים קמז, יט."],["5660","59","<b>לא עשה כן</b>: תהלים שם, כ."],["5661","61","<b>אברהם. . כאשר מקיימים המצות</b>: להעיר משע\"ת קלג, א."],["5662","60","<b>הכריתות ברית שעם אברהם. . שעם משה</b>: ראה גם אוה\"ת תשא ע' א'תתמח. ע' ב'ט ואילך. כרך ח ע' ג'קיז ואילך. פלח הרמון תשא ע' רצט ואילך. ע' שא ואילך. סה\"מ תר\"ל ע' קה ואילך. תרנ\"ד ע' קעז ואילך. סה\"מ פר\"ת כאן ע' שטז ואילך."],["5663","62","<b>אין לך דבר שעומד בפני התשובה</b>: ראה תניא פכ\"ה. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. סה\"מ תש\"ט ע' 42 (הא') בהערה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061066\" data-slug=\"likkutei-sichot\" data-id=\"1300061066\">לקו\"ש בא כרך ו ע' 66</a> הערה 54."],["5664","63","<b>ברית כרותה לי\"ג מדה\"ר</b>: וכ\"ה באוה\"ת תשא כאן ע' ב'ז. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת על יד הערה 71. ובהנחה שם על יד הערה 87. ראה ר\"ה יז, ב."]]],[2000470575,"מעלה מכריתות ברית דאברהם וכמ\"ש ונפלינו אני ועמך<sup data-n=\"5665\">64</sup> שהוא פלא גדול דבשלמא אם ישראל מקיימים מצות הרי הם הארץ שע\"י נעשה צמיחה וגם הצמיחה הוא דוקא מעין המין שזורעים אבל בלי זריעה בארץ לא יצמח כלל, וכמ\"כ הוא בנמשל שע\"י התשובה יהי' נושא עון ועובר על פשע<sup data-n=\"5666\">65</sup> ויומשכו עוד אורות עליונים ה\"ז פלא ששרשו מפלא עליון. ולכן מצינו דכתי' וזכרתי את בריתי יעקב והארץ אזכור<sup data-n=\"5667\">66</sup> שהו\"ע הכריתות ברית שעם אברהם שהוא על הארץ דוקא ואח\"כ כתיב ואף גם זאת<sup data-n=\"5668\">67</sup> בהיותם בארץ אויביהם לא מאסתים כו' וזכרתי להם ברית ראשונים<sup data-n=\"5669\">68</sup> הוא משה וכאן לא כתיב ארץ כי הכריתות ברית דמשה לא הי' על הארץ.\n<b>וזהו</b> מ\"ש כי כארץ תוציא צמחה<sup data-n=\"5670\">69</sup> וכגנה זרועיה תצמיח כן אד' ה' יצמיח צדקה ותהלה, בארץ<sup data-n=\"5671\">70</sup> היינו מעשה המצות שלא בכוונה, וכגנה היינו מעשה המצות בכוונה כי בגן זורעים דברים חשובים, שע\"י המצות בכוונה הוא כמו למשל הגן וע\"י עשי' שלא בכוונה הוא ארץ סתם מ\"מ הרי הוא נק' ארץ, אבל אם פגם בתומ\"צ שאז אינו בבחי' ארץ להצמיח עז\"נ כן אד' ה' יצמיח צדקה שע\"י התשובה נעשה הצמיחה מלמעלה מעלה וכמ\"ש וסלחת לעוונינו ולחטאתינו<sup data-n=\"5672\">71</sup>. וזהו פי' הפסוק שענין הכריתות ברית דמשה הוא על התשובה ששרשו מי\"ג מדה\"ר הנק' בשם פלא שזהו מ\"ש אעשה נפלאות ולכן כתי' אשר לא נבראו בכל הארץ שהוא אינו שייכות לארץ שהוא התומ\"צ כ\"א לתשובה, ולכן כתי' אשר לא נבראו ששרש ענין זה הכריתות ברית דמשה הוא למעלה מעלה ממעלת הבריאה. ונמצא מתורץ הכל שהגם שהי' כבר כריתות ברית עם אברהם זה הי' על קיום התומ\"צ שנש\"י יהי' הם דוקא בבחי' ארץ ולא אחר, והכריתות ברית דמשה הוא על התשובה ושרשו הוא מנפלאות ולכן בו דוקא כתיב אעשה נפלאות ולכן כתי' ג\"כ אשר לא נבראו שהם למעלה משרש הבריאה ואינם שייכים להארץ.",[["5665","64","<b>ונפלינו אני ועמך</b>: תשא לג, טז."],["5666","65","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח."],["5667","66","<b>וזכרתי את בריתי יעקב. . אזכור</b>: בחוקותי כו, מב [בדילוג]."],["5668","67","<b>ואף גם זאת</b>: בחוקותי שם, מד."],["5669","68","<b>וזכרתי להם ברית ראשונים הוא משה</b>: שם כו, מה. ראה אוה\"ת תשא כאן ס\"ע ב'ט ואילך. כרך ח ע' ג'קיז. ע' ג'קיט."],["5670","69","<b>כי כארץ תוציא צמחה</b>: ישעי' סא, יא. ראה גם אוה\"ת תשא כאן ע' ב'י."],["5671","70","<b>בארץ</b>: אוצ\"ל: כארץ."],["5672","71","<b>וסלחת לעוונינו ולחטאתינו</b>: תשא לד, ט."]]],[2000470576,"<h3>גדולה מילה</h3>\n<b></b><b>נאמר על ב\"מ של כר\"ל נכד של מהרש\"ש נ'</b>\nנאמר על ב\"מ של כר\"ל נכד של מהרש\"ש נ'\n<b>גדולה</b> מילה<sup data-n=\"5673\">1</sup> שנכרתו עלי' י\"ג בריתות<sup data-n=\"5674\">2</sup>, הנה לכאורה צ\"ל מפני מה על תורה נכרתו רק ג' בריתות<sup data-n=\"5675\">3</sup> ועל מילה י\"ג הלא מילה הוא רק מצוה פרטיות ואיך יצא מן הכלל בתוס' יותר ותוס' מרובה על העיקר. הנה כתי' מי יעלה לנו השמימה<sup data-n=\"5676\">4</sup> שמילה הוא בר\"ת ושם ה' הוא בס\"ת<sup data-n=\"5677\">5</sup> שגם זה צ\"ל מפני שם<sup data-n=\"5678\">6</sup> ה' בס\"ת ומילה בר\"ת. להבין זאת צ\"ל תחלה תיבת השמימה הנה משה אמר האזינו השמים ותשמע הארץ<sup data-n=\"5679\">7</sup> וישעי' אמר שמעו שמים והאזיני ארץ<sup data-n=\"5680\">8</sup>, מה שבמשה נאמר האזינו לשמים ובישעי' נאמר האזינו לארץ מתורץ במדרש שמשה הי' שייך לשמים יותר ע\"כ נאמר אצלו האזינו לשמים וישעי' הי' שייך יותר לארץ ע\"כ אמר האזינו לארץ<sup data-n=\"5681\">9</sup>, אך מה שנאמר השמים והארץ שמים וארץ היינו שמו\"א דלא ידיען ושמו\"א ידיען<sup data-n=\"5682\">10</sup>.\n<b>והנה</b> שמים הוא מקיף את הארץ מכל צד והארץ הוא רק כגרגיר חרדל<sup data-n=\"5683\">11</sup> והוא באמצע האויר, ונלאו חכמי הפילוסופים בהחקירה איך הוא קיים הארץ שעומד באמצע האויר<sup data-n=\"5684\">12</sup>. אך באמת כתי' אני אענה את השמים<sup data-n=\"5685\">13</sup> והם יענו את הארץ, אני אענה את השמים והשמים משפיע<sup data-n=\"5686\">14</sup> בארץ שכל חלק בארץ הוא מקבל מהשמים השפעה ועי\"ז יתקיים הארץ, והנה השמים מקיף את הארץ מכל צד והיינו כמו מדות ודיבור שמדות מקיף את הדיבור<sup data-n=\"5687\">15</sup> כאשר המדה בתוקף אז לא יוכל לדבר<sup data-n=\"5688\">16</sup> אלא",[["5673","1","<b>גדולה מילה</b>: הנחה ממאמר כ\"ק אדמו\"ר מהר\"ש.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפס לעיל (בחלק הנחותיו). וראה הנסמן שם בריש המאמר.\nבהכותרת כאן נרשם: נאמר על בר\"מ של כר\"ל( ) נכד של מהרש\"ש נ'. השווה הכותרת לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן [ושם נרשם גם התאריך]."],["5674","2","<b>גדולה מילה שנכרתו עלי' י\"ג בריתות</b>: משנה נדרים לא, ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251054\" data-slug=\"likkutei-sichot\" data-id=\"1300251054\">לקו\"ש לך כרך כה ע' 54</a> ואילך ובהערה 5. הערה הבאה."],["5675","3","<b>תורה. . ג' בריתות</b>: ברכות מח, סע\"ב ואילך. ראה גם סה\"מ תרכ\"ו ע' כג. תרל\"א (נמצא בדפוס). תרל\"ג ח\"ב ע' שצט. וע' תא."],["5676","4","<b>מי יעלה לנו השמימה</b>: נצבים ל, יב."],["5677","5","<b>שמילה הוא בר\"ת ושם ה' הוא בס\"ת</b>: ראה בעה\"ט שם. ת\"ז בהקדמה ב, ב. תכ\"ב סה, ב. סו, א. ת\"ע קלא, רע\"א."],["5678","6","<b>מפני שם</b>: אוצ\"ל: מפני מה שם."],["5679","7","<b>משה אמר האזינו השמים ותשמע הארץ</b>: האזינו לב, א. ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 6."],["5680","8","<b>וישעי' אמר שמעו שמים והאזיני ארץ</b>: ישעי' א, ב."],["5681","9","<b>שמשה. . לשמים. . וישעי'. . לארץ</b>: ראה ספרי ר\"פ האזינו. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091204\" data-slug=\"likkutei-sichot\" data-id=\"1300091204\">לקו\"ש האזינו כרך ט ע' 204</a> הערה 1 וראה גם שם בהערה 4."],["5682","10","<b>שמו\"א דלא ידיען ושמו\"א ידיען</b>: ראה זהר האזינו רפו, ב. סה\"מ תרל\"ח שבהערה הבאה."],["5683","11","<b>והארץ הוא רק כגרגיר חרדל</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370006\" data-slug=\"torah-or\" data-id=\"3901370006\">תו\"א בראשית ב, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670215\" data-slug=\"torat-chaim\" data-id=\"2300670215\">תו\"ח בראשית כא, ד</a> ובהערה 34. סה\"מ תרל\"ח ע' שפד. וש\"נ. עטר\"ת ע' רעא."],["5684","12","<b>ונלאו חכמי הפילוסופים. . הארץ שעומד באמצע האויר</b>: השווה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה *10."],["5685","13","<b>אני אענה את השמים</b>: הושע ב, כג [בהוספת תיבת: אני — ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 10."],["5686","14","<b>אני אענה. . משפיע</b>: ראה גם סידור שער ל\"ג בעומר שג, א. שה\"א לד, ב ובהערה 31."],["5687","15","<b>שמדות מקיף את הדיבור</b>: ראה גם מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' ג. סה\"מ תרכ\"ו ס\"ע כו ואילך. תרל\"ח ע' שפד."],["5688","16","<b>המדה בתוקף אז לא יוכל לדבר</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן יד הערה *13. הנחה ד\"ה משה קבל פיסקא וביאור ענין. סה\"מ תרל\"ח ע' י."]]],[2000470577,"כאשר המדה נתצמצם בדיבור אז יוכל לדבר, וכאשר מדבר מן השפה ולחוץ אז חבירו לא יוכל לקבל מאיתו ואינו פועל אצלו כלום שזהו אינו גילוי אלא שהמדה צריך להתצמצם בדיבור ומקיף את הדיבור מכל צד אז יוכל לקבל חבירו מאיתו, והנה מדות ודיבור היינו ז\"א ומל' והיינו שמו\"א<sup data-n=\"5689\">17</sup> ידיען כמו שהמדות מקיף את הדיבור כך שמים מקיף את הארץ, שמו\"א דלא ידיען היינו חו\"ב<sup data-n=\"5690\">18</sup> שמחכמה נמשך בהשגה והבנה דבינה וכמו שהמדות נתצמצם בדיבור והראי' כאשר המדה הוא בתוקף אז לא יוכל לדבר כך החכמה נתצמצם בהשגה והבנה דבינה, אך כ\"ז שמו\"א, ויש עוד בחי' שלמעלה היינו בחי' שמי השמים שהוא מקיף הכללי שהוא מקור כל המקיפים.\n<b>והנה</b> במילה נאמר השמימה הוא כולל אפי' שמי השמים וע\"כ מי יעלה לנו השמימה שהוא כולל אפי' שמי השמים וע\"כ מילה בר\"ת ושם ה' בס\"ת ששם ה' הוא לשון מהוה<sup data-n=\"5691\">19</sup> שהוא מקור על התהוות שזהו שייך לארץ, אבל מילה הוא בר\"ת מפני שמגיע אפי' לבחי' שמי השמים וע\"כ נאמר השמימה, וע\"כ בתורה נכרתו רק ג' בריתות כי תורה נק' תורת הבריאה<sup data-n=\"5692\">20</sup> והג' בריתות הם כנגד ג' עולמות בי\"ע, אבל מילה נכרתו עליה י\"ג בריתות כי ע\"י העברת ערלה עי\"ז מסירים כל המסכים והמבדילים ועי\"ז מגיע לבחי' השמימה שכולל אפי' שמי השמים כמו י\"ג פרוכת הי' בבהמ\"ק<sup data-n=\"5693\">21</sup> והבדילו הפרוכת בין קודש הקדשים<sup data-n=\"5694\">22</sup>, וכמו שאהרן נכנס לקודש הקדשים שיש בחי' קודש הקדשים ואהרן נכנס לקדש הקדשים כך ע\"י מילה מגיע לבחי' שמים ושמי השמים כמארז\"ל במד\"ר פתחי לי כחודה של מחט<sup data-n=\"5695\">23</sup> ואני אפתח לך כפתחו של אולם, ובעבודה היינו שמסירים העברת הערלה הגשמי והעברת ערלה ברוחני' עי\"ז מגיע לבחי' ומלתם את ערלת לבבכם<sup data-n=\"5696\">24</sup> ועי\"ז ומל ה' את לבבך<sup data-n=\"5697\">25</sup>, וע\"כ נאמר בזאת יבוא אהרן<sup data-n=\"5698\">26</sup> באיזה זכות נכנס אהרן<sup data-n=\"5699\">27</sup> אל קודה\"ק זכות המילה היתה",[["5689","17","<b>מדות ודיבור. . שמו\"א</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 14."],["5690","18","<b>שמו\"א. . חו\"ב</b>: ראה גם לעיל שם ובהערה 16."],["5691","19","<b>ששם ה'. . מהוה</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"ט. שער עצמות וכלים שער ד', ספ\"י. שער היחוה\"א פ\"ד. פ\"ז. הערה בסה\"מ ת\"ש ע' 40."],["5692","20","<b>תורה נק' תורת הבריאה</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 25."],["5693","21","<b>י\"ג פרוכת הי' בבהמ\"ק</b>: ראה יומא נד, א. כתובות קו, א."],["5694","22","<b>והבדילו הפרוכת בין קודש הקדשים</b>: תרומה כו, לג [ושם: והבדילה הפרוכת לכם בין הקדש ובין קדש הקדשים]."],["5695","23","<b>פתחי לי כחודה של מחט</b>: ראה ס' חרדים בהקדמה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011205\" data-slug=\"likkutei-sichot\" data-id=\"1300011205\">לקו\"ש ויקהל ח\"א ע' 191</a> הערה 17. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370424\" data-slug=\"torah-or\" data-id=\"3901370424\">תו\"א מג\"א צד, ג</a>. סה\"מ תרל\"ח ע' תסד. וש\"נ."],["5696","24","<b>ומלתם את ערלת לבבכם</b>: עקב י, טז."],["5697","25","<b>ומל ה' את לבבך</b>: נצבים ל, ו [ושם ה\"א]. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה עטרת תפארת שיבה על יד הערה 21 ואילך ובהנסמן שם."],["5698","26","<b>בזאת יבא אהרן</b>: אחרי טז, ג."],["5699","27","<b>באיזה זכות נכנס אהרן</b>: ראה שמו\"ר פל\"ח, ח. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080286\" data-slug=\"or-hatorah-hb\" data-id=\"8160080286\">אוה\"ת אחרי ח\"א ס\"ע רפו</a> ואילך. סה\"מ תר\"ל ע' קכו."]]],[2000470578,"נכנסת עמו כי זהו ד\"מ כמו<sup data-n=\"5700\">28</sup> ע\"י מילה מגיע לבחי' שמים ושמי השמים כך אהרן נכנס לקודש הקדשים שיש קדשים וקודש<sup data-n=\"5701\">29</sup> ואהרן נכנס לקה\"ק ע\"כ ע\"י זכות המילה היתה נכנסת, וע\"כ על המילה נכרת י\"ג בריתות שהתוס' מרובה יותר שעי\"ז אפשר לבוא לבחי' שמי השמים כו'.",[["5700","28","<b>ד\"מ כמו</b>: תיבות אלו אינם ברורים."],["5701","29","<b>וקודש</b>: אוצ\"ל: וקוה\"ק."]]],[2000470579,"<h3>וביום הביכורים</h3>\n<b>בס\"ד חגה\"ש ש' תר\"ם </b>\nלד\"ה מצה זו. הנחה\nוביום הביכורים<sup data-n=\"5702\">1</sup> בהקריבכם מנחה חדשה לה' בשבעתיכם מקרא קדש יהי' לכם כל מלאכת עבודה לא תעשו<sup data-n=\"5703\">2</sup>, הנה מנחה חדשה קאי על שתי הלחם שהי' לחם חמץ כמ\"ש סולת תהיינה חמץ תאפינה<sup data-n=\"5704\">3</sup> וכמארז\"ל כל המנחות באות מצה<sup data-n=\"5705\">4</sup> חוץ מתודה ושתי הלחם, הנה לכאורה צ\"ל מפני מה בחגה\"ש מקריבים לחם חמץ משא\"כ בכל השנה כתי' וכל שאור וכל דבש לא תקטירו<sup data-n=\"5706\">5</sup>, הגם ששתי הלחם הי' אכילת כהנים<sup data-n=\"5707\">6</sup> מ\"מ בכל השנה לא הקריבו חמץ גם לפני<sup data-n=\"5708\">*7</sup> אכילת כהנים ג\"כ כ\"א בחגה\"ש דוקא א\"כ מפני מה בכל השנה וכל שאור וכל דבש לא תקטירו שכל המנחות באות מצה ושתי הלחם באות חמץ, וזה שהי' אכילה לכהנים זה אינו לגריעותא כו'.\n<b>ולהבין</b> זאת צ\"ל תחלה ההפרש בין שבת ליו\"ט<sup data-n=\"5709\">7</sup> הנה שבת נק' בשם קדש וכמ\"ש ושמרתם את השבת<sup data-n=\"5710\">8</sup> כי קדש היא ויו\"ט נק' מקרא קדש כמ\"ש מקרא קדש תהי' לכם<sup data-n=\"5711\">9</sup>, הנה שבת נק' קדש היינו בחי' קדש מלה בגרמה<sup data-n=\"5712\">10</sup> שקדוש ומובדל מגדר עולם כמו אלפים שנה קדמה תורה לעולם<sup data-n=\"5713\">11</sup>, לא שקדם בזמן אלא במעלה<sup data-n=\"5714\">12</sup>, אלפיים",[["5702","1","<b>וביום הביכורים</b>: הנחה ממאמר כ\"ק אדמו\"ר מהר\"ש ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים בהמשך מצה זו פרקים ל\"א-ג\"ל. וש\"נ.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפס לעיל (בחלק הנחותיו)."],["5703","2","<b>וביום הביכורים. . לא תעשו</b>: פינחס כח, כו. ראה מנחות פד, ב."],["5704","3","<b>סולת תהיינה חמץ תאפינה</b>: אמור כג, יז."],["5705","4","<b>כל המנחות באות מצה</b>: מנחות נב, ב (במשנה)."],["5706","5","<b>וכל שאור. . לא תקטירו</b>: ויקרא ב, יא [ושם: כי כל]."],["5707","6","<b>ששתי הלחם הי' אכילת כהנים</b>: מנחות עד, ב במשנה."],["5708","*7","<b>לפני</b>: כ\"ה בהכת\"י."],["5709","7","<b>ההפרש בין שבת ליו\"ט</b>: ראה פע\"ח שער מקראי קדש ש\"כ, פ\"א. (לעיל בחלק המאמרים) המשך מצה זו כאן ובהערה 994."],["5710","8","<b>ושמרתם את השבת</b>: תשא לא, יד."],["5711","9","<b>מקרא קדש תהי' לכם</b>: בריש ההנחה כאן־ בא יב, טז־ אמור כג, ז ואילך [יהי' לכם — ואולי גם כאן צ\"ל כן]."],["5712","10","<b>קדש מלה בגרמה</b>: זהר אמור צד, ב."],["5713","11","<b>אלפים שנה קדמה תורה לעולם</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ. מאמר ד\"ה זה תשי\"א יום ב' דחה\"ש."],["5714","12","<b>שקדם. . במעלה</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו ובהערה 899."]]],[2000470580,"היינו אאלפך חכמה<sup data-n=\"5715\">13</sup> שחכמה נק' קדש מלה בגרמה שמובדל מעולם כמו שנת\"ל ההפרש בין מוחין למדות<sup data-n=\"5716\">14</sup> שמדות שייך דוקא לזולת אבל מוחין אינו שייך לזולת שאפשר להשכיל אפי' בפ\"ע ע\"כ נק' מלה בגרמה שקדוש ומובדל מגדר עולם וע\"כ נק' אין כמ\"ש והחכמה מאין תמצא<sup data-n=\"5717\">15</sup> שענין המציאה היינו שלא נשתנה הדבר<sup data-n=\"5718\">16</sup> אז צריך להחזיר לבעל האבידה כך החכמה שנמשך בדרך תמצא וכיון שנמשך מאין הוא ג\"כ אין<sup data-n=\"5719\">17</sup> וע\"כ נק' מ\"ה<sup data-n=\"5720\">18</sup> כו'. ומה שנמשך מחכמה בבינה הוא נמשך ע\"י חלון כמ\"ש בע\"ח<sup data-n=\"5721\">19</sup> שע\"ס כל ספירה הוא פרצוף שלם כלול מעשר ובחי' יסוד שבכל ספירה הוא נק' חלון שזה הוראה שהמשכה נמשך בצמצום כמו ע\"י חלון בגשמיות כאשר אין כותל בבית אז מאיר השמש כמו שהוא בבית וכאשר יש דופן בבית בלא חלונות אז מסתיר לגמרי וכאשר מאיר ע\"י חלונות אז מאיר בצמצום כך המשכה שנמשך מחכמה לבינה נמשך ע\"י חלון שזה מורא<sup data-n=\"5722\">20</sup> שנמשך בצמצום הארה וע\"כ נק' בשם יו\"ד שזה ד\"א<sup data-n=\"5723\">21</sup> חלון או יו\"ד שנמשך בצמצום, וכל האורך ורוחב שנעשה בבינה שבינה הוא השגה והבנה באורך ורוחב שנעשה בחי' יש כמ\"ש להנחיל אוהבי יש<sup data-n=\"5724\">22</sup> זהו רק מהארת יסוד אבא שנמשך בבינה וע\"כ נק' קדוש בוא\"ו שמה שנמשך מבחי' קדש<sup data-n=\"5725\">23</sup> בחי' חכ' בבינה זהו ע\"י וא\"ו כי לבד שאינו דומה קדוש לקדש עוד זאת אינו דומה בשני דברים כי וא\"ו הוא בראשו יו\"ד<sup data-n=\"5726\">24</sup> ונעשה וא\"ו שזהו תוס' והתוס' הוא גירעון כמו מתיים נעשה אמתיים שהתוס' הוא לגירעון ועוד כי יו\"ד הוא מספר עשר אבל וא\"ו הוא מספר ששה, והמשכה שנמשך מיסוד אבא בבינה הוא ע\"י וא\"ו שבראשו יו\"ד שזהו הוראה שיש בזה הארת החכמה אבל מ\"מ כיון שנמשך ע\"י וא\"ו נשתנה שאינו דומה לעצם היו\"ד כי וא\"ו אינו דומה ליו\"ד.\n<b>והנה</b> קוטב מדרוש<sup data-n=\"5727\">*25</sup> זה הוא לפי השיטה דבחי' אבי\"ע שבאצי' הנה החכמה היא אצי' שבאצי' והבינה היא בריאה שבאצי'<sup data-n=\"5728\">25</sup> וז\"א יצירה שבאצי' ובחי' מדת המל' היא עשיי' שבאצי' כו', וכ\"מ בלק\"ת (סד\"ה ששים המה מלכות דרוש א'<sup data-n=\"5729\">26</sup> )",[["5715","13","<b>אאלפך חכמה</b>: ע\"פ איוב לג, ג."],["5716","14","<b>כמו שנת\"ל ההפרש בין מוחין למדות</b>: (בחלק המאמרים) המשך מצה זו פ\"ל ובהערה 969."],["5717","15","<b>והחכ' מאין תמצא</b>: איוב כח, יב. ראה (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וירא העם וינועו ובהערה 63."],["5718","16","<b>המציאה היינו שלא נשתנה הדבר</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו ספ\"ל."],["5719","17","<b>החכמה. . הוא ג\"כ אין</b>: ראה גם לעיל שם ובהערה 981."],["5720","18","<b>החכמה. . נק' מ\"ה</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 39."],["5721","19","<b>מחכמה. . חלון כמ\"ש בע\"ח</b>: ראה שער הכללים פ\"א. ראה גם (לעיל בחלק המאמרים) המשך מצה זו כאן רפל\"א."],["5722","20","<b>מורא</b>: כנצ\"ל: מורה."],["5723","21","<b>ד\"א</b>: דבר אחר"],["5724","22","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["5725","23","<b>קדוש בוא\"ו. . קדש</b>: ראה ביאוה\"ז אמור פ, ג. ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה הנה אנכי כורת ברית הערה 30."],["5726","24","<b>וא\"ו הוא בראשו יו\"ד</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370012\" data-slug=\"torah-or\" data-id=\"3901370012\">תו\"א בראשית ג, ג</a>. מאמרי אדה\"א דברים ח\"ב ע' תרעח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540182\" data-slug=\"torat-chaim\" data-id=\"2300540182\">תו\"ח בשלח ח\"א קנ, ג</a>. וש\"נ."],["5727","*25","<b>מדרוש</b>: אוצ\"ל: דרוש."],["5728","25","<b>אבי\"ע. . החכמה היא אצי' שבאצי'. . בריאה שבאצי'</b>: ראה (לעיל בחלק המאמרים) המשך מצה זו כאן הערה 1002."],["5729","26","<b>בלק\"ת. . דרוש א'</b>: ראה שם שה\"ש לט, ג."]]],[2000470581,"שהובא בשם ע\"ח<sup data-n=\"5730\">27</sup> שע\"י שבינה דאצי' מלבשת התלבשות גמור להחכ' עי\"ז נעשה מסך מבדיל בין א\"ס וחכמה אל בריאה היינו בין אצי' לבריאה, א\"כ כיון שבינה הוא מקור לבריאה שע\"י בינה נעשה הפרסא ועי\"ז מקור לבריאה ממילא מובן שבאצי' גופא בינה הוא בריאה וחכמה הוא אצי' שבאצי', כי אבא מקננא באצי'<sup data-n=\"5731\">28</sup> משא\"כ בבריאה אימא עילאה מקננא בכורסייא<sup data-n=\"5732\">29</sup> הוא בחי' עולם הבריאה א\"כ כמו שהבריאה אינו בערך אל האצי' כן אינו בערך בינה לגבי חכמה כי נברא לגבי אלקות אינו בערך כמו לפי ערך השגה לגבי למעלה השגה<sup data-n=\"5733\">30</sup> שענין השגה היינו שנמשך בהשגה והבנה ונתפס במוחו אבל למעלה מהשגה היינו שאינו נתפס בשכל ע\"כ כמו שאינו בערך השגה לגבי למעלה מהשגה כן אינו בערך נברא לגבי אלקות א\"כ לפ\"ז שאצי' שבאצי' הוא בחי' חכמה ממילא בחי' א\"א הוא למעלה מאבי\"ע דאצי' אלא כענין שיש ד' יסודות אש רוח מים עפר<sup data-n=\"5734\">31</sup> ויש בחי' היולי<sup data-n=\"5735\">32</sup> שלכאורה מהו\"ע היולי הלא הוא אינו בחי' אש ולא מים ולא עפר אלא שזהו מקור לד' יסודות<sup data-n=\"5736\">33</sup> כך א\"א<sup data-n=\"5737\">34</sup> הוא שורש ומקור לד' עולמות וכן הוא מקור לד' עולמות שבאצי' גופא כו'.\n<b>אך</b> יש עוד שיטה שכתר נק' אצי' שבאצי'<sup data-n=\"5738\">35</sup> וחכמה נק' בריאה שבאצי' וכן משמע בלקו\"ת<sup data-n=\"5739\">36</sup> שהובא מ\"ש בורא קדושים ישתבח שמך<sup data-n=\"5740\">37</sup> שאפי' קדושים בחי' קדושים בכל יום יהללוך סלה<sup data-n=\"5741\">38</sup> נק' ג\"כ בורא כמו בריאה יש מאין א\"כ חכמה נק' ג\"כ בחי' בריאה וכ\"מ בהרמ\"ז<sup data-n=\"5742\">39</sup> ג\"כ, אך דרוש זה נמשך לפי שיטה שחכמה נק' אצי' שבאצי' וכן משמע באשל אברהם<sup data-n=\"5743\">40</sup> כו'. והנה מה שנמשך מחכמה לבינה זהו רק הארה כמו עד\"מ השפעת הרב לתלמיד שמשפיע לו רק הארת השכל כי דיבור הוא רק חלק עשירי<sup data-n=\"5744\">41</sup> מחכמה, ובאמת אינו אפי' חלק עשירי ג\"כ שבאינו<sup data-n=\"5745\">*42</sup> בערך דיבור",[["5730","27","<b>בשם ע\"ח</b>: שער סדר אבי\"ע שמ\"ז, פ\"ב."],["5731","28","<b>אבא מקננא באצי'</b>: ראה ת\"ז ת\"ו כג, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' רלה."],["5732","29","<b>אימא עילאה מקננא בכורסייא</b>: ת\"ז שם. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["5733","30","<b>השגה</b>: אוצ\"ל: מהשגה."],["5734","31","<b>ד' יסודות אש רוח מים עפר</b>: ראה שה\"א סו, א ובהערה 17. סה\"מ תרכ\"ט ע' קעט. וש\"נ. תרל\"ח ע' תצא."],["5735","32","<b>בחי' היולי</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. שער קיצור אבי\"ע ש\"נ, פ\"י. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550161\" data-slug=\"torat-chaim\" data-id=\"2300550161\">תו\"ח תשא ח\"ב שפד, ד</a> הערה 48. מכתב ה' מ\"ח תש\"י נדפס באג\"ק ח\"ג ע' רו."],["5736","33","<b>היולי. . מקור לד' יסודות</b>: ראה אוה\"ת שמות ע' מה. בשלח ע' שצג. ע' שצה."],["5737","34","<b>היולי. . א\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450556\" data-slug=\"or-hatorah-hb\" data-id=\"8316450556\">אוה\"ת בשלח ע' תרפה</a>. אחרי ע' תקנו. ואתחנן ע' רכח. סה\"מ תרס\"ה רסד רע\"א."],["5738","35","<b>שכתר נק' אצי' שבאצי'</b>: ראה מאמרי אדה\"ז תקס\"ז ע' שיא."],["5739","36","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380255\" data-slug=\"likkutei-torah\" data-id=\"4001380255\">לקו\"ת</b>: בהר מא, ד</a>."],["5740","37","<b>בורא קדושים ישתבח שמך</b>: נוסח ברכת יוצר."],["5741","38","<b>קדושים. . יהללוך סלה</b>: ע\"פ ברכת אתה קדוש."],["5742","39","<b>וכ\"מ בהרמ\"ז</b>: לזהר ויצא קנ, א (ד\"ה חמא). לזהר ר\"פ קרח — קעו, ב. ראה (לעיל בחלק המאמרים) המשך מצה זו כאן (על יד הערות 1012-1013): וכ\"כ. ובהנחות כ\"ק אדמו\"ר מהורש\"ב כאן (על יד הערה 24): וכן פי'."],["5743","40","<b>וכן משמע באשל אברהם</b>: ראה (לעיל בחלק המאמרים) המשך מצה זו כאן הערות 1015־ 1014."],["5744","41","<b>דיבור הוא רק חלק עשירי</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו ספ\"ה ובהערה 198."],["5745","*42","<b>שבאינו</b>: כ\"ה בהכת\"י."]]],[2000470582,"לגבי חכמה רק שנק' בשם חלק עשירי כמו כסף וזהב ונחושת שנק' נחושת חלק א' מזהב כאשר מונחים ביחד כך דיבור נק' חלק עשירי אבל באמת אינו בערך לגבי חכמה כמו נחושת לגבי זהב, ובאמת אפי' הדיבור של הרב אינו מבין התלמיד כמו שהוא כי הוא מלביש את הדיבור באותיות אחרים ומשנה הדיבור והראיי' שהוא אומר אח\"כ זאת הי' כוונתו (בל\"א דאס ה ט ער גימיינט) ממילא מובן שמקודם לא יבין כוונת הרב ובאמת גם אחר כך אינו מבין כמו שהוא, ולבד שלא קאים אינש אדעתי' דרבי'<sup data-n=\"5746\">42</sup> עד ארבעין שנין זהו אדעתי' דרבי' באמת אפי' דיבור של הרב ג\"כ אינו מבין כמו שהוא והראיי' שהוא מדייק אח\"כ מפני מה אמר זה מקודם וזה אח\"כ מסתמא יש בזה כוונה ומסתמא צ\"ל<sup data-n=\"5747\">*43</sup> מפני מה זאת א\"כ מובן שאפי' הדיבור אינו מבין כמו שהוא, כך יובן מה שנמשך מחכמה לבינה זהו רק הארה, והארה ג\"כ אינו מושג כמו שעצם החכמה שנק' אין בדרך תמצא<sup data-n=\"5748\">**43</sup> שאינו משתנה כך אפי' הארת החכמה שנמשך בהשגה והבנה הארה ג\"כ אינו מושג, הגם שברק המבריק<sup data-n=\"5749\">43</sup> נמשך בהשגה והבנה אך זהו רק שברק המבריק מעורר השגה והבנה ומה שמושג ע\"י השגה זהו כאשר נשתנה הברק המבריק ונמשך בהשגה והבנה, ומ\"מ נשאר עצם הברק אינו מושג כמו שאין מהווה מציאת היש שאין עומד תמיד שמחי' בחי' יש ואם לאו הי' אין ואפס<sup data-n=\"5750\">44</sup> מהיש מ\"מ אינו מושג האין שהיש אינו משיג האין, כך ברק המבריק אפי' כאשר נמשך בהשגה נשאר עצם הברק שאינו מושג כמו שעצם החכמה אינו נשתנה כך הארה שנמשך בהשגה אינו מושג, ע\"כ נק' בשם נקודה.\n<b>וכן</b> אפי' יסוד אבא שנמשך מכתר נק' ג\"כ נקודה שנמשך רק הארה כמ\"ש בזוהר<sup data-n=\"5751\">45</sup> ע\"פ (ישעי' כ\"ה) אודה שמך כי עשיתי פלא<sup data-n=\"5752\">46</sup> שיש ב' נקודות נקודה עילאה ונקודה תתאה שמה שנמשך מחכמה בבינה זהו נקודה תתאה וכן מה שנמשך יסוד אבא מכתר זהו ג\"כ רק הארה נק' נקודה אך זהו נקודה עילאה, וכן הוא ג\"כ בא\"א שמה שנמשך מח\"ס באצי' זהו רק נקודה וכן ח\"ס מכתר דא\"א זהו ג\"כ נקודה כו' א\"כ יובן שמה ששבת נק' קדש מלה בגרמה ששבת הוא עליי' עולמות<sup data-n=\"5753\">47</sup> למעלה מעלה, ששרש תיבת שבת הוא מל' שביתה והוא כמשל האדם שעוסק במלאכתו בכתיבת אותיות וכדומה אז יורדים ומתפשטים כחות נפשו ונתצמצם בעסק דבר מעשה ההוא, וכאשר שובת ממלאכתו אז חוזרים כחותי' למקורם ושרשם שנפשט כחות נפשו מהירידה ועולה למקורם ושרשם, כך יובן למעלה כתי' ששת ימים עשה ה'<sup data-n=\"5754\">48</sup> את השמים כי בששת ימים נמשך עד\"מ מבחי' הבל הלב להיות בחי' פרטי",[["5746","42","<b>שלא קאים אינש אדעתי' דרבי'</b>: ראה ע\"ז ה, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540728\" data-slug=\"torat-chaim\" data-id=\"2300540728\">תו\"ח בשלח ח\"א ריז, ג</a> הערה 418. המשך וככה תרל\"ז ספל\"ה."],["5747","*43","<b>ומסתמא צ\"ל</b>: אוצ\"ל: וצ\"ל."],["5748","**43","<b>החכמה. . תמצא</b>: ראה לעיל ע' תנה."],["5749","43","<b>שברק המבריק</b>: ראה גם בענין ברק המבריק (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 21."],["5750","44","<b>שאין עומד תמיד. . אין ואפס</b>: ראה שער היחוד והאמונה פ\"א. פ\"ב."],["5751","45","<b>בזוהר</b>: בלק קצג, ב."],["5752","46","<b>(ישעי' כ\"ה) אודה שמך כי עשיתי פלא</b>: פסוק א [ושם: עשית]."],["5753","47","<b>ששבת הוא עליי' עולמות</b>: נסמן בסמוך הערה 52."],["5754","48","<b>ששת ימים עשה ה'</b>: יתרו כ, יא. תשא לא, יז."]]],[2000470583,"המאמרות יהי אור יהי רקיע<sup data-n=\"5755\">49</sup> אבל ביום השביעי שבת מכל מלאכתו ונתעלו כל העולמות למקורן ושרשן אשר ע\"כ נק' שבת בשם קדש להיותו למעלה מגדר המשכה קדש מלה בגרמי' לכן אז הוא בחי' זווגא דמלכא קדישא עם כנס\"י<sup data-n=\"5756\">50</sup>.\n<b>כי</b> הנה שרש ענין הזווג הוא להוליד נשמות חדשות דוקא וכתי' אין כל חדש תחת השמש<sup data-n=\"5757\">51</sup> אחר שכבר נתהוו סדרי השתלשל' אין כל חדש שאינו נמשך בחי' התחדשות לגמרי כ\"א שנמשך רק לחזק הישינות בלבד כו'. אבל בשבת שהוא בחי' עליי' העולמות<sup data-n=\"5758\">52</sup> למקורן ושרשן ובחי' זו הוא למעלה מן השמש שהוא בחי' סדר השתלשל', שקדש בעצם אינו בגדר המשכה, אז מתגלים נשמות חדשות<sup data-n=\"5759\">53</sup> ע\"י בחי' יחוד כנס\"י עם מלכא קדישא. ולהבין ענין השמש יובן ע\"פ מ\"ש בהרמ\"ז שאור הגנוז הוא פנימי' יסוד אבא<sup data-n=\"5760\">54</sup> דכתי' בו ופני לא יראו<sup data-n=\"5761\">55</sup> אבל הארה משם חיצוני' מיסוד אבא נמשך בתפארת דז\"א וזהו\"ע שמש, שמה שתמצא בזוהר ובקדמונים שהתפארת ה\"ס השמש ירצה לומר אור זעיר שמצד אבא פי' חיצוני' מיסוד אבא והוא מאיר לכל דכתי' כולם בחכמה עשית<sup data-n=\"5762\">56</sup>, אבל עצם יסוד אבא הוא לעילא משמשא ועליי' שבת הוא בבחי' זו ומשם נמשך נשמות חדשות. לפ\"ז צ\"ל שיש בזה ג' מדרגות הא' הוא בחי' הארת יסו\"א שמאיר בז\"א ושם אין כל חדש כ\"א לחזק הישינות כמ\"ש המחדש בטובו בכי\"ת<sup data-n=\"5763\">57</sup> שבכל יום נמשך חיות חדש אבל זהו רק חידוש הישינות, ויסו\"א בעצמו הוא למעלה מן השמש ושם יש כל חדש לחדש נשמות חדשות וזהו מדרגה הב', ובחי' הג' זהו פנימי' יסו\"א שמבחי' זו א\"א להמשיך עכשיו כי פנימי' אבא הוא חשוב כפנימי' עתיק<sup data-n=\"5764\">58</sup>, ולכן בשבת כשנתעלה בבחי' קדש שלמעלה מהשתל' אז הזיווג על התגלות אור לבד והוא בחי' נשמות חדשות כו'.\n<b>והנה</b> בחי' יחוד זה הוא בכנס\"י דוקא כדכתי' ה' בחכמה יסד ארץ וכונן שמים בתבונה<sup data-n=\"5765\">59</sup> הגם שיש בשמים ג\"כ חכמה מ\"מ כונן שמים בתבונה ובחכמה יסד ארץ, וצ\"ל איך ארץ שהוא למטה במדרגה משמים יסודתה מחכמה דוקא ושמים שהם רוחני' יותר מארץ הם מהבינה. והענין הוא הנה שמים הוא בחי' אש ומים<sup data-n=\"5766\">60</sup>",[["5755","49","<b>יהי אור יהי רקיע</b>: בראשית א, ג. ו."],["5756","50","<b>זווגא דמלכא קדישא עם כנס\"י</b>: ראה זהר אמור ק, ב."],["5757","51","<b>אין. . תחת השמש</b>: קהלת א, ט [ושם: ואין]. ראה גם מאמרי אדה\"א דברים ח\"א ע' רעו."],["5758","52","<b>בשבת שהוא בחי' עליי' העולמות</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540867\" data-slug=\"torat-chaim\" data-id=\"2300540867\">תו\"ח בא ח\"א קכז, א</a> הערה 667."],["5759","53","<b>בשבת. . נשמות חדשות</b>: ראה גם ביאוה\"ז תרומה כרך ב ע' תתיט ואילך ובהנסמן שם."],["5760","54","<b>בהרמ\"ז שאור הגנוז הוא פנימי' יסוד אבא</b>: ר\"פ בהעלותך קמח, ב (ד\"ה והוא שמשא וכו')."],["5761","55","<b>ופני לא יראו</b>: תשא לג, כג."],["5762","56","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["5763","57","<b>המחדש בטובו בכי\"ת</b>: ברכת יוצר. ראה גם לעיל הנחה ד\"ה מי כהוי' אלקינו ובהערה 41."],["5764","58","<b>פנימי' אבא. . כפנימי' עתיק</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380918\" data-slug=\"likkutei-torah\" data-id=\"4001380918\">לקו\"ת נצבים מט, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541072\" data-slug=\"torat-chaim\" data-id=\"2300541072\">תו\"ח שמות ח\"א כג, א</a> הערה 951."],["5765","59","<b>ה' בחכמה יסד ארץ וכונן שמים בתבונה</b>: משלי ג, יט [ושם: כונן]."],["5766","60","<b>שמים. . אש ומים</b>: ראה חגיגה יב, סע\"א. רש\"י בראשית א, ח."]]],[2000470584,"חו\"ג<sup data-n=\"5767\">61</sup> וע\"כ תיבת מים יש בפירוש בשמים ואש רק אות ש'<sup data-n=\"5768\">62</sup> והאלף יוצא מקמ\"ץ ש מים, מפני שז\"א רובו חסדים<sup data-n=\"5769\">63</sup>. והנה חסד הוא בחי' אהבה<sup data-n=\"5770\">64</sup> ואהבה הוא יש מי שאוהב<sup data-n=\"5771\">65</sup> שנולד מן התבוננות ויש מי שאוהב דבר זה, אינו דומה<sup data-n=\"5772\">66</sup> בחי' יראה הוא<sup data-n=\"5773\">*67</sup> מצד הביטול שיראה הוא מצד הקירוב כאשר מתבונן ומשיג בהשגה אז הוא קרוב לאלקות מצד שנופל עלי' יראה ובטל בתכלית, אבל אהבה הוא יש מי שאוהב שאהבה הוא מצד התבוננות כאשר מתבונן שדבר זה טוב לפניו אז נולד אצלו אהבה שאינו שייך שאדם יחפוץ דבר מה שאינו מתבונן שדבר זה טוב לפניו ומובן בשכלו, אלא מפני שמתבונן בשכלו שדבר זה טוב כמו למשל כאשר מתבונן שאדם זה הוא איש נגבה וגם<sup data-n=\"5774\">68</sup> (בל\"א ער איז א גרוגט פאהן<sup data-n=\"5775\">67</sup> אים) עי\"ז נמשך אחריו וכרוך אחריו שמשתוקק לו שזהו מצד התבוננות בשכלו שעי\"ז בא לאהבה שיש מי שאוהב, וזהו כונן שמים בתבונה שמדות נמשך מבינה<sup data-n=\"5776\">69</sup> כמו באדם כאשר מתבונן שטוב לפניו דבר ההוא ה\"ה אוהב דבר ההוא כן למעלה שמדות נמשך מבינה ע\"כ כונן שמים בתבונה שבינה דינין מתערין מינה בסופו<sup data-n=\"5777\">70</sup> שאחר שנמשך בהשגה והבנה שייך שיומשך ע\"י הבנה זו לאהוב את הדבר או להיפך לשנוא אותה שהוא בחי' יש מי שאוהב מפני שנמשך מבינה שהוא מקור היש, ובחכמה יסד ארץ כמ\"ש בזוהר כד ברא קוב\"ה עלמא<sup data-n=\"5778\">71</sup> חמי דלא יכיל לאתקיימא עד דברא אורייתא, קודב\"ה היינו או\"ס<sup data-n=\"5779\">72</sup>, עלמא עולם האצי', חמי דלא יכיל לאתקיימא ברא אורייתא שהיא בחי' חכמה ובחכמה יסד ארץ.\n<b>והנה</b> אנו רואים שארץ הוא בטל לכולם שהכל דורסים עלי' וכל הבנינים בונים עלי' וכל הצמיחה הוא על הארץ שבטל לכל. והנה ארץ הוא בחי' מל'<sup data-n=\"5780\">73</sup> וזהו רק ביטול היש כמו עבד שמשתחווה לאדונו שמרכין ראשו ורגלו בשוה כמו שהרגל אינו מראה למלך איך להתנהג הנהגות המלוכה כך הראש אינו מראה לו בהנהגת המלוכה, אך זהו ביטול היש, ובחכמה יסד ארץ הגם שחכמה הוא ביטול אמיתי מ\"מ יש מעלה בביטול היש לגבי ביטול אמיתי כי ביטול אמיתי היינו שאין שום מציאות",[["5767","61","<b>שמים. . חו\"ג</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו כאן פל\"ב ובהערה 1039."],["5768","62","<b>שמים. . מים. . ואש רק אות ש'</b>: ראה לעיל שם ובהערה 1038."],["5769","63","<b>שז\"א רובו חסדים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670441\" data-slug=\"torat-chaim\" data-id=\"2300670441\">תו\"ח וירא קד, ד</a> ובהערה 33."],["5770","64","<b>חסד הוא בחי' אהבה</b>: ראה פרדס שער עה\"כ שכ\"ג, פ\"א מערכת אהבה."],["5771","65","<b>יש מי שאוהב</b>: מובא בכ\"מ בדא\"ח ומהם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370251\" data-slug=\"torah-or\" data-id=\"3901370251\">תו\"א וארא נו, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370302\" data-slug=\"torah-or\" data-id=\"3901370302\">יתרו סז, ג</a>. סה\"מ תרל\"ח ס\"ע קלה. וש\"נ."],["5772","66","<b>ויש מי שאוהב. . אינו דומה</b>: להבא להלן ראה (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 54 ואילך."],["5773","*67","<b>אינו. . הוא</b>: אוצ\"ל: ואינו דומה לבחי' יראה שהוא."],["5774","68","<b>וגם</b>: אולי מקום תיבה זו אחרי הסוגר."],["5775","67","<b>נגבה. . גרוגט פאהן</b>: כ\"ה בהכת\"י."],["5776","69","<b>שמדות נמשך מבינה</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו כאן פל\"ב ובהערה 1043."],["5777","70","<b>שבינה דינין מתערין מינה בסופו</b>: ראה זהר ויקרא י, סע\"ב. יא, רע\"א. מאמרי אדה\"א דברים ח\"ב ע' שעז. וש\"נ."],["5778","71","<b>בזוהר כד ברא קוב\"ה עלמא</b>: ויגש רז, א."],["5779","72","<b>או\"ס</b>: ועד\"ז הובא בסמוך על יד הערה 95. ראה גם לקמן הנחה ד\"ה ויאמר משה אל העם אל תיראו ובהערה 34. אולי צ\"ל: א\"ס־ או אוא\"ס."],["5780","73","<b>ארץ הוא בחי' מל'</b>: ראה זהר תוספתא בראשית לא, ב."]]],[2000470585,"בטל בתכלית ולא נחשב למאומה א\"כ זה אינו רבותא כ\"כ כיון שהוא אין שום מציאות אינו רבותא שהוא בטל אבל ביטול היש הו\"ע הגם שהוא מציאות היש מ\"מ הוא בטל, כ\"א הי' אין שום מציאות זהו ביטול אמיתי, אלא הגם שהוא מציאות היש מ\"מ הוא בטל ע\"כ יש מעלה באתכפי' לגבי אתהפכא. מ\"מ אינו דומה לביטול אמיתי כי ביטול אמיתי היינו שהוא בטל בתכלית אבל ביטול היש היינו שהוא מציאות היש רק שהוא בטל, כמו כאשר העבד מרכין ראשו ורגלו הגם שראשו ורגלו שוה אז אצלו, מ\"מ יש מציאות ראש ורגל שהוא מציאות היש רק שהוא בטל כו'. ע\"כ ה' בחכמה יסד ארץ.\n<b>וע\"כ</b> אנו רואים ששם אחד לשניהם כמו משה עבדי<sup data-n=\"5781\">74</sup> דוד עבדי<sup data-n=\"5782\">75</sup> ששניהם נק' עבד, משה עבדי בחי' חכמה כמ\"ש ואנחנו<sup data-n=\"5783\">76</sup> מ\"ה<sup data-n=\"5784\">77</sup> שהי' בחי' מ\"ה דחכמה ביטול עצמי, דוד עבדי הוא בחי' מל'<sup data-n=\"5785\">78</sup> שהי' מרכבה לבחי' מל' וע\"כ אמר אנוכי תולעת ולא איש<sup data-n=\"5786\">79</sup> חרפת אדם ובזוי עם, וע\"כ שניהם נק' חכמה היינו חכמה בראש וחכמה בסוף<sup data-n=\"5787\">80</sup>, שניהם נק' יראה, יראה עילאה ויראה תתאה הכל שם אחד רק זה עילא' וזה תתא', כי בחי' החכמה היא שרש ומקור לבחי' המל' כדכתי' ה' בחכמה יסד ארץ, ובשבת עליי' העולמות בביטול דחכמה כו'.\n<b>ובד\"כ</b> ההפרש בין שבת לחול כמו עד\"מ כאשר המל' יוצא לעבדו לחוץ שישתחוה העבד להמלכות<sup data-n=\"5788\">81</sup> זהו רק ביטול היש שהעבד הוא על מקומו רק שהעבד הוא בטל כמו שדרך המל' שעובר על מדינתו שהעם בטל לפני המלך וצריך להיות בטל וכן ראוי להיות שעבד יהי' בטל לפני המלך אבל זהו רק ביטול היש כי העבד הוא על מקומו, אבל כאשר העבד נכנס לפני ולפנים מחדר לפנים מחדר ובא לפני אדונו להשתחוות אלי' אז הוא בטל בתכלית, כך יובן שבששת ימי החול הוא עד\"מ המל' שיוצא עבדו<sup data-n=\"5789\">82</sup> לחוץ שזהו רק ביטול היש, אבל בשבת הוא עליי' העולמות היינו כמו שהעבד נכנס לפני ולפנים ובודאי אינו דומה ההשתחוואה שבחוץ להשתחוואה שבפנים, ולכן בשבת כשמתעלה לבוא לשרש ומקור האמיתי בחי' הביטול עצמי אז נעשה הזווג להוליד נשמות, זווגא דכנס\"י במלכא קדישא להוליד נשמות חדשות, אך זהו רק גילוי אור כללי וע\"י מטרוניתא שבה יש ה\"ג מנצפ\"ך<sup data-n=\"5790\">83</sup>",[["5781","74","<b>משה עבדי</b>: יהושע א, ב. ז. מלאכי ג, כב."],["5782","75","<b>דוד עבדי</b>: שמואל-ב ג, יח. ועוד. ראה גם מאמרי אדה\"ז תקס\"ז ע' שסט."],["5783","76","<b>ואנחנו</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה הנה אנכי כורת ברית ובהערה 29."],["5784","77","<b>ואנחנו מ\"ה</b>: ראה לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח ספכ\"א הערה 593."],["5785","78","<b>דוד. . מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דוד. הנסמן המאמרי אדה\"א דברים ח\"ג ע' תתקט."],["5786","79","<b>אנוכי תולעת ולא איש</b>: תהלים כב, ז [ושם: ואנכי — ראה גם לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אשריכם זורעי על כל מים ובהערה 114]."],["5787","80","<b>חכמה בראש וחכמה בסוף</b>: ראה זהר בראשית כו, ב. שעה\"י קמג, א הערה 8."],["5788","81","<b>המל'. . להמלכות</b>: אוצ\"ל: המלך. . להמלך."],["5789","82","<b>עבדו</b>: אוצ\"ל: לעבדו."],["5790","83","<b>ה\"ג מנצפ\"ך</b>: ראה שער היחוד והאמונה ספ\"ד. מאמרי אדה\"א ויקרא ח\"א ע' רלז. וש\"נ."]]],[2000470586,"המחלקים לנשמות אברהם לבד יצחק לבד כ\"א בפ\"ע ולכן עיקר הלידה הוא ע\"י מטרוניתא, וזהו זוווגא דכנס\"י במלכא קדישא כי השפעה שמקבלת בחי' המל' מחכמה עוברת דרך ז\"א וע\"כ נק' מלכא כי ז\"א נק' מלכא אך מ\"מ קדישא מפני כי בשבת עליי' ז\"א באו\"א וע\"כ נק' מלכא קדישא<sup data-n=\"5791\">84</sup>. ולהיות כי כל השפעה הוא באתעדל\"ת אתעדל\"ע<sup data-n=\"5792\">85</sup>, א\"כ דעת לנבון נקל<sup data-n=\"5793\">86</sup> שבשבת צ\"ל בבחי' מל' העלאת מ\"ן באופן אחר שלא כמו העלאת מ\"ן שביומין דחול ולפ\"ע העלאת מ\"ן כן נמשך המשכת מ\"ד<sup data-n=\"5794\">87</sup>. וזהו שא' בזוהר מהיכן הכח לבחי' מל' להעלות מ\"ן גבוה כזו ועז\"א בזימנא דנטלא מבי אבא<sup data-n=\"5795\">88</sup>, והיינו כי בחול יש ג\"כ זיווג בשמ\"ע<sup data-n=\"5796\">89</sup> על השפעה לחדש הישינות כו' אמנם כל השפעה דחול הוא הכל למטה מן השמש והיינו מה שנמשך בסדר השתל' הגם שזהו בחיק הבורא כי אפי' מתכנשים כל באי עולם<sup data-n=\"5797\">90</sup> אין יכול לברוא אפי' כנף יתוש א' מ\"מ זהו בסדר השתל' ושרשם מבחי' הבינה ולפי שבינה דינין מתערין מינה לכן אברהם יצא ממנו ישמעאל<sup data-n=\"5798\">91</sup> וכן עד\"מ הצפרנים הגדלים מן הידים ותחת הצפרנים א\"ל צואה כו', וכן כל העבודה דחול הוא רק לבוא לבחי' אתכפי' להיות כי שרש המשכה הוא מבחי' בינה א\"א לבוא לבחי' אתהפכא, אבל בשבת הו\"ע עליי' עולמות שעליי' בבחי' קדש מלה בגרמי' ע\"כ יכול להיות העלאת מ\"ן בבחי' אתהפכא מי לי בשמים ועמך לא חפצתי בארץ<sup data-n=\"5799\">92</sup>, שמו\"א הוא געה\"ע וגעה\"ת<sup data-n=\"5800\">93</sup> שאינו צריך לחפוץ לא געה\"ע ולא געה\"ת אפי' מקור החיים ומקור התענוגים<sup data-n=\"5801\">94</sup> אינו צריך לחפוץ רק רצון פשוט לאו\"ס<sup data-n=\"5802\">95</sup> עצמותו כו', ולפ\"ע אתעדל\"ת כן נמשך מלמעלה להוליד נשמות חדשות, ויו\"ט שחל להיות בחול עיקר ההמשכה מאימא דרך השתלשל' רק שבהעלם יש בה הארת יסו\"א לכן נק' מקרא קדש שממשיכים הארה מקדש וזהו קדוש בוא\"ו שנשתנה שוא\"ו אינו יו\"ד כו', אבל שבת נק' קדש ששבת הוא עליי' עולמות בבחי' קדש מלה בגרמי' כו'.",[["5791","84","<b>ז\"א. . מלכא קדישא</b>: ראה זהר בשלח נה, א ובמק\"מ שם."],["5792","85","<b>באתעדל\"ת אתעדל\"ע</b>: ראה זהר לך פח, א. מאמר ד\"ה לרוקע נדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' קצד [ובמקביליו ובהנסמן במ\"מ לשם]. מאמרי אדה\"א דברים ח\"א ע' קצח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a> ובהערה 189."],["5793","86","<b>דעת לנבון נקל</b>: משלי יד, ו."],["5794","87","<b>ולפ\"ע העלאת מ\"ן. . מ\"ד</b>: ראה גם מאמרי אדה\"א קונטרסים ע' שעט [ושם: הכלל הידוע]. שה\"א כו, ב ובהערה 29."],["5795","88","<b>בזימנא דנטלא מבי אבא</b>: ראה זהר אמור ק, ב."],["5796","89","<b>בחול יש ג\"כ זיווג בשמ\"ע</b>: ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח כאן פרק ג\"ל ובהערה 1060."],["5797","90","<b>אפי' מתכנשים כל באי עולם</b>: ראה ירושלמי סנהדרין ספ\"ז. ספרי ואתחנן ו, ה. ב\"ר פל\"ט, יד. וש\"נ. אוה\"ת בראשית כרך ו ע' 2040. המשך מים רבים תרל\"ו פכ\"ה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261455\" data-slug=\"likkutei-sichot\" data-id=\"1300261455\">לקו\"ש משפטים כרך כו ע' 366</a>."],["5798","91","<b>אברהם יצא ממנו ישמעאל</b>: ראה פסחים נו, א. מאמרי אדה\"א דברים ח\"ג ע' א'קטו ואילך. וש\"נ. שע\"ת פה, ג ובהערה 14. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540876\" data-slug=\"torat-chaim\" data-id=\"2300540876\">תו\"ח בא ח\"א קכז, ב</a>."],["5799","92","<b>מי לי בשמים. . בארץ</b>: תהלים עג, כה. ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גל נעול ובהערה 65. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פכ\"ב. וש\"נ."],["5800","93","<b>שמו\"א הוא געה\"ע וגעה\"ת</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת פ' ראה כה, א</a>. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 154."],["5801","94","<b>מקור החיים ומקור התענוגים</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 50."],["5802","95","<b>לאו\"ס</b>: ראה לעיל הערה 72."]]],[2000470587,"<b>ועפ\"ז</b> יובן מ\"ש וביום הבכורים בהקריבכם מנחה חדשה לה', שחגה\"ש לבד שהוא השלמת ז' שבועות עוד בשבועות הי' מ\"ת<sup data-n=\"5803\">96</sup>, הגם שבחגה\"ש גילוי שעה\"נ דבינה<sup data-n=\"5804\">97</sup> אך בשבועות הי' מ\"ת שנמשך בחי' תורה למטה מטה ואורייתא מחכמה נפקת<sup data-n=\"5805\">98</sup> ונמשך למטה ואחר כל הלבושים שנתלבש למטה יש בחי' חכמה למטה מטה ע\"כ אפי' חמץ אפשר להתברר ע\"כ הי' שתי הלחם מחמץ, כי בכל יו\"ט הוא רק מקרא קדש שבעצם נמשך בחי' בינה ובבחי' בינה דינים מתערין מינה בסופא ע\"כ א\"א חמץ להתברר אבל בשבועות שהי' מ\"ת ויורד ה' על הר סיני<sup data-n=\"5806\">99</sup> שנמשך המשכת התורה למטה ע\"כ אפשר אפי' חמץ להתברר, וזהו סולת תהיינה חמץ תאפינה פי' סולת היינו להראות שנקי מכל דבר כי בקרבן שהוא בחי' אש היינו בחי' בירורים אבל סולת היינו להראות שנקי מכל דבר והתנשאות הוא בקדושה כמ\"ש ויגבה לבו בדרכי ה'<sup data-n=\"5807\">100</sup> וע\"כ הי' קציר חיטים<sup data-n=\"5808\">101</sup> חיטה הוא כ\"ב אתוון דאורייתא<sup data-n=\"5809\">102</sup>, הגם שזה הי' אכילת כהנים אך באמת הנה הקרבנות שהקריבו היינו פני ארי'<sup data-n=\"5810\">103</sup> ופני שור זהו רק מבהמה אבל כאן הוא אכילת אדם כמ\"ש ועל הכסא דמות כמראה אדם עלי' מלמעלה<sup data-n=\"5811\">104</sup> וע\"י אכילת כהנים הגביהו אדם שעהכ\"ס לבחי' כי לא אדם<sup data-n=\"5812\">105</sup> א\"כ זה אינו לגריעותא כו', ע\"כ הי' א\"ל אפי' מחמץ, הגם שבכל שבת מפני מה ג\"כ לא הקריבו מחמץ אך בשבת הוא רק עליי' עולמות הגם שעליי' במוחין דאבא אבל רק עליי' וזהו כמו למשל א' שהולך לפני ולפנים שא\"א להכניס גם חמץ בשם כך בשבת א\"א להקריב מחמץ אבל בחגה\"ש וירד ה' כו' שנמשך המשכת אלקות מלמעלה ע\"כ אפי' חמץ אפשר להתברר, הגם שהכל מודים שבשבת הי' מ\"ת<sup data-n=\"5813\">106</sup> פי' שמ\"ת הי' במדרגת שבת כמו שבת הוא עליי' בקדש מלה בגרמי' כך שבועות הוא גילוי בחי' קדש אבל אינו דומה לשבת ששבת הוא רק עליי' אבל בשבועות הוא המשכ' מלמעלה ע\"כ אפשר אפי' חמץ להתעלות, וזהו מנחה חדשה שזהו התחדשות שאפי' חמץ יתעלה, וזהו וביום הבכורים בהקריבכם מנחה חדשה כו'.",[["5803","96","<b>בשבועות הי' מ\"ת</b>: ראה נוסח התפלה וקידוש לשבועות. שו\"ע אדה\"ז חאו\"ח סתצ\"ד, ס\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081021\" data-slug=\"likkutei-sichot\" data-id=\"1300081021\">לקו\"ש שבועות כרך ח ע' 21</a>."],["5804","97","<b>שבחגה\"ש גילוי שעה\"נ דבינה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370309\" data-slug=\"torah-or\" data-id=\"3901370309\">תו\"א יתרו סט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380351\" data-slug=\"likkutei-torah\" data-id=\"4001380351\">לקו\"ת במדבר י, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380355\" data-slug=\"likkutei-torah\" data-id=\"4001380355\">יא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380356\" data-slug=\"likkutei-torah\" data-id=\"4001380356\">יב, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381310\" data-slug=\"likkutei-torah\" data-id=\"4001381310\">שה\"ש מה, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540330\" data-slug=\"torat-chaim\" data-id=\"2300540330\">תו\"ח בא ח\"א קיז, ג</a> ובהערה 132."],["5805","98","<b>ואורייתא מחכמה נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["5806","99","<b>ויורד </b>[בסמוך בפנים מובא: וירד]<b> ה' על הר סיני</b>: יתרו יט, כ."],["5807","100","<b>ויגבה לבו בדרכי ה'</b>: דהי\"ב יז, ו. ראה גם כש\"ט קה\"ת סשצ\"ג (נז, א ואילך)."],["5808","101","<b>קציר חטים</b>: תשא לד, כב."],["5809","102","<b>חטה הוא כ\"ב אתוון דאורייתא</b>: ראה זהר בלק קפח, ב. ת\"ז תס\"ט (קיד, א. ב)."],["5810","103","<b>הקרבנות שהקריבו היינו פני' ארי'</b>: ראה (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 74 ואילך: אכילת מזבח הוא ארי' דאכיל קורבנין והיינו ד' חיות המרכבה."],["5811","104","<b>ועל הכסא דמות. . מלמעלה</b>: יחזקאל א, כו [בדילוג]."],["5812","105","<b>כי לא אדם</b>: שמואל-א טו, כט."],["5813","106","<b>שהכל מודים שבשבת הי' מ\"ת</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 78. המשך תער\"ב ח\"ב ע' א'צא: וכמא' הכל מודים כו'. שבת פו, ב. תורת לוי יצחק תענית ג, רע\"א."]]],[2000470588,"<b>הגם</b><sup data-n=\"5814\">107</sup> שאכילה של שבת אינו מגשם<sup data-n=\"5815\">108</sup> היינו מפני שרע נפרד מן הטוב מ\"מ שיתעלה החמץ למעלה זה א\"א שאין דרך להכניס חמץ בהיכל המלך לפני ולפנים כמו עד\"מ מאן דמחוי במחוג קמי' מלכא<sup data-n=\"5816\">109</sup> כו' כך למעלה א\"א שיתעלה החמץ אבל במ\"ת שהי' גילוי למטה ע\"כ אפי' חמץ נתעלה כו'.\n<b>ע'</b> ד\"ה וככה תאכלו אותו<sup data-n=\"5817\">110</sup> סי' ל\"ו ל\"ז, ע' בה\"ז אמור<sup data-n=\"5818\">111</sup>.",[["5814","107","<b>הגם</b>: שני קטעים הבאים נרשמו מעבר לדף בשולי היריעה."],["5815","108","<b>שאכילה של שבת אינו מגשם</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקעו. וש\"נ. קונטרסים ע' רמב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540256\" data-slug=\"torat-chaim\" data-id=\"2300540256\">תו\"ח בשלח ח\"א רי, ד</a> ובהערה 77. סה\"מ תרל\"ח ע' שפ."],["5816","109","<b>מאן דמחוי במחוג קמי' מלכא</b>: ראה חגיגה ה, ב."],["5817","110","<b>ד\"ה וככה תאכלו אותו</b>: המשך וככה תרל\"ז. ראה גם הנסמן לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 998."],["5818","111","<b>בה\"ז אמור</b>: ראה לעיל הערה 23."]]],[2000470589,"<h3>ויאמר משה אל העם אל תיראו</h3>\n<b></b><b>בס\"ד ביום ב' דחגה\"ש ש' תר\"ם לד\"ה מצה זו </b>\nב' דחגה\"ש\nהנחה\n(יתרו ך') ויאמר משה אל העם אל תיראו<sup data-n=\"5819\">1</sup> כי לבעבור נסות אתכם בא האלקים ובעבור תהי' יראתו על פניכם לבלתי תחטאו<sup data-n=\"5820\">2</sup>. הנה לכאורה צ\"ל איך אמר משה אל תיראו איך אפשר להיות שמשה יגיד להם שלא יראו ח\"ו, הלא באמת העיקר הוא יראה כמ\"ש ועתה ישראל מה ה' אלקיך שואל מעמך כ\"א ליראה<sup data-n=\"5821\">3</sup>, ויצווינו ה' לעשות כל החוקים האלה ליראה<sup data-n=\"5822\">4</sup>, את ה' אלקיך תירא<sup data-n=\"5823\">5</sup>, למען תירא<sup data-n=\"5824\">6</sup>, סוף דבר הכל נשמע את אלקים ירא<sup data-n=\"5825\">7</sup> ואת מצותיו שמור כי זה כל האדם, שתכלית המכוון של האדם הוא בשביל היראה וגם יראה היא מקור לשס\"ה ל\"ת<sup data-n=\"5826\">8</sup> ואיך אמר משה אל תיראו<sup data-n=\"5827\">9</sup>, גם צ\"ל הלא אח\"כ כתי' לבעבור כו' בא אלקים ובעבור תהי'",[["5819","1","<b>ויאמר משה אל העם אל תיראו</b>: הנחה ממאמר כ\"ק אדמו\"ר מהר\"ש ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים בהמשך מצה זו פל\"ד-פל\"ו. וש\"נ.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נמצא רק הפסוק ולא רשם יותר ונדפס לעיל (בחלק הנחותיו)."],["5820","2","<b>(יתרו ך') ויאמר משה אל העם אל תיראו. . בא האלקים. . לבלתי תחטאו</b>: פסוק יז."],["5821","3","<b>ועתה ישראל מה ה'. . כ\"א ליראה</b>: עקב י, יב."],["5822","4","<b>ויצווינו ה' לעשות. . ליראה</b>: ואתחנן ו, כד [בדילוג]."],["5823","5","<b>את ה' אלקיך תירא</b>: שם ו, יג. עקב י, כ."],["5824","6","<b>למען תירא</b>: ואתחנן שם, ב."],["5825","7","<b>סוף דבר. . אלקים ירא</b>: קהלת יב, יג [ושם: האלקים]."],["5826","8","<b>יראה היא מקור לשס\"ה ל\"ת</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>. (לעיל בחלק המאמרים) המשך מצה זו הערה 772."],["5827","9","<b>ואיך אמר משה אל תיראו</b>: ראה גם מאמרי אדה\"ז הקצרים ע' ס. סה\"מ תרל\"ח ע' קמו."]]],[2000470590,"יראתו על פניכם לבלתי תחטאו א\"כ כיון שבא אלקים שתהי' יראתו ואיך אמר משה אל תיראו כו'.\n<b>להבין</b> זאת צ\"ל תחלה ההפרש בין אהבה ויראה, הנה יראה נק' זאת, בזאת יבוא אהרן אל הקדש שע\"י זאת בחי' יראה<sup data-n=\"5828\">10</sup> יבוא אל הקדש, ואהבה נק' זה כמ\"ש זה אלי ואנווהו<sup data-n=\"5829\">11</sup>. הנה תיבת אנוהו הוא תיבה מורכבת אני<sup data-n=\"5830\">12</sup> והוא<sup data-n=\"5831\">13</sup>, פי' הוא דבר שנסתר ונעלם כמ\"ש אתה הוא ה' אלקים<sup data-n=\"5832\">14</sup> שלמעלה מבחי' נאצלים, אני והוא היינו מה שלמעלה מנאצלים שיתגלה בבחי' גילוי בנאצלים כמו עד\"מ כאשר האדם שואל איש אחד אי' אדם ההוא שמזה מוכח שאדם ההוא נסתר ונעלם מאיתו שאינו יודע היכן הוא, וכאשר יפגע באדם זה גופא ושואל אצלו היכן אדם והושיב<sup data-n=\"5833\">15</sup> לו שזה אני בעצמי אותו אדם שאתה מבקש אותו, כך אני והוא שזה שנסתר ונעלם למעלה מנאצלים יתגלה בנאצלים וזהו אני והוא, ע\"פ פשוט אנוהו לשון נוי<sup data-n=\"5834\">16</sup> שקאי על בחי' ת\"ת כי התחלת אצי' הוא מא\"א כי א\"א הוא שרש וראש ומקור לנאצלים<sup data-n=\"5835\">17</sup> ע\"כ שייך לאצי' אבל כתר בכלל הוא למעלה מאצי' וע\"י שת\"ת עולה עד הכתר<sup data-n=\"5836\">18</sup> עי\"ז נמשך המשכת הכתר בבחי' ת\"ת וזהו עיקר הנוי ויופי כו'. אך זהו רק קדוש וא\"ו שהמשכת הקו הוא ע\"י וא\"ו כו', אבל כדי שיגיעו לבחי' קדש<sup data-n=\"5837\">19</sup> היינו ע\"י זאת כמ\"ש בזאת יבוא אהרן אל הקדש.\n<b>להבין</b> זאת הנה ארז\"ל במד\"ר לא זז הקב\"ה מחבבה<sup data-n=\"5838\">20</sup> לכנס\"י עד שקראה אמי, כי תחלה איתא במד\"ר לא זז מחבבה עד שקראה בתי אחותי עד שאח\"כ קראה אמי לכאורה צ\"ל איך קראה הקב\"ה לכנס\"י בשם אמי, אך זה קאי על מ\"ת שבעת מ\"ת קרא הקב\"ה לכנס\"י בשם אמי כמ\"ש בעטרה שעטרה לו אמו<sup data-n=\"5839\">21</sup> ביום חתונתו, ביום חתונתו זו מ\"ת<sup data-n=\"5840\">22</sup>, שבעת מ\"ת אמו כנס\"י מעטר בכתר להקב\"ה, ומה שנק' בשם אם כמו שהאם מברך את בני' כך כנס\"י מברך להקב\"ה. אך צ\"ל מה צריך הקב\"ה ברכת של כנס\"י.",[["5828","10","<b>בזאת יבוא אהרן אל הקדש. . יראה</b>: אחרי טז, ג. ראה זהר אחרי נו, ב. בהר קח, א. מאמרי אדה\"א ויקרא ח\"א ע' סב. וש\"נ."],["5829","11","<b>ואהבה. . זה אלי ואנווהו</b>: בשלח טו, ב. ראה (לעיל בחלק המאמרים) המשך מצה זו כאן הערה 1084."],["5830","12","<b>אנוהו. . אני והוא</b>: ראה של\"ה בעשרה מאמרות המאמר הראשון מ, א. (לעיל בחלק המאמרים) כאן הערה 1088."],["5831","13","<b>והוא</b>: בשל\"ה שם: והו — ראה גם לעיל שם ובהערה 1089."],["5832","14","<b>אתה הוא ה' אלקים</b>: כ\"ה בכת\"י."],["5833","15","<b>אדם והשיב</b>: אוצ\"ל: אדם זה והשיב."],["5834","16","<b>אנוהו לשון נוי</b>: ראה רש\"י בשלח טו, ב."],["5835","17","<b>א\"א הוא שרש וראש ומקור לנאצלים</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א."],["5836","18","<b>שת\"ת עולה עד הכתר</b>: ראה שערי אורה לר\"י גיקטלייא שער ה (סג, ב)."],["5837","19","<b>קדוש וא\"ו. . קדש</b>: ראה ביאוה\"ז אמור פ, ג. ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה הנה אנכי כורת ברית הערה 30."],["5838","20","<b>לא זז הקב\"ה מחבבה</b>: ראה פדר\"כ פסקא א ויהי ביום כלות משה. הנסמן במ\"מ ל<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">לקו\"ת שה\"ש כא, ב</a>."],["5839","21","<b>בעטרה שעטרה לו אמו</b>: שה\"ש ג, יא."],["5840","22","<b>ביום חתונתו זו מתן תורה</b>: תענית כו, ב (במשנה). ראה מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' לד. מאמרי אדה\"א דברים ח\"ג ע' תתמז בהערה."]]],[2000470591,"<b>להבין</b> זאת צריך להבין תחלה מה שנק' שם ה' בלשון חכמים הקב\"ה<sup data-n=\"5841\">23</sup>, שלכאורה אינו מובן מהו\"ע ברוך כי קדוש א\"ל להראות שהוא קדוש ומובדל אבל מהו\"ע ברוך. אך הענין הוא הנה אנו רואים שנתהווה ריבוי התהוות הנבראים בהתחלקות כל א' מחבירו, כמו מה גדלו מעשיך ה'<sup data-n=\"5842\">24</sup>, שקאי על נבראים הגדולים דהיינו מלאכים שמלאך בשליש עולם עומד<sup data-n=\"5843\">25</sup> שבעולם שלנו לא נמצא כזאת, וכן אלף אלפים ישמשוני'<sup data-n=\"5844\">26</sup> ורבו רבבן כו', היש מספר לגדודי'<sup data-n=\"5845\">27</sup>, אלף אלפים היינו גדוד א' ולגדודיו אין מספר<sup data-n=\"5846\">28</sup>, מ\"מ הרי הם בבחי' התחלקות אלא שההתחלקות הוא עד אין קץ וכמו מחנה מיכאל קפ\"ו אלף<sup data-n=\"5847\">29</sup> מחנות ומחנה גבריאל קנ\"א אלף<sup data-n=\"5848\">30</sup> מחנות, מיכאל וגבריאל הם חו\"ג<sup data-n=\"5849\">31</sup> שחסד וגבורה הם ב' הפכים, וכן בחסד גופא כל א' בחי' בפ\"ע קפ\"ו אלף מחנות, מ\"מ כל א' הוא בחי' בפ\"ע בהתחלקות המדרגות. ומה שנתהווה ריבוי התהוות הנבראים תכלית המכוון הוא כדי שנשפע<sup data-n=\"5850\">32</sup> השפעת אלקות למטה ע\"י, עד שאין לך עשב<sup data-n=\"5851\">33</sup> מלמטה שאין לו מזל מלמעלה ואומר לו גדל עד שנמשך דעת בנש\"י, אך או\"ס<sup data-n=\"5852\">34</sup> ב\"ה הוא פשוט בתכלית הפשיטות, ואיך נעשה מאו\"ס אחדות פשוט ריבוי התהוות הנבראים, הלא לפני אחד מה אתה סופר<sup data-n=\"5853\">35</sup> שבאו\"ס אין שייך מספר, אך זהו\"ע תיבת ברוך שנמשך המשכת הארה להיות ממכ\"ע<sup data-n=\"5854\">36</sup> וסוכ\"ע<sup data-n=\"5855\">37</sup> בכדי שיהי' העולמות והנבראים יכולים לקבל כאו\"א לפי מדרגתו, שעיקר מציאת היש הוא מסוכ\"ע<sup data-n=\"5856\">38</sup> והתחלקות הוא ממכ\"ע. אך כתי' כי נשגב שמו לבדו<sup data-n=\"5857\">39</sup> שאפי' נשגב סוכ\"ע הוא שמו שם בעלמא, ואפי' שמו בחי' נשגב מובדל מגדר עולם, כי הארה והמשכה ההיא נק' קדוש ומובדל, כי הארה והמשכה שנמשך בעולם",[["5841","23","<b>שם ה' בלשון חכמים הקב\"ה</b>: ראה ברכות ג, א. ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550570\" data-slug=\"torat-chaim\" data-id=\"2300550570\">תו\"ח תרומה ח\"ב שיז, ב</a> ואילך. וש\"נ. וראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540664\" data-slug=\"torat-chaim\" data-id=\"2300540664\">תו\"ח בא ח\"א קכב, ב</a>."],["5842","24","<b>מה גדלו מעשיך ה'</b>: תהלים צב, ו. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול על יד הערה 42 ואילך. וש\"נ."],["5843","25","<b>שמלאך בשליש עולם עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. לעיל (בחלק המאמרים) שם הערה 44."],["5844","26","<b>אלף אלפים ישמשוני'</b>: דניאל ז, י."],["5845","27","<b>היש מספר לגדודי'</b>: איוב כה, ג."],["5846","28","<b>אלף אלפים. . ולגדודיו אין מספר</b>: ראה חגיגה יג, ב."],["5847","29","<b>מחנה מיכאל קפ\"ו אלף</b>: ראה זהר בהעלותך ס\"ע קנד ואילך. ולא קפיד להעתיק גם מספר המאות שבזהר שם (מספר דגל מחנה יהודה). ראה גם סה\"מ תרל\"ח ע' קלא. וש\"נ."],["5848","30","<b>ומחנה גבריאל קנ\"א אלף</b>: ראה זהר שם קנה, א קנ\"ז אלף שש מאות (מספר דגל מחנה דן). הערה בסה\"מ ת\"ש ע' 40.\nולהעיר (באם אינו טעות המעתיק) שזהו מספר דגל מחנה ראובן (במדבר ב, טז 151,450)."],["5849","31","<b>מיכאל וגבריאל הם חו\"ג</b>: ראה זהר ויחי רלה, ב. סה\"מ תרל\"ח ע' קטז. וש\"נ."],["5850","32","<b>שנשפע</b>: אוצ\"ל: שיושפע."],["5851","33","<b>שאין לך עשב</b>: ראה ב\"ר פ\"י, ו. (לעיל בחלק המאמרים) המשך מצה זו הערה 549."],["5852","34","<b>או\"ס</b>: ועד\"ז הוא בכ\"מ בסמוך. כ\"ה בהכ\"י מעתיק זה — ראה גם לעיל הנחה ד\"ה וביום הביכורים ובהערה 72. אולי צ\"ל: א\"ס־ או אוא\"ס."],["5853","35","<b>לפני אחד מה אתה סופר</b>: ראה ס\"י פ\"א, מ\"ז."],["5854","36","<b>המשכת הארה להיות ממכ\"ע וסוכ\"ע</b>: ראה (לעיל בחלק המאמרים) המשך מצה זו פכ\"ו ובהערה 856."],["5855","37","<b>ממכ\"ע וסוכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["5856","38","<b>שעיקר מציאת היש הוא מסוכ\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370407\" data-slug=\"torah-or\" data-id=\"3901370407\">תו\"א מג\"א צ, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370412\" data-slug=\"torah-or\" data-id=\"3901370412\">סע\"ג. צא, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370416\" data-slug=\"torah-or\" data-id=\"3901370416\">צב, ג</a> ואילך. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה סוכה שחמתה מרובה מצלתה ובהערה 25."],["5857","39","<b>כי נשגב שמו לבדו</b>: תהלים קמח, יג."]]],[2000470592,"אינו כדמיון הנשמה המתפשטת בתוך הגוף להחיותו ולקיימו שהיא מתפעלת ממקרי הגוף לפי שהיא מלובשת ממש בתוך הגוף שהרי כשמתלבשת במחשבה אחת היא נתפסת ומוקפת בה עד שאינה יכולה להתלבש במחשבה אחרת<sup data-n=\"5858\">40</sup> (בל\"א ער קען ניט ארוף ל זין „נ„נדער מחשבה), משא\"כ למעלה אפי' הארה שנמשך להחיות ולהוות עולמות נבראים עד אין קץ בריבוי התחלקות הארה זו קדוש ומובדל מגדר עולם.\n<b>וכמו</b> שנת\"ל בבחי' מה גדלו מעשיך כו' כן הוא במה רבו מעשיך ה'<sup data-n=\"5859\">41</sup> שנתהווה נבראים עד אין קץ כמ\"ש רבות עשית אתה ה' אלקי<sup data-n=\"5860\">42</sup>, מה רבו מעשיך ה' שנתהווה ריבוי נבראים כמו דצח\"ם ריבוי מינים ובכל מין יש ריבוי נבראים, כמו מדבר שכל א' יש לו דיעה ומחשבה אחרת שלזה יש דיעה ומחשבה כזו ולזה יש דיעה ומחשבה אחרת ע\"כ לזה הנחת סוף דעתו כן ולזה סוף דעתו באופן אחר ושניהם צודקים כי לזה יש דיעה ומחשבה אחרת ולזה יש דיעה אחרת שאין דיעותיהם שוות<sup data-n=\"5861\">43</sup> ואין מחשבותיהן שוות זל\"ז, והקב\"ה הגם שהוא מחי' את ראובן שיש לו דיעה ומחשבה כזו מ\"מ הוא מחי' גם שמעון שיש לו דיעה ומחשבה אחרת, ואין מחשבת ודיעה נברא א' תופסת ומקפת החיות הנמשך ממנו ית' להטריד ולבלבל שלא יתלבש להחיות ולהוות נבראים אחרים שבמחשבה ודיעות אחרים, מפני שזהו רק בדרך גלוי וידוע לפניו<sup data-n=\"5862\">44</sup>, ולא כמו ידיעת האדם כאשר ברצונו לידע איזה דבר הנה ידיעתו מלובשת באותו דבר שיודע וזהו ענין יודע אבל למעלה זהו בדרך גלוי וידוע ולא בהתלבשות, וידיעה שלמעלה אינו מכרחת את האדם<sup data-n=\"5863\">45</sup> שיעשה כמו שידוע למעלה רק הבחירה ניתן חפשית לאדם, הגם שהאדם עושה כמו שידוע למעלה אך זהו לא מפני שידיעה שלמעלה מכרחת כן, כ\"א הי' כן לא הי' שייך שכר ועונש אלא שהבחירה ניתן חפשית לאדם וע\"כ יש שכר ועונש, והידיעה שלמעלה אינו מכרחת שזהו בדרך גלוי וידוע ע\"כ מפני שזהו לא בהתלבשות והגם שהוא מחי' ראובן מ\"מ הוא מחי' גם שמעון. ובד\"כ זהו השגחה אחת, הגם שיש השגחה פרטיות על כל דרכי איש<sup data-n=\"5864\">46</sup>, לתת איש כדרכיו וכפרי מעלליו<sup data-n=\"5865\">47</sup>, וכתי' אני ה' חוקר לב ובוחן כליות<sup data-n=\"5866\">48</sup>, שיש השגחה פרטיות, וכמו אין אדם נוקף אצבעו<sup data-n=\"5867\">49</sup> מלמטה אא\"כ מכריזין",[["5858","40","<b>כשמתלבשת במחשבה אחת. . אחרת</b>: ראה גם שו\"ע אדה\"ז הל' ק\"ש רסע\"ג קו\"א ס\"ג."],["5859","41","<b>מה רבו מעשיך ה'</b>: תהלים קד, כד. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול על יד הערה 36 ואילך. וש\"נ."],["5860","42","<b>רבות עשית אתה ה' אלקי</b>: תהלים מ, ו."],["5861","43","<b>שאין דיעותיהם שוות</b>: ראה ברכות נח, א ובדק\"ס שם. תניא בהקדמה."],["5862","44","<b>גלוי וידוע לפניו</b>: ע\"פ שבת נה, א<sup data-n=\"e295\">א</sup>. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370066\" data-slug=\"torah-or\" data-id=\"3901370066\">תו\"א וירא יד, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550112\" data-slug=\"torat-chaim\" data-id=\"2300550112\">תו\"ח משפטים ח\"ב רעט, ג</a>. וש\"נ. סהמ\"צ להצ\"צ פא, ב. סה\"מ תרכ\"ז ע' שכב. וש\"נ."],["5863","45","<b>וידיעה שלמעלה אינה מכרחת את האדם</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו הערה 1806."],["5864","46","<b>על כל דרכי איש</b>: ע\"פ איוב לד, כא. משלי טז, ב. ירמי' לב, יט."],["5865","47","<b>לתת איש כדרכיו וכפרי מעלליו</b>: ירמי' לב, יט [ושם: לאיש]. יז, י [ושם: ולתת לאיש כדרכיו כפרי מעלליו]."],["5866","48","<b>אני הוי' חוקר לב ובוחן כליות</b>: ירמי' יז, י [ושם: בחן — ראה סה\"מ תרל\"ח ע' תנה]."],["5867","49","<b>אין אדם נוקף אצבעו</b>: חולין ז, סע\"ב.\n\n<b>א</b>  ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב</a> ובמ\"מ הגהות והע\"ק לשם ע' רפא. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181206\" data-slug=\"likkutei-sichot\" data-id=\"1300181206\">לקו\"ש קרח כרך יח ע' 197</a> הערה 11."]]],[2000470593,"עלי' מלמעלה, וכן לטוב אנו מצינו כאשר פוסקים גדולה לאדם<sup data-n=\"5868\">*50</sup> פוסקים לו ולזרעו עד דור ודור, אך בד\"כ זהו השגחה אחת ואינה נתפסת ומלובשת ממש בתוך הנבראים רק צופה ומביט<sup data-n=\"5869\">50</sup> עד סוף כל הדורות בסקירה אחת, ולכן נק' הארה והמשכה זו בחי' קדוש ומובדל, אלא שהוא קדוש וא\"ו שמורה שאפי' הארה שנמשך להיות סוכ\"ע וממכ\"ע הוא ג\"כ קדוש ומובדל שאפי' שמו בחי' נשגב כו'.\n<b>וזהו</b> דכתיב אין קדוש כה'<sup data-n=\"5870\">51</sup> ופי' בזח\"ג תזריע<sup data-n=\"5871\">52</sup> דכמה קדישין אינון כו' ולאו קדישין כה'. והענין הוא כי ה' הוא לשון מהוה<sup data-n=\"5872\">53</sup> שמהווה נאצלים ונבראים נוצרים ונעשים, ואעפ\"י שמהווה הכל אעפי\"כ הוא קדוש ומובדל ואינו כדמיון הנשמה וכנ\"ל, והנה בחי' קדוש כזה לא נמצא בכל בחי' קדישין דלעילא מפני שבכל סדרי השתל' מי שנק' קדוש שהוא מובדל מאיזה דבר אז א\"א להיות נתפס ונאחז באיזה דבר, ואם הוא נתפס ונאחז באיזה דבר אז אינו מובדל מאותו דבר, כמו שנת\"ל ההפרש בין מוחין למדות<sup data-n=\"5873\">54</sup> שמדות שייך לזולת אבל מוחין אינו שייך לזולת שהוא מובדל מעולם, משא\"כ למעלה באו\"ס ב\"ה הסוכ\"ע שהוא קדוש ומובדל ואעפי\"כ הוא דוקא המהווה כל העולמות, ואדרבה עיקר החיות והתהוות הוא מבחי' המקיף וכמ\"ש בסש\"ב ס\"פ כ\"ג וס\"פ מ\"ח וכ\"ה בע\"ח שהמקיף מצחצח הכלי מבחוץ<sup data-n=\"5874\">55</sup>, ובאמת זהו רבותא יותר מבפנים כי בפנים אפשר לפעול ע\"י התבוננות, ועוד כי בפנים קרוב יותר לאור, אבל מבחוץ שרואה אויר העולם צריך בחי' גבוה יותר לצחצח ואור המקיף הוא מצחצח הכלי מבחוץ א\"כ העיקר הוא המקיף, וכן כתי' ואתה משמרה בקרבי<sup data-n=\"5875\">56</sup> נשמה שנתת בי טהורה היא ואתה משמרה בקרבי<sup data-n=\"5876\">57</sup> שהמקיף הוא עיקר שומר, וזהו אין קדוש כה' הגם שהוא מהווה ומחי' מ\"מ הוא קדוש ומובדל שאפי' הארה הוא קדוש ומובדל כו'.\n<b>אך</b> הנה בחי' זו א\"ל כאשר הדור אינו ראוי לכך שיסתלק לגמרי ע\"כ ע\"ז כתי' שאו ידיכם קדש<sup data-n=\"5877\">58</sup> וברכו את הוי', כי הנה סוכ\"ע הגם שהוא מקיף את העולם שזהו מפני שא\"א להיות שיומשך בפנימי' כידוע שענין המקיף היינו מפני שא\"א לימשך בפנימי' מ\"מ זהו ענין קדוש בוא\"ו ובחי' זו כאשר דור<sup data-n=\"5878\">59</sup> אינו ראוי לכך אפשר להיות",[["5868","*50","<b>כאשר פוסקים גדולה לאדם</b>: ראה מגילה יג, ב. זבחים קב, א."],["5869","50","<b>צופה ומביט</b>: ראה ברכת זכרונות. ר\"ה יח, א. סהמ\"צ להצ\"צ ע' פב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540576\" data-slug=\"torat-chaim\" data-id=\"2300540576\">תו\"ח שמות ח\"א מח, ב</a>. וש\"נ."],["5870","51","<b>אין קדוש כה'</b>: שמואל-א ב, ב."],["5871","52","<b>ופי' בזח\"ג תזריע</b>: ראה שם מד, א."],["5872","53","<b>ה' הוא לשון מהוה</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. (לעיל בחלק המאמרים) המשך מצה זו כאן הערה 1115."],["5873","54","<b>כמו שנת\"ל ההפרש בין מוחין למדות</b>: ראה לעיל הנחה ד\"ה וביום הביכורים על יד הערה 14 (בחלק המאמרים) המשך מצה זו פ\"ל ובהערה 969."],["5874","55","<b>שהמקיף מצחצח הכלי מבחוץ</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"ב. שער השתל' הי\"ס ש\"ב, ענף ג. מאמרי אדה\"ז תקס\"ה ח\"א ע' תצט. ח\"ב ע' תתקלט ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550230\" data-slug=\"torat-chaim\" data-id=\"2300550230\">תו\"ח פקודי ח\"ב תמט, ד</a> ואילך."],["5875","56","<b>ואתה משמרה בקרבי</b>: תיבות אלו הוכפלו כאן. ואולי כן אמר כ\"ק אדמו\"ר מהר\"ש."],["5876","57","<b>נשמה שנתת. . ואתה משמרה בקרבי</b>: ברכת אלקי נשמה (מברכות ס, ב) בדילוג. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה סוכה שחמתה מרובה מצלתה הערה 98."],["5877","58","<b>שאו ידיכם קדש</b>: תהלים קלד, ב."],["5878","59","<b>דור</b>: אוצ\"ל: הדור."]]],[2000470594,"שמסתלק ע\"כ צריך להמשיך מבחי' קדש וזהו שאו ידיכם קדש וברכו את ה' שיתברך מבחי' קדש, לפי זה ברוך גבוה יותר מבחי' קדוש בוא\"ו, וזהו לשון הקב\"ה שקדוש הוא בוא\"ו וע\"י ברוך היינו ברוך ונמשך מבחי' קדש העליון. ועל בחי' זו נא' אם חטאת מה תפעל ורבו פשעיך<sup data-n=\"5879\">60</sup> כו' אם צדקת<sup data-n=\"5880\">61</sup>, ששם אינו תופס מקום מעהמ\"צ וכן אינו תופס מקום חטא ועון ומשם נמשך אפי' כאשר הדור אינו ראוי לכך, כי מצד בחי' קדש העליון שלמעלה מסוכ\"ע וממכ\"ע שם אינו תופס מקום כלל ע\"כ כאשר אפי' הדור אינו ראוי לכך ג\"כ נמשך.\n<b>אך</b> הגורם להשפיע שפע ברכה והמשכה מקדש העליון להיות קדוש בוא\"ו היינו ע\"י שאו ידיכם קדש, לכאורה מהו שייך שם ידים, אך הענין הוא ב' ידים היינו יחו\"ע<sup data-n=\"5881\">62</sup> ויחו\"ת<sup data-n=\"5882\">63</sup>, יחו\"ע למסור נפשו באחד<sup data-n=\"5883\">64</sup> פי' אחד הגם שנתהווה ז' רקיעים וארץ וד' רוחות העולם שזהו\"ע ח\"ד<sup data-n=\"5884\">65</sup> מ\"מ הם בטילים לא' לאלופו ש\"ע<sup data-n=\"5885\">66</sup> כי לפני אחד מה סופר, רק שנא' אחד להראות הגם שנתהווה מציאות העולם מ\"מ הוא בטל וטפל לאו\"ס, שלא יאמרו שנתהווה מציאות העולם רק שהעולם אינו נפרד מאלקות, אלא שאין שום מציאות עולם רק אלקות, כמו מאמר יהי רקיע<sup data-n=\"5886\">67</sup> זהו מהות רקיע שאותיות רקיע מחי' ומהווה את רקיע, למשל ע\"י דיבור האדם כאשר האדם הי' אומר לא נתהווה כלום וע\"י אותיות שלמעלה נתהווה וזהו מהות רקיע א\"כ מובן שזהו רק אלקות רק שלא ניתן רשות לעין לראות וע\"כ נראה העולם למציאות היש אבל אלו ניתנה רשות לעין לראות לא הי' הגשמית נראה כלל למציאת היש (כמבואר בתניא ח\"ב פ\"ג). וזהו והשבות אל לבבך<sup data-n=\"5887\">68</sup> כי ה' הוא אלקים בשמים ממעל ועל הארץ מתחת אין עוד פי' במד\"ר אין עוד אפי' בחללו ש\"ע<sup data-n=\"5888\">69</sup> לכאורה מהו הרבותא בחללו של עולם, אלא שזהו הרבותא אפי' במקום החלל שנגע בו הצמצום מ\"מ נשאר רשימו שדבר שבקדושה אינו נעקר ממקומו לגמרי<sup data-n=\"5889\">70</sup> והרשימו הוא מלפני הצמצום, ובד\"כ זהו נק' בשם העלם וגילוי שהצמצום היינו שמתחלה הי' בדרך גילוי",[["5879","60","<b>אם חטאת. . ורבו פשעיך</b>: איוב לה, ו [בדילוג]."],["5880","61","<b>אם צדקת</b>: איוב שם, ז."],["5881","62","<b>ב' ידים היינו יחו\"ע ויחו\"ת</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381215\" data-slug=\"likkutei-torah\" data-id=\"4001381215\">לקו\"ת שה\"ש כא, ג</a>."],["5882","63","<b>יחו\"ע ויחו\"ת</b>: זהר בהקדמה יב, א."],["5883","64","<b>למסור נפשו באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["5884","65","<b>ז' רקיעים וארץ וד' רוחות. . ח\"ד</b>: נסמן (לעיל בחלק המאמרים) במאמר ד\"ה סמוכים לעד הערה 50."],["5885","66","<b>לאלופו ש\"ע</b>: לשון ב\"ר פ\"כ, ב."],["5886","67","<b>יהי רקיע</b>: בראשית א, ו."],["5887","68","<b>והשבות אל לבבך</b>: ואתחנן ד, לט."],["5888","69","<b>פי' במד\"ר אין עוד אפי' בחללו ש\"ע</b>: דבר\"ר פ\"ב, כח<sup data-n=\"e296\">ב</sup>. ילקוט שמעוני יתרו יח, יא (רמז רסט). יהושע ב, י (רמז י). ראה גם המשך מים רבים תרל\"ו פי\"ב."],["5889","70","<b>שדבר שבקדושה. . לגמרי</b>: ראה אלשיך ר\"פ לך<sup data-n=\"e297\">ג</sup>. (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אז ישיר משה ובהערה 45.\n\n<b>ב</b>  במדרש שם חסר ציון זה, ושם נרשמו הציונים כה. כו כז. ל. ונרשם כאן ”כח\" ע\"פ פי' מהרז\"ו שם. וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291026\" data-slug=\"likkutei-sichot\" data-id=\"1300291026\">לקו\"ש ואתחנן כרך כט ע' 26</a> הערה 5.\n\n<b>ג</b>  הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490011\" data-slug=\"or-hatorah-hb\" data-id=\"8316490011\">אוה\"ת לך כרך ד ע' תרעה</a> וע' תרפא. ושם מציין לפרדס שער המציאות פ\"א."]]],[2000470595,"ואח\"כ נעשה העלם כו', א\"כ מובן איך שאין עוד אפי' בחללו ש\"ע ע\"כ ע\"י התבוננות זו אפשר לבוא לבחי' למס\"נ מי לי בשמים ועמך לא חפצתי בארץ<sup data-n=\"5890\">71</sup>, שמים וארץ היינו געה\"ע וגעה\"ת<sup data-n=\"5891\">72</sup> שאינו צריך לחפוץ לא בגעה\"ע ולא בגעה\"ת כי מה שהוא עמך לא חפצתי אפי' עוה\"ב כיון שנק' שם עולם ועולם הוא לשון העלם<sup data-n=\"5892\">73</sup> ע\"כ לא חפצתי רק שצריך לחפוץ רצון פשוט לאו\"ס עצמותו וזהו\"ע למס\"נ באחד ענין יחו\"ע כו'.\n<b>ובחי'</b> יחו\"ת הוא בע\"כ אתה חי<sup data-n=\"5893\">74</sup> רק שהמכוון שיהי' ביטול היש לאין כי אנו רואים שהמכוון שיהי' מציאות העולם היינו כדי שיהי' עבודה, ומה צריך לעבודתינו זה אינו מושג לנו, אך אנו רואים שהמכוון שיהי' עבודה וע\"כ נעשה מציאת היש, רק שאין המכוון שישאר כן שיהיה מציאת היש אלא שיבואו לבחי' ביטול היש לאין, כי מצד בחי' יחו\"ע לא הי' צריך להיות שיתהווה נבראים כאלו עם חומר גס ועב אלא שהי' אפשר להיות באופן אחר והי' משיגים רק רוחני' ולא גשמיות אלא זה שנתהווה נבראים מוכח שהמכוון שיהי' ביטול היש לאין. ובאמת עיקר העונג הוא עומד בזה כמו עד\"מ ציפור המדברת<sup data-n=\"5894\">75</sup> הגם שהאדם מדבר טוב יותר ומדבר הכל עם שכל, אך כאשר האדם מדבר זה אינו רבותא אלא כאשר ציפור מדבר בזה יש עונג גדול. כך הגם שנעשה מציאת העולם ונראה העולם בטוב מאד ומובן בטוב מאד והיצה\"ר מוסית<sup data-n=\"5895\">*76</sup> ומדיח לגמרי מ\"מ פועל ביטול היש לאין זהו רבותא גדולה ע\"כ יש בזה עונג גדול ע\"כ עיקר המכוון הוא בשביל ביטול היש לאין וזהו\"ע יחו\"ת כו'. שאו ידיכם היינו כאשר מייחד ב' בחי' אלו יחו\"ע ויחו\"ת עי\"ז א\"ל<sup data-n=\"5896\">76</sup> לבחי' קדש, כי כאשר מייחד יחו\"ע ויחו\"ת היינו שמבטל במחשבתו מציאת העולם שאין שום מציאות דבר חוץ מאלקות ע\"כ עי\"ז א\"ל לבחי' קדש, כי ענין קדש היינו בחי' קדש מלה בגרמי'<sup data-n=\"5897\">77</sup> מובדל מעולם ע\"כ ע\"י מחשבתו שמבטל העולם שאין שום מציאת חוץ מאתו עי\"ז<sup data-n=\"5898\">78</sup> לבוא לבחי' קדש. וזהו שאו ידיכם קדש שע\"י שמייחד יחו\"ע ויחו\"ת עי\"ז ממשיך מבחי' קדש שיומשך הארה להיות סוכ\"ע וממכ\"ע כדי שיהי' עוד עבודה.\n<b>והנה</b> כמו שע\"י העבודה דשאו ידיכם באים לבחי' קדש העליון כן ע\"י היראה באים ג\"כ לבחי' קדש העליון בחי' קדש עילאה וזהו בזאת יבא אהרן אל הקודש ע\"י בחי' יראה שנק' זאת יבא לבחי' קדש עילאה, שענין האהבה הוא בחי'",[["5890","71","<b>מי לי בשמים. . בארץ</b>: תהלים עג, כה. ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גל נעול ובהערה 65. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פכ\"ב. וש\"נ."],["5891","72","<b>שמים וארץ היינו געה\"ע וגעה\"ת</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת פ' ראה כה, א</a>. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 154."],["5892","73","<b>ועולם הוא לשון העלם</b>: ראה ספר הבהיר ס\"י. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541025\" data-slug=\"torat-chaim\" data-id=\"2300541025\">תו\"ח שמות ח\"א יח, ד</a> הערה 783."],["5893","74","<b>בע\"כ אתה חי</b>: ראה אבות ספ\"ד."],["5894","75","<b>ציפור המדברת</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואתה תצוה ובהערה 14."],["5895","*76","<b>מוסית</b>: כ\"ה בהכת\"י."],["5896","76","<b>א\"ל</b>: אפשר לבוא."],["5897","77","<b>קדש מלה בגרמי'</b>: זהר אמור צד, ב."],["5898","78","<b>עי\"ז לבוא</b>: אוצ\"ל: עי\"ז אפשר לבוא."]]],[2000470596,"יש מי שאוהב<sup data-n=\"5899\">79</sup> שיש מי שמתפעל<sup data-n=\"5900\">80</sup> בבחי' אהבה ע\"כ עי\"ז א\"ל רק לבחי' זה כו', משא\"כ יראה שמי שהוא איש ירא הוא בטל בתכלית שכל הכחות שלו הם בטלים בתכלית שהוא אין שום מציאת דבר ע\"כ עי\"ז א\"ל לבחי' קדש, בזאת שע\"י זאת בחי' יראה יבוא לבחי' קדש כו'. וזהו אל יתהלל חכם בחכמתו<sup data-n=\"5901\">81</sup> כ\"א בזאת יתהלל המתהלל השכל וידוע אותי<sup data-n=\"5902\">82</sup>, הגם שחכמה הוא בחי' גבוה מ\"מ אל יתהלל בחכמה כ\"א בזאת שע\"י זאת בחי' יראה עי\"ז א\"ל לבחי' אותי עצמות או\"ס פי' אותי היינו שאין מרומז לא בשום אות ולא בשום קוץ<sup data-n=\"5903\">83</sup> עצמות או\"ס. וזהו גבוה יותר מבחי' איהו תפיס בכולא עלמין<sup data-n=\"5904\">84</sup>, כי איהו תפיס בכולא עלמין היינו סוכ\"ע שענין סוכ\"ע היינו שסובב ומקיף את העולם ולית מאן דתפיס בו שאפי' סוכ\"ע הוא ג\"כ מובדל מעולם א\"כ זהו רק סוכ\"ע קדוש בוא\"ו, אבל אותי היינו עצמות או\"ס בחי' קדש, וע\"י זאת בחי' יראה א\"ל לבחי' אותי כו'.\n<b>וז\"ע</b> שם ירושלים דאיתא בתוס' בשם מד\"ר ששם ירושלים ע\"ש יראה שלם<sup data-n=\"5905\">85</sup> שלימות היראה<sup data-n=\"5906\">86</sup>, כי ביראה גופא יש כמה מדרגות שיש קצת ירא ויש ירא יותר ויש שלימות היראה, וירושלים נק' שלימות היראה. וכן לימות המשיח נא' והריחו ביראת ה'<sup data-n=\"5907\">87</sup>, שענין הריח הוא שהנשמה נהנה<sup data-n=\"5908\">88</sup> ממנה, והריח יהי' ביראת ה'. ועיקר שלימות היראה יהי' לע\"ל כמ\"ש וחשף ה' את זרוע קדשו<sup data-n=\"5909\">89</sup> ואז יגיעו כולם לשלימות היראה כמ\"ש ובאו במערות צורים מפני פחד ה' והדר גאונו<sup data-n=\"5910\">90</sup> מחמת עוצם הגילוי שיתגלה לע\"ל. כי ענין היראה הוא חותם שוקע ועי\"ז יתגלה לע\"ל בחי' חותם בולט<sup data-n=\"5911\">91</sup> כו'.\n<b>ומעתה</b> יובן מ\"ש משה אל תיראו כי לבעבור נסות אתכם בא אלקים ובעבור שתהי' יראתו על פניכם לבלתי תחטאו. כי הנה הרמב\"ן פי' שמה שחרדו",[["5899","79","<b>יש מי שאוהב</b>: מובא בכ\"מ בדא\"ח ומהם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370251\" data-slug=\"torah-or\" data-id=\"3901370251\">תו\"א וארא נו, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370302\" data-slug=\"torah-or\" data-id=\"3901370302\">יתרו סז, ג</a>. סה\"מ תרל\"ח ס\"ע קלה. וש\"נ."],["5900","80","<b>שיש מי שמתפעל</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו כאן הערה 1135."],["5901","81","<b>אל יתהלל חכם בחכמתו</b>: ירמי' ט, כב."],["5902","82","<b>כ\"א בזאת יתהלל. . וידוע אותי</b>: ירמי' שם כג."],["5903","83","<b>שאין מרומז. . בשום אות. . קוץ</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380190\" data-slug=\"likkutei-torah\" data-id=\"4001380190\">לקו\"ת אחרי כו, סע\"ג</a>. פינחס פ, סע\"ב. וראה זח\"ג יא, א<sup data-n=\"e298\">ד</sup>."],["5904","84","<b>איהו תפיס בכולא עלמין</b>: ראה זהר רע\"מ פינחס רכה, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קפב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670220\" data-slug=\"torat-chaim\" data-id=\"2300670220\">תו\"ח נח סו, ג</a> הערה 30."],["5905","85","<b>בתוס' בשם מד\"ר. . יראה שלם</b>: ראה תוד\"ה הר תענית טז, א. ב\"ר פנ\"ו, י. (לעיל בחלק המאמרים) המשך מצה זו כאן הערה 1139."],["5906","86","<b>ירושלים ע\"ש. . שלימות היראה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380960\" data-slug=\"likkutei-torah\" data-id=\"4001380960\">לקו\"ת ר\"ה ס, ב</a>. לעיל (בחלק המאמרים) שם ובהערה 1140."],["5907","87","<b>והריחו ביראת ה'</b>: ישעי' יא, ג."],["5908","88","<b>הריח הוא שהנשמה נהנה</b>: ראה ברכות מג, ב. (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 134."],["5909","89","<b>וחשף ה' את זרוע קדשו</b>: ישעי' נב, י [ושם: חשף]."],["5910","90","<b>ובאו במערות. . והדר גאונו</b>: ישעי' ב, יט [בדילוג. ושם: ומהדר — ראה גם המשך מצה זו כאן הערה 1142]."],["5911","91","<b>חותם שוקע. . חותם בולט</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381312\" data-slug=\"likkutei-torah\" data-id=\"4001381312\">לקו\"ת שה\"ש מו, א</a>.\n\n<b>ד</b>  ציון הזהר ע\"פ <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021419\" data-slug=\"likkutei-sichot\" data-id=\"1300021419\">לקו\"ש</a> פ' ראה ח\"ב ע' 696 (נדפס גם באג\"ק שלו ח\"כ ע' שיז)."]]],[2000470597,"וינועו ויעמדו מרחוק<sup data-n=\"5912\">92</sup> זה הי' קודם אשר ירד ה' על הר סיני כי כאשר נש\"י ראו המראה הקולות וברקים קול שופר חזק מאד נפל עליהם יראה ופחד וירא העם וינועו ויעמדו מרחוק פי' וינועו שעמדו לפוש מהיראה לכן שיערו שכשישמעו הקול ימותו שיתבטלו ולא יהי' שום מציאות ולא יהי' מי שיקבל התורה ולזה רצו לשמוע מפי משה ואתה תדבר אלינו<sup data-n=\"5913\">93</sup>, והשערתם הי' נכונה שהרי עכו\"ד<sup data-n=\"5914\">94</sup> פרחה נשמתן<sup data-n=\"5915\">95</sup> רק שהחזירם בטל תחי'<sup data-n=\"5916\">96</sup>, ולכן אמר להם משה אל תיראון<sup data-n=\"5917\">97</sup> פי' שלא ימותו ע\"ז לא ערב להם, ע\"כ לא אמר אל תמותון כ\"א אל תיראון כי הגם שפרחה נשמתן הגם ששיער שיהי' כן שפרחה נשמתן עכ\"ז הבין שמסתמא יחיים בטל תחי' דאל\"כ למי יצווה לקיים התומ\"צ א\"כ מסתמא יהי' מי שיקבל, וזהו א\"ל<sup data-n=\"5918\">98</sup> אל תיראו מחשש פן תמותון, ומה שבא אלקים זהו בשביל שיהי' שלימות היראה, כי הנה עשה\"ד האותיות נראה באויר ממשות האותיות נראה באויר<sup data-n=\"5919\">*99</sup> והי' צריך גם שמיעת הקול ראיי' ושמיעה ועי\"ז נחלף הכחות שהי' רואין את הנשמע<sup data-n=\"5920\">99</sup> ושומעין את הנראה, וזהו בא אלקים בעבור שתהי' יראתו על פניכם לבלתי תחטאו שיבואו לשלימות היראה יראת חטא פי' לא שיראו מהעונש אלא שיראו מעצם החטא<sup data-n=\"5921\">100</sup> (וזהו<sup data-n=\"5922\">101</sup> אל תיראו שיראה של נש\"י הי' שיתבטלו ממציאות לא שאיכפת להם החיים גשמים אלא שאיכפת להם ליפסד קיום תומ\"צ כיון שיתבטלו ממציאות ממילא יפסידו קיום תומ\"צ ולא יהי' מי שיקיים תומ\"צ, ע\"כ אמר להם אל תיראון ששיער שיחזירו בטל תחי' שעתיד להחיות את המתים, בא אלקים בעבור שתהי' יראתו על פניכם שיבואו לשלימות היראה ועי\"ז א\"ל לבחי' קדש כו'. וגם י\"ל שא\"ל אל תיראו פי' שאין דרך היראה שעי\"ז תעמדו מרחוק כ\"א שתגישו בכדי שיהי' שלימות היראה וזהו ויאמר משה אל העם אל תיראו כי לבעבור נסות כו'.\n<b>ע'</b><sup data-n=\"5923\">102</sup> ד\"ה באתי לגני<sup data-n=\"5924\">103</sup> ענין מה שנמשך דעת בנש\"י ע\"י המלאכים.",[["5912","92","<b>הרמב\"ן פי'. . וינועו ויעמדו מרחוק</b>: יתרו כ, טו."],["5913","93","<b>ואתה תדבר אלינו</b>: ע\"פ ואתחנן ה, כד."],["5914","94","<b>עכו\"ד</b>: אוצ\"ל עכדו\"ד."],["5915","95","<b>עכדו\"ד פרחה נשמתן</b>: ראה שבת פח, ב. (לעיל בחלק המאמרים) המשך מצה זו הערה 873."],["5916","96","<b>בטל תחי'</b>: שבת פח, ב."],["5917","97","<b>תיראון</b>: אוצ\"ל: תיראו. אבל כ\"ה כמ\"פ בסמוך."],["5918","98","<b>א\"ל</b>: אוצ\"ל: שא\"ל שאמר להם."],["5919","*99","<b>האותיות נראה. . באויר</b>: כ\"ה בהכת\"י."],["5920","99","<b>רואין את הנשמע</b>: ראה מכילתא ורש\"י יתרו כ, טו. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061131\" data-slug=\"likkutei-sichot\" data-id=\"1300061131\">לקו\"ש יתרו כרך ו ע' 120</a> בהערה 5-6. ובהשמטה לשם בע' 416. מאמרי אדה\"א במדבר ח\"ב ע' תרכו. סה\"מ תרכ\"ט ע' ריח ואילך. וש\"נ."],["5921","100","<b>שיראו מעצם החטא</b>: ראה גם תויו\"ט סוף סוטה (ד\"ה וענוה). ר\"ח שער היראה ש\"א, ספ\"ג (ד\"ה עוד בחי' ד' — יד, א). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת</a> בלק נג, ד<sup data-n=\"e299\">ה</sup>. מטות פב, א. פלח הרמון אמור ע' רפג. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181070\" data-slug=\"likkutei-sichot\" data-id=\"1300181070\">לקו\"ש נשא כרך יח ע' 61</a>."],["5922","101","<b>(וזהו</b>: בהכת\"י לא נסמן סיום הסוגר."],["5923","102","<b>ע'</b>: נרשם בשולי היריעה."],["5924","103","<b>ד\"ה באתי לגני</b>: ראה גם סידור שער התפלה כז, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381258\" data-slug=\"likkutei-torah\" data-id=\"4001381258\">לקו\"ת שה\"ש לב, ב</a>.\n\n<b>ה</b>  לכאורה כצ\"ל גם בלקו\"ש שבפנים ההערה."]]],[2000480072,"<h3>יונתי בחגוי הסלע</h3>\n<b>בס\"ד פ' ואתחנן</b>\n&lt;1&gt;\nּ<b>יונתי</b> בחגוי<sup data-n=\"1\">1</sup> הסלע<sup data-n=\"2\">2</sup> וגו', הנה כנס\"י נמשלו ליונה כמארז\"ל בפ\"ד דשבת דמ\"ט א' גבי אלישע בעל כנפיים ומ\"ש כנפי יונה משאר עופות משום דאמתיל כנס\"י ליונה שנא' כנפי יונה נחפה בכסף (תלים ס\"ח י\"ד) מה יונה כנפי' מגינות עלי' אף ישראל<sup data-n=\"3\">4</sup> מצות<sup data-n=\"4\">3</sup> מגינות עליהן, וכ\"ה ספ\"ח דברכות דנ\"ג ע\"ב מה יונה אינה ניצלת<sup data-n=\"5\">5</sup> אלא בכנפי' אף ישראל אינם ניצולין אלא במצות, ומזה פי' רש\"י בשבת הנ\"ל שהיונה ניצלת ע\"י שמכה בראש כנפיה<sup data-n=\"6\">6</sup> וע' בזח\"ג פנחס דרל\"ד א' ובמק\"מ שם, וע' עוד בפ' בלק דר\"ד ע\"ב גבי ואלבישו נהורין ואלין<sup data-n=\"7\">7</sup> אקרון כנפים עילאין,",[["1","1","<b>יונתי בחגוי הסלע</b>: בספר התולדות של כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"e30\">א</sup> ע' 52 הערה 11 כותב כ\"ק אדמו\"ר: מכאן ועד סד\"ה וזהו אני לדודי<sup data-n=\"e31\">ב</sup> הוא המשך הנודע בשם ”יונתי — תר\"ם\" ונדפס, ביחד עם עוד מאמרים אחדים<sup data-n=\"e32\">ג</sup> משנת תרמ\"א, בשם: לקו\"ת תורת שמואל ש\"ח. סיום ההמשך נדפס בספר התולדות שם ע' 59 — ולקמן ע' תקסג.\nהמשך זה הכולל תשעה מאמרים<sup data-n=\"e33\">ד</sup> (שהם כ\"ה פרקים — פרט להסיום), נאמר מש\"פ ואתחנן עד מוצאי ר\"ה תרמ\"א.\nלמאמר זה פ\"א — להתחלת המאמר (עד וביאור הענין) — לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640312\" data-slug=\"or-hatorah-hb\" data-id=\"8316640312\">אוה\"ת שה\"ש ח\"א ע' שיב</a> (בשינויים והוספות). ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א מקץ מב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370283\" data-slug=\"torah-or\" data-id=\"3901370283\">בשלח סג, ב</a>.\nפ\"ב — ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370194\" data-slug=\"torah-or\" data-id=\"3901370194\">תו\"א מקץ מג, ב</a> (בהוספות ושינויים). סידור שער החנוכה רעג, ג ואילך.\nפ\"ג — בתחלתו לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640312\" data-slug=\"or-hatorah-hb\" data-id=\"8316640312\">אוה\"ת שה\"ש ח\"א ע' שיב</a> (בשינויים).\nהנחת<sup data-n=\"e34\">ה</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן (בחלק הנחותיו<sup data-n=\"e35\">ו</sup>)."],["2","2","<b>יונתי בחגוי הסלע</b>: שה\"ש ב, יד."],["3","4","<b>ישראל</b>: באוה\"ת כאן: כנס\"י. בגמ' כבפנים."],["4","3","<b>כנפי יונה. . מצות</b>: ראה גם אוה\"ת (יהל אור) תהלים ע' רלו."],["5","5","<b>ניצלת</b>: בגמ' ואוה\"ת: ניצולת."],["6","6","<b>כנפיה</b>: ברש\"י: גפה. וברש\"י שבע\"י: גפי'."],["7","7","<b>ואלבישו. . ואלין</b>: בזהר ואוה\"ת: ואתלבשו. . ואינון.\n\n<b>א</b>  מהדורת קה\"ת תש\"ז.\n\n<b>ב</b>  ר\"ה תרמ\"א.\n\n<b>ג</b>  ראה בסמוך שולי הגליון ד.\n\n<b>ד</b>  <b>ויש להעיר שגם שאר המאמרים הם שייכים להמשך זה. ראה להלן מאמר ד\"ה וכל שיח השדה על יד הערה 35 שכותב</b>: וכמבואר בד\"ה ביום השמע\"צ שבד\"ה יונתי בחגוי הסלע. ובסה\"מ תרמ\"ג ע' נג: והוא שייך ליונתי מ\"ם. וראה גם הנרשם לקמן בהערה 1 במאמר ד\"ה שובה ישראל־ ד\"ה כנשר יעיר־ ד\"ה עשה צדקה ומשפט־ ד\"ה ויובן כו' הני ששה ועשרים הודו.\nבספר התולדות שם נרשם סיום ההמשך אחרי מאמר ד\"ה סוכה שחמתה מרובה מצלתה — וכן נדפס כאן.\n\n<b>ה</b>  ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\n\n<b>ו</b>  להלן באה רשימת הדרושים כפי שמופיעה בספר התולדות הנ\"ל ובחצאי ריבוע ניתוספו בריש הדרוש פתיחת הדרושים — שכנראה לא נרשמו ע\"י כ\"ק אדמו\"ר מהר\"ש — כפי שהם מופיעים בהנחות כ\"ק אדמו\"ר מהורש\"ב.\nא) יונתי בחגוי הסלע — (פרקים א-ג), פ' ואתחנן.\nב) [ואהבת את ה' אלקיך] והנה כמו שנמשלו המצות בנר — (פרקים ד-ז), פ' עקב.\nג) [יפה שעה אחת] ועפ\"ז כו' נרי בידך — (פרקים ח-יו\"ד), פ' ראה.\nד) [לכל תכלה כו'] אך עדיין צ\"ל מאחר שבחי' חיוהי — (פרקים יא-יב), פ' שופטים.\nה) [אני לדודי] והנה כל מה שנת\"ל בענין עליית נה\"א — (פרקים יג-טו), פ' תצא.\nו) [אני לדודי] והנה אני לדודי ודודי לי — (פרקים טז-יח), פ' תבוא.\nז) [יפה שעה אחת] ומעתה כו' אני לדודי ועלי תשוקתו — (פרקים יט-כאז), פ' נצבים.\nח) [ובחודש השביעי] ויובן ענין הטוב — (פרקים כא-כב), ר\"ה.\nט) וזהו אני לדודי — (פרקים כג-כה), מוצאי ר\"ה.\nסיום ההמשך וזהו שרש ענין יונתי בחגוי הסלע נדפס לקמן אחר מאמר ד\"ה סוכה שחמתה מרובה מצלתה.\nחלק מפרק כא נכנס בדרוש ויובן ענין הטוב (ר\"ה תרמ\"א)."]]],[2000480073,"ובמק\"מ שם נהורא קדמאה א\"ק<sup data-n=\"8\">8</sup>, בההוא נהורא עתיק, ונת' ע\"ז כי הכנפים הם כלי להרצון<sup data-n=\"9\">9</sup> שהרי העוף יעופף למעלה בגובה או למטה, והכל בעפיפת הכנפים באופן אחד, א\"כ זה שלפעמים מעופף למעלה ופעמים למטה זהו מחמת הרצון לבד שכפי הרצון כך נעשה הפריחה הוא עפיפת הכנפים, ועד\"ז יובן שהמצות הם כלים להרצון העליון נק' כנפי יונה, וזהו שפי' בפ' פנחס שהם ממשיכים הרוח להמתיק הגבורות של האש וחום הלב. וביאור הענין דהנה ארז\"ל כל האומר אין לי אלא תורה<sup data-n=\"10\">10</sup> אפי' תורה אין לו, אלא שצ\"ל תורה וגמ\"ח, ולכאו' יפלא הלא מצות התורה היא גדולה ונפלאה מאד עד שמצינו שויתר הקב\"ה על ג' עבירות חמורים דע\"ז וג\"ע וש\"ד ולא ויתר על ביטול תורה<sup data-n=\"11\">11</sup> שהמאור שבה מחזירם למוטב ולמה בלא מצות אפילו תורה אין לו כו'. אך הענין שאין זה פירכא כלל דמה שוויתר כו' המאור שבה נת' ע\"ז בד\"ה ושננתם באריכות<sup data-n=\"12\">12</sup> שהפגם בכל המצות זהו כמו החסרון באבר פרטי שיכולים להיות גם בלתי אבר ההוא, אבל התורה היא כמו האברים הפנימיים<sup data-n=\"13\">13</sup> שנקובתם במשהו<sup data-n=\"14\">14</sup>, ונמשלה לדם<sup data-n=\"15\">15</sup> שבו מלובש הנפש כמ\"ש כי הדם הוא הנפש<sup data-n=\"16\">16</sup> ובו תלוי",[["8","8","<b>ובמק\"מ. . א\"ק</b>: ראה גם אוה\"ת בהעלותך שבהערה הבאה."],["9","9","<b>הכנפים הם כלי להרצון</b>: ראה גם (בנוסף ל<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830027\" data-slug=\"or-hatorah-hb\" data-id=\"8158830027\">אוה\"ת</a> כאן) אוה\"ת בהעלותך ע' שדמ. קרח ע' תשיג. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 10: ועל ל' החסידות. ד\"ה ובחודש השביעי הב' על יד הערה 108. (בחלק ההנחות) הנחה ד\"ה כנשר יעיר קנו על יד הערה 141. נזכר גם במאמר ד\"ה כנשר יעיר קנו תשכ\"ה."],["10","10","<b>כל האומר אין לי אלא תורה</b>: ראה יבמות קט, ב. סה\"מ תש\"ח ע' 266 בהערה."],["11","11","<b>שויתר הקב\"ה. . ולא ויתר על ביטול תורה</b>: ראה ירושלמי חגיגה פ\"א, ה\"ז. פתיחתא דאיכ\"ר ב. הל' ת\"ת לאדה\"ז פ\"ד, ה\"ז."],["12","12","<b>דמה שוויתר. . בד\"ה ושננתם באריכות</b>: ראה סה\"מ תרל\"ו ח\"ב ע' רצז ואילך. אמ\"ב שער הק\"ש פא, ב ואילך. אוה\"ת ואתחנן ע' רמז. ע' עבר ואילך. ע' שב ואילך. סה\"מ תרכ\"ט ס\"ע רצב ואילך ובהנסמן שם."],["13","13","<b>התורה. . האברים הפנימיים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550199\" data-slug=\"torat-chaim\" data-id=\"2300550199\">תו\"ח פקודי ח\"ב תנג, א</a> ואילך."],["14","14","<b>האברים הפנימיים שנקובתם במשהו</b>: ראה חולין מב, א."],["15","15","<b>התורה. . ונמשלה לדם</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380360\" data-slug=\"likkutei-torah\" data-id=\"4001380360\">לקו\"ת במדבר יג, א</a>."],["16","16","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."]]],[2000480074,"עיקר חיות נפש האדם כו', ועכ\"ז אינו סותר כלל למארז\"ל כל האומר אין לי אלא תורה שבאמת בהעדר גמ\"ח שה\"ע המצות אפי' תורה אין לו כו'. והענין הוא דכתי' כי נר מצוה<sup data-n=\"17\">17</sup> ותורה אור, המשיל התורה לאור המאיר הרבה והמצות לנר פרטי יחידי ועכ\"ז הקדים נר מצוה לתורה אור להיות כי גם בחי' אור התורה תלוי בבחי' נר מצוה. ויובן בהקדם ענין מה שדימה את המצות לנר, בהיות ידוע כי דליקת אור הנר תלוי' באויר<sup data-n=\"18\">18</sup> שסביבה, אשר בלא אויר אינה יכולה כלל לדלוק, ולכן אין כופין כלי<sup data-n=\"19\">19</sup> ע\"ג הנר בשבת מפני שיכבה הנר ונמצא גורם כיבויה, וכן באויר גס ג\"כ לא תדלוק<sup data-n=\"20\">20</sup> וכל שאויר זך ביותר תדלוק בטוב יותר שנמצא כל ענין דליקתה תלוי' באויר דוקא, והענין הוא שאויר הוא אותיות אור יו\"ד<sup data-n=\"21\">21</sup>, פי' שהוא שרש ומקור בחי' היו\"ד<sup data-n=\"22\">22</sup> שהיו\"ד הוא בחי' העלם אור שבא לידי גילוי אח\"כ, והאויר הוא מקורו שבא ונמשך משם, וע\"ד מ\"ש בת\"ז אנת הוא חכים<sup data-n=\"23\">23</sup> שענין בחי' חכים הוא כמו פועל יוצא (רק שבאמת אין זה פועל יוצא מפני שהוא וחכמתו א'<sup data-n=\"24\">24</sup> כו', והיינו &lt;2&gt;\nּ שבו ית' אינו שייך לומר יצא כלל, וגם כי אין עוד מלבדו<sup data-n=\"25\">25</sup> כו') ואנת קאי על אוא\"ס שמפעיל את בחי' חכים ולא בחכ' ידיעא כו', והיינו בחי' רצון העליון שעלה ברצונו שיהי' בחי' חכים כו', וזהו בחי' האויר אור ומקור בחי' יו\"ד דחכמה<sup data-n=\"26\">26</sup> שהוא בחי' התורה בכלל, והמצות נמשלו לנר, להיותם בשרשם בבחי' רצה\"ע שלמעלה מחכמת התורה ולכן עיקר התורה תלוי' בקיום המצות כו', כמ\"ש וצדקה תהי' לנו כי נשמור לעשות את כל כו', פי' שכל המצות נק' בשם צדקה<sup data-n=\"27\">27</sup>, והיינו שכמו הצדקה הוא להחיות רוח",[["17","17","<b>כי נר מצוה</b>: משלי ו, כג. ראה גם בהבא לקמן תו\"א שבהערה הבאה."],["18","18","<b>דליקת אור הנר תלוי' באויר</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370194\" data-slug=\"torah-or\" data-id=\"3901370194\">תו\"א מקץ מב, ג<sup data-n=\"e36\">ח</sup>. מג, ב</a>. סידור שער החנוכה רעג, ג. אוה\"ת תזריע כרך ב' ע' תקכ<sup data-n=\"e37\">ט</sup>. בהעלותך ע' שמג."],["19","19","<b>אין כופין כלי</b>: ראה שו\"ע אדה\"ז הל' שבת סרע\"ז, ס\"ח. תו\"א־ סידור־ אוה\"ת תזריעט שבהערה שלפנ\"ז."],["20","20","<b>באויר גס ג\"כ לא תדלוק</b>: ראה גם לקו\"ת חוקת סה, סע\"ד. מאמרי אדה\"ז תקס\"ז ס\"ע רסה. אתהלך לאזניא ע' צט<sup data-n=\"e38\">י</sup>. סידור ואוה\"תט שבהערה 18. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 97."],["21","21","<b>שאויר. . אור יו\"ד</b>: ראה זהר בראשית טז, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א מקץ מב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370194\" data-slug=\"torah-or\" data-id=\"3901370194\">מג, ב</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תנ. וש\"נ."],["22","22","<b>שאויר. . אור יו\"ד. . ומקור בחי' היו\"ד</b>: ראה גם אוה\"ת תזריעט שם. לקמן פ\"ב. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 138 ואילך."],["23","23","<b>מ\"ש בת\"ז אנת הוא חכים</b>: בהקדמה יז, ב. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 140. ד\"ה מפני שיבה תקום על יד הערה 13. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה משה קבל על יד הערה 28. סה\"מ תרל\"ח ע' קצב ובהערה 1537."],["24","24","<b>שהוא וחכמתו א'</b>: פרדס שער מהות והנהגה ש\"ח, פט\"ו. תניא פ\"ב."],["25","25","<b>אין עוד מלבדו</b>: ואתחנן ד, לה."],["26","26","<b>יו\"ד דחכמה</b>: ראה זהר בראשית לא, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשסד ובהנסמן לשם."],["27","27","<b>וצדקה תהי' לנו.. שכל המצות. . צדקה</b>: ואתחנן ו, כה. ראה מאמרי אדה\"א ויקרא ח\"ב ע' עדרת. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540914\" data-slug=\"torat-chaim\" data-id=\"2300540914\">תו\"ח שמות ח\"א יד, א</a> ובהערה 628. סה\"מ תרל\"ח ע' שמט. וש\"נ. לקמן ספ\"כ. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 100. ד\"ה יפה שעה אחת הג' על יד הערה 74. ד\"ה עשה צדקה על יד הערה 8. (בחלק ההנחות) ד\"ה לכל תכלה ראיתי קץ על יד הערה 94. ד\"ה אני לדודי הב' על יד הערה 54. ד\"ה יפה שעה אחת הב' על יד הערה 90. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 65.\n\n<b>ח</b>  נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480237\" data-slug=\"or-hatorah-hb\" data-id=\"8316480237\">אוה\"ת מקץ כרך ה ע' תתקנ</a>.\n\n<b>ט</b>  נדפס גם (בשינויים קלים) בסה\"מ תרל\"ה ח\"א ע' קצז. והנחת כ\"ק אדמו\"ר מהורש\"ב בח\"ב שם ע' תפא.\n\n<b>י</b>  והוא משנת תקנ\"ח (כרם חב\"ד **4 ע' 362). נדפס גם באוה\"ת בהעלותך כרך ד ע' א'תעו ואילך [ובמהדורת תשנ\"ז בהעלותך ע' שלט ]."]]],[2000480075,"שפלים<sup data-n=\"28\">28</sup> עד\"מ העני דלית לי' מגרמי' כלום שהוא שפל ונבזה בעיני עצמו שעומד בפתח הבית לבקש השפעת חיי נפשו לחם לאכול כדי חייו עכ\"פ, כך כל העולמות הם דכים ושפלים נגדו ית' שאינם תופסים שום תפיסת מקום כלל, שהרי כלליות כולם היא מהארה בעלמא שאינו נוגע כלל כמ\"ש במ\"א שלכן אני הוי' לא שניתי<sup data-n=\"29\">29</sup> כו', אי לזאת ההשפעה שנשפע מאתו להחיות כלליות ההשתל' זהו נק' בשם צדקה, וממשיכים בחי' צדקה זו ע\"י הצדקה שעושה למטה עי\"ז נמשך גילוי אלקות בכל העולמות, וזהו בחי' אור התורה שהוא מקור הארת האור שבכל העולמות להיות מבחי' חכ' ראשית ההשתל'<sup data-n=\"30\">30</sup> כו', וזהו משפט וצדקה ביעקב אתה עשית<sup data-n=\"31\">31</sup>, פי' שע\"י הצדקה שיעקב עושה עי\"ז נמשך בחי' אתה שמורה על הגילוי<sup data-n=\"32\">32</sup> כנודע, וצדקה זו משפט כתיב בה שלא די במה שיתן צדקה ממה שנשאר אצלו אחר כל תענוגי הגשמי' שיתענג בה אדם הגשמי, אלא שצריך לשפוט א\"ע מהמותרות כו' שלא אמרו חייך קודמין<sup data-n=\"33\">33</sup> אלא בקיתון של מים וכמעשה שהי' שלשניהם לא הי' מספיק כלל, אבל לא שיחיה האדם בתפנוקי בנ\"א וחבירו ימות ברעב ח\"ו כו', ולזה צדקה זו משפט כתיב בה, ומאי חזית<sup data-n=\"34\">34</sup> כו', ולכן כל מה שהוא מוכרח לחיי נפשו אשר בלעדו א\"א לו לחיות כנ\"ל ע\"ז אמרו חייך קודמין כו', וע\"י בחי' אתכפיא זו ממשיכים בחי' אתה בחי' גילוי כו'. וג\"ז אתה עשית, פי' הגם שצדקה זו הוא בחי' אתכפיא גדולה הן במתן צדקה בפו\"מ והן בעשיית כל המצות שנק' בשם צדקה, היינו שלא לאמר כבד לי כעת לעסוק במצוה זו או שאין לו פנאי וע\"ז צריך לשפוט א\"ע אם א\"א לו לחיות בפו\"מ אזי אשר וחי בהם<sup data-n=\"35\">35</sup> כתי' ולא שימות בהם, אבל כל שלא הגיע למדריגה זו כו', שנמצא שזהו אתכפיא גדולה אמנם מהו תופס מקם נגדו ית' מאחר",[["28","28","<b>להחיות רוח שפלים</b>: ישעי' נז, טו. ראה גם סה\"מ תרל\"ג ח\"ב ע' תסה ובהנסמן שם."],["29","29","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה אני לדודי הא' על יד הערה 29. ד\"ה שובה ישראל (הא' והב') על יד הערות 43. 46. ד\"ה כנשר יעיר קנו על יד הערה 32. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח על יד הערה 44. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה צאינה וראינה ובהערה 82. סה\"מ תרכ\"ז ע' שנט ואילך."],["30","30","<b>חכ' ראשית ההשתל'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381236\" data-slug=\"likkutei-torah\" data-id=\"4001381236\">לקו\"ת שה\"ש כו, ד</a>. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1248."],["31","31","<b>משפט וצדקה ביעקב אתה עשית</b>: תהלים צט, ד. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370283\" data-slug=\"torah-or\" data-id=\"3901370283\">תו\"א בשלח סג, ב</a>. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 106 ואילך. לעיל ח\"א (בחלק המאמרים) המשך מצה זו על יד הערה 1390 ואילך."],["32","32","<b>אתה שמורה על הגילוי</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370006\" data-slug=\"torah-or\" data-id=\"3901370006\">תו\"א בראשית ב, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370207\" data-slug=\"torah-or\" data-id=\"3901370207\">ויחי מה, ג</a>. לקו\"ת ואתחנן ז, ב. בהערה שלפנ\"ז. פיה\"מ ס, א. מאמרי אדה\"א שמות ח\"א ע' קטו. וש\"נ. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 109."],["33","33","<b>חייך קודמין</b>: ב\"מ סב, א. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1395."],["34","34","<b>ומאי חזית</b>: פסחים כה, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381040\" data-slug=\"likkutei-torah\" data-id=\"4001381040\">לקו\"ת סוכות עט, א</a>."],["35","35","<b>וחי בהם</b>: אחרי יח, ה. יומא פה, ב."]]],[2000480076,"שכלליות השתל' הוא רק הארה בעלמא, ולזה אמרו אתה עשית שאתה ית' עשית כן ונתת לנו תורתיך וצויתנו מצותיך וכך עלה ברצונך שאתכפיא זו תפעול להיות גילוי בחי' אתה כו', ונמצא כי בחי' תורה אור תלוי בנר מצוה כו', ולכן האומר אין לי אלא תורה אפי' תורה אין לו, אלא שצ\"ל תורה וגמ\"ח שע\"י גמ\"ח שהוא לגמול חסדים טובים ע\"י בחי' נר מצוה שעי\"ז יומשך הארת אור התורה כו'.\n<b></b>קיצור. כנס\"י נמשלו ליונה, כנפי' מגינות, ניצולים במצות, הכנפי' הם כלים להרצון &lt;3&gt;\nּ כמ\"כ מצות רצה\"ע, אין לי אלא תורה, כי כדי שיומשך אור התורה זו ע\"י המצות ששרשם בכתר בחי' אויר מקור האור כו'.\nב) <b>וביאור</b> הענין<sup data-n=\"36\">36</sup>, דהנה האויר הוא למטה מיסוד האש<sup data-n=\"37\">37</sup>, ועכ\"ז יש בו דקות יותר מבאש, והיינו דעם היות שנשפל למטה יותר אבל בשרשו גבוה יותר, וכענין שא' יעקב מה נורא המקום הזה<sup data-n=\"38\">38</sup>, וכן בשמ\"ע א\"א הגדול הגבור והנורא<sup data-n=\"39\">39</sup> שזהו נגד ג' אבות, שנמצא והנורא זהו נגד יעקב, שלכאו' בחי' נורא שייך למדתו של יצחק בחי' גבורה<sup data-n=\"40\">40</sup>, אלא לפי שיעקב הי' מחבר ב' בחי' דחו\"ג אברהם ויצחק<sup data-n=\"41\">41</sup> לכן הי' כלול משניהם, ולכן הי' בחיר שבאבות<sup data-n=\"42\">42</sup> כמ\"ש כי יעקב בחר לו י\"ה<sup data-n=\"43\">43</sup>, להיותו בקו האמצעי ת\"ת עולה עד הכתר<sup data-n=\"44\">44</sup>, ולכן בכחו לחבר חו\"ג כמ\"ש מזה באגה\"ק סי' י\"ב בענין המשל ופחד עמו, ובד\"ה גן נעול באריכות<sup data-n=\"45\">45</sup>, וז\"ש מה נורא כו' פי' נורא הוא מקור היראה<sup data-n=\"46\">46</sup> כמ\"ש ואתנם לו",[["36","36","<b>וביאור הענין</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370194\" data-slug=\"torah-or\" data-id=\"3901370194\">תו\"א מקץ מג, ב</a> (בהוספות ושינויים). סידור שער החנוכה רעג, ג ואילך."],["37","37","<b>האויר הוא למטה מיסוד האש</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ג, ה\"ד. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1005."],["38","38","<b>מה נורא המקום הזה</b>: ויצא כח, יז. ראה גם בהבא לקמן (בנוסף להערה 36) אוה\"ת תזריע ע' תקכ ואילך<sup data-n=\"e39\">א</sup>."],["39","39","<b>הגדול הגבור והנורא. . והנורא</b>: ראה אוה\"ת (וסה\"מ שם) שם שמציין: בפע\"ח שער העמידה פי\"ב. ובת\"ז<sup data-n=\"e40\">ב</sup> תיקון למ\"ד דע\"ז ע\"א ובתיקון ע' דקכ\"ב ע\"א. וע' בפרדס בעה\"כ ערך נורא<sup data-n=\"e41\">ג</sup> ובמאו\"א אות נו\"ן סעי' כ\"ב. וראה באוה\"ת (וסה\"מ שם) שם ע' תקכא."],["40","40","<b>שלכאו' בחי' נורא. . גבורה</b>: ראה גם פרדס שבהערה שלפנ\"ז."],["41","41","<b>שיעקב. . דחו\"ג אברהם ויצחק</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול בתחילתו. וש\"נ."],["42","42","<b>שיעקב. . בחיר שבאבות</b>: ראה ע\"ח שער לאה ורחל של\"ב, פ\"ב. לקו\"ת להאריז\"ל תולדות כז, כה. לקו\"ש ויחי כרך ג ע' 832 הערה 11."],["43","43","<b>כי יעקב בחר לו י\"ה</b>: תהלים קלה, ד."],["44","44","<b>ת\"ת עולה עד הכתר</b>: ראה שערי אורה לר\"י גיקטלייא שער ה (סג, ב). מאמרי אדה\"ז הקצרים ע' תקעט."],["45","45","<b>ת\"ת. . בכחו לחבר חו\"ג. . ובד\"ה גן נעול באריכות</b>: לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"נ ואילך."],["46","46","<b>נורא הוא מקור היראה</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' יט. סה\"מ תרל\"ו ח\"ב ע' שלג. המשך מים רבים תרל\"ו ע' נח־ ע' קג־ סה\"מ תרל\"ו ח\"ב ע' דש־ ע' שכט־ ע' של (מורא).\n\n<b>א</b>  נדפס גם (בשינויים קלים) בסה\"מ תרל\"ה ח\"א ע' קצח ואילך. והנחת כ\"ק אדמו\"ר מהורש\"ב בח\"ב ס\"ע תפא ואילך.\n\n<b>ב</b>  <b>בדפוס אמשטרדם תקכ\"ח. ולפנינו עד, א. קכג, ע\"א. ציונים אלו הובאו גם ביאיר נתיב למאו\"א שבפנים ההערה אלא ששם נדפס</b>: דע\"ו.\n\n<b>ג</b>  ראה גם אוה\"ת (יהל אור) תהלים ע' תקנג."]]],[2000480077,"מורא ויראוני<sup data-n=\"47\">47</sup> שהמורא שנותן<sup data-n=\"48\">49</sup> זהו מקור שיהי' ויראוני<sup data-n=\"49\">48</sup> כמ\"ש מזה במ\"א, ומורא ונורא הנו\"ן והמ\"ם שנים<sup data-n=\"50\">50</sup> מפעילים רק שהמ\"ם מורה על מקור הפעולה<sup data-n=\"51\">51</sup> בזולתו ונו\"ן הוא מקור היראה עצמה כו', וענינם א' הוא, ועכ\"ז בהשתלשלות הת\"ת הוא למטה מחו\"ג, כך הוא בענין האויר שעם היות שהיא למטה מיסוד האש במקום חנייתם בהשתלשלו' בריאותם ומצבם מ\"מ שרשו גבוה יותר עד שאויר הוא מקור האור<sup data-n=\"52\">52</sup>, וז\"ע שהוא אותיות אור יו\"ד, פי' יו\"ד הוא חכ' ונת' במ\"א שבו עצמו יש אור וכלי<sup data-n=\"53\">53</sup>, והיינו שההשכלה שבאות יו\"ד הוא בחי' אור החכ', והמביא השכלה זו לידי גילוי ממקורו הנעלם, היינו מה שנשאר אח\"כ גם כן בהעלם, זהו עצם אות היו\"ד עצמו שהאותיות פעולתם להוביל ולהמשיך אור שכל לבוא לידי גילוי, ודעת לנבון נקל<sup data-n=\"54\">54</sup> שהמביא לידי גילוי כחו יותר רב ועצום מהדבר שבא לידי בחי' הגילוי, ע\"ד כמו פועל ונפעל, שבהכרח לומר שהפועל חזק יותר מהנפעל<sup data-n=\"55\">55</sup> כו', ועד\"ז יובן בענין אויר אור יו\"ד שהיו\"ד כולל האור דתורה והאותיות שמביאים אור השכלת שכל התורה לבוא לידי גילוי כו', ואויר אור יו\"ד שהוא האור והמקור דכלליות היו\"ד דתורה, והיינו בחי' המצות שהם הם הנר שכשדולקת בהכרח שיש אויר סביבה לכן היא הממשיך בחי' תורה אור, ועז\"נ יעקב חבל נחלתו<sup data-n=\"56\">56</sup> פי' חבל לכאו' אין לו שייכות כ\"כ דהל\"ל יעקב נחלתו<sup data-n=\"57\">57</sup> אלא לרמז שכמו החבל כשראשה א' קשור למעלה<sup data-n=\"58\">58</sup> והשני הורד עד למטה מטה, הנה כשמנענעים בראש החבל שלמטה מתנענע ראש החבל שלמעלה כך המצות עם היות שהם במל' בחי' מצות המלך<sup data-n=\"59\">60</sup> מ\"מ בשרשם הם בבחי' הכתר<sup data-n=\"60\">59</sup>, שהרי תרי\"ג מצות<sup data-n=\"61\">61</sup> הם תרי\"ג",[["47","47","<b>ואתנם לו מורא ויראוני</b>: מלאכי ב, ה. ראה רש\"י שם. ראה גם סה\"מ תרל\"ו ח\"ב ע' דש. ע' שה."],["48","49","<b>שנותן</b>: בהמשך הנדפס: שניתן."],["49","48","<b>ויראוני. . ויראוני</b>: בהמשך יונתי הנדפס: ויראני<sup data-n=\"e42\">ד</sup>. במלאכי שם: וייראני<sup data-n=\"e43\">ה</sup>."],["50","50","<b>שנים</b>: אוצ\"ל: שניהם"],["51","51","<b>שהמ\"ם. . מקור הפעולה</b>: ראה גם סה\"מ תרל\"ו ח\"ב ע' שכט."],["52","52","<b>שאויר הוא מקור האור</b>: ראה סידור כאן. ש\"א כא, ב. מג, ב."],["53","53","<b>יו\"ד. . אור וכלי</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 137. לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"ב ורפ\"ג. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה שם."],["54","54","<b>ודעת לנבון נקל</b>: משלי יד, ו."],["55","55","<b>שהפועל חזק יותר מהנפעל</b>: ראה גם המשך וככה תרל\"ז ע' יז ואילך. סה\"מ תרל\"ח ע' תצד וע' תקז."],["56","56","<b>יעקב חבל נחלתו</b>: האזינו לב, ט."],["57","57","<b>נחלתו</b>: בהמשך הנדפס: חבל נחלתו. וכנשצ\"ל כבפנים."],["58","58","<b>החבל כשראשה א' קשור למעלה</b>: ראה גם (בנוסף לתו\"א כאן) <a class=\"ft-cite\" href=\"#/read/tanya/3401310050\" data-slug=\"tanya\" data-id=\"3401310050\">תניא פמ\"ה</a>. אגה\"ת פ\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380384\" data-slug=\"likkutei-torah\" data-id=\"4001380384\">לקו\"ת במדבר יט, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380858\" data-slug=\"likkutei-torah\" data-id=\"4001380858\">תצא לה, ב</a>. מאמרי אדה\"א שמות ח\"ב ע' תרז. וש\"נ. סה\"מ תרל\"ח ע' תל. לקמן מאמר ד\"ה עטרת תפארת שיבה על יד הערה 105. ולהעיר מר\"ח שער היראה פי\"ד (מא, ד). סידור קול יעקב בהקדמת הכותב ד\"ה בעה\"ר."],["59","60","<b>מצות המלך</b>: ראה אסתר ג, ג. מאמרי אדה\"א שמות ח\"א ע' יא. וש\"נ. נ\"ך ע' רלה. ש\"א ע' נו."],["60","59","<b>המצות. . שהם במל'. . בבחי' הכתר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380376\" data-slug=\"likkutei-torah\" data-id=\"4001380376\">לקו\"ת במדבר יז, א</a> (ובהנסמן בריש המאמר שם). סה\"מ תרל\"ח ח\"ב ע' שכב. וש\"נ."],["61","61","<b>תרי\"ג מצות</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטיליא מערכת שש מאות [צפת תשנ\"ב ע' 208]. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261512\" data-slug=\"likkutei-sichot\" data-id=\"1300261512\">לקו\"ש יתרו כרך כו ס\"ע 424</a> ואילך. אג\"ק שלו ח\"ג ע' רג.\n\n<b>ד</b>  <b>וכ\"ה בכ\"מ ומהם</b>: אוה\"ת תצוה כרך ז ע' ב'תשנו. מאמרי תרל\"ו שבהערה 46.\n\n<b>ה</b>  וכ\"ה גם בסה\"מ תרל\"ו ח\"ב ע' שה."]]],[2000480078,"ארחין דגלגלתא<sup data-n=\"62\">62</sup>, ותרי\"ג מצות עם ז\"מ דרבנן<sup data-n=\"63\">64</sup> הם תר\"ך<sup data-n=\"64\">63</sup> עמודי אור<sup data-n=\"65\">65</sup>, וכמשנ\"ת מזה במ\"א, לכן ע\"י עשיית המצות למטה ה\"ז כמו שמנענע בחבל למטה בקצה התחתון הנה עי\"ז מתנענע קצה העליון שלמעלה, ולכן ע\"י הנר מצוה מאיר בחי' אור התורה כו'.\n<b></b>קיצור. דעם היות הרוח הוא למטה מיסוד האש עכ\"ז שרשו גבוה יותר כמו הת\"ת &lt;4&gt;\nּ שבסדר עמידת הספירות הוא למטה מחו\"ג, ועכ\"ז עולה עד הכתר, אויר אור יו\"ד פועל ונפעל, יעקב חבל נחלתו.\nג) <b>והרמב\"ם</b> ז\"ל במ\"נ<sup data-n=\"66\">67</sup> ח\"א פ\"ז<sup data-n=\"67\">68</sup> פי' דרוח (הוא אויר) הוא ג\"כ הכוונה והרצון כמ\"ש כל רוחו יצא כסיל<sup data-n=\"68\">69</sup> דפי' כוונתו ורצונו, וכמוהו ונבקה רוח מצרים<sup data-n=\"69\">70</sup> כו', ועד\"ז נא' מי תכן את רוח ה'<sup data-n=\"70\">71</sup> כו', פי' מי הוא אשר ידע את סדר רצונו כו' ע\"ש. וכמו\"כ יובן מ\"ש בזהר שכנפי' ממשיכים הרוח כנ\"ל היינו בחי' הרצה\"ע ב\"ה<sup data-n=\"71\">66</sup>, וע' בת\"א פ' תרומה בכי\"ק ביאור לענין הכרובים בענין סוככים בכנפיהם על הכפורת<sup data-n=\"72\">73</sup>, שהכרובים נעשים מקשה אחת מהכפורת<sup data-n=\"73\">74</sup> שהוא בחי' כתר א' לשניהם<sup data-n=\"74\">75</sup>, וגם בחי' מקיף על הלוחות שבארון שהן בחי' יסוד אבא<sup data-n=\"75\">*76</sup> שנתלבשו בעשייה בזמן המשכן והמקדש, ובזמן עליית הכרובים הם מעלים גם הכפורת והלוחות לאצי' לכן הם סוככים בכנפיהם על הכפורת שהכפורת עולה<sup data-n=\"76\">76</sup> עמהם<sup data-n=\"77\">72</sup>.",[["62","62","<b>תרי\"ג מצות הם תרי\"ג ארחין דגלגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א. אגה\"ק ס\"כ (קלא, א). לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"א ובהערה 219."],["63","64","<b>ז\"מ דרבנן</b>: ראה לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות הערות 62-63."],["64","63","<b>ותרי\"ג מצות עם ז\"מ. . תר\"ך</b>: ראה תורת העולה להרמ\"א ח\"ג פל\"ח (לב, א). של\"ה יתרו שיו, א. מאו\"א מערכת תר\"ך סנ\"ו. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שלח."],["65","65","<b>תר\"ך עמודי אור</b>: ראה לקו\"ת להאריז\"ל חבקוק. מאמרי אדה\"א ויקרא ח\"ב ע' תסא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670571\" data-slug=\"torat-chaim\" data-id=\"2300670571\">תו\"ח בראשית מה, ג</a> הערה 32."],["66","67","<b>והרמב\"ם ז\"ל במ\"נ</b>: בשינויים."],["67","68","<b>פ\"ז</b>: וכ\"ה בהמשך הנדפס. ולכאורה צ\"ל כבאוה\"ת: פ\"מ."],["68","69","<b>כל רוחו יצא כסיל</b>: משלי כט, יא [ושם: יוציא. וכ\"ה באוה\"ת. בהמשך הנדפס: יוצא. וכ\"ה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 152]."],["69","70","<b>ונבקה רוח מצרים</b>: ישעי' יט, ג."],["70","71","<b>מי תכן את רוח ה'</b>: ישעי' מ, יג."],["71","66","<b>והרמב\"ם. . ב\"ה</b>: לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640312\" data-slug=\"or-hatorah-hb\" data-id=\"8316640312\">אוה\"ת שה\"ש כאן ח\"א ע' שיב</a> (בשינויים)."],["72","73","<b>סוככים בכנפיהם על הכפורת</b>: תרומה כה, כ. ויקהל לז, ט."],["73","74","<b>שהכרובים נעשים מקשה אחת מהכפורת</b>: שם כה, יח. ויקהל שם, ז."],["74","75","<b>מהכפורת. . כתר א' לשניהם</b>: ראה אוה\"ת תרומה ע' א'תנ."],["75","*76","<b>הלוחות שבארון. . יסוד אבא</b>: ראה ע\"ח שער הארת המוחין זו\"ן של\"ב, פ\"ח. תו\"א כאן."],["76","76","<b>ובזמן עליית הכרובים. . שהכפורת עולה עמהם</b>: ראה אוה\"ת שם ס\"ע א'תנז ואילך. ע' א'תנט ואילך."],["77","72","<b>בת\"א פ' תרומה. . שהכרובים. . עמהם</b>: פא, ב (בשינוי קל)."]]],[2000480079,"<b>והנה</b> זמן עפיפתם היינו עלייתם נת' בזהר פ' אחרי דנ\"ט<sup data-n=\"78\">78</sup> ובפ' ויחי דרך\"ח סע\"ב תלת זמנין ביומא כו', אינון מגרמייהו סלקין גדפייהו כו', ופי' הרמ\"ז שם דהיינו בשעת ג' תפלות שבכל יום, היינו בכל עת וזמן התפלה שהוקבע למטה הנה הם עולים ג\"כ, והיינו ע\"י התעוררות אהוי\"ר שבישראל, שנודע שהאוי\"ר נק' גדפין<sup data-n=\"79\">79</sup> וע\"י פרחא לעילא<sup data-n=\"80\">77</sup>, ולכן קיום התומ\"צ זמן עלייתן הוא בזמן התפלה לפי שאז הוא זמן התעוררות אהוי\"ר בעבודה בנפש האדם כו', וז\"ע עולת תמיד<sup data-n=\"81\">80</sup> כמ\"ש במ\"א, ולכן אז מתעוררים ג\"כ הכרובים וסלקין גדפייהו כו', ושרש ענין עליות התומ\"צ בזמן התפלה מפני שאז מתעוררים בנש\"י בחי' אהוי\"ר כנ\"ל זהו כי גם שרש המצות הוא ג\"כ אהוי\"ר, וכנודע ממ\"ש במ\"א באורך שאהבה היא שרש רמ\"ח מ\"ע ויראה היא שרש שס\"ה ל\"ת<sup data-n=\"82\">81</sup> רק שבענין המצות הנה האהוי\"ר הם רק שרשם לבד, ובתפלה הוא זמן התעוררות עצמם, והם בחי' הגדפין לפרחא ע\"י לעילא כו', ועכ\"ז גם בכל המצות יש כח בחי' גדפי' שהרי ארז\"ל במדרש תנחומא הוי זהירין<sup data-n=\"83\">83</sup> במצות<sup data-n=\"84\">82</sup> שהם שלוחי ושלוחו של אדם כמותו, פי' שלוחי' שנשלח ע\"י בחי' הרצה\"ע עד למטה מטה להתלבש בדברים הגשמים וה\"ז כמו הכנפים הם שלוחי הרצון שע\"י השלוחי' אלו יגיע העוף לעופף למעלה או למטה כפי הרצון כנ\"ל להיות כי הם שלוחי הרצון כו', וכן המצות הם שלוחי הרצה\"ע כו', וכמו שהכרובים היו סוככי' בכנפיהן כו', כן בחי' המצות הם סכך ומקיף על בחי' הלוחות שהם בחי' יסו\"א, וכמשי\"ת לקמן אי\"ה בענין הראני את מראיך<sup data-n=\"85\">85</sup> והשמיעני כו', דשרש המצות גבוהות יותר<sup data-n=\"86\">84</sup> כו', וגם עכשיו כשנגנז הארון<sup data-n=\"87\">87</sup> כו' הנה ארז\"ל אין להקב\"ה בעולמו אלא ד\"א של<sup data-n=\"88\">88</sup> הלכה<sup data-n=\"89\">86</sup> שהם במקום המקדש והשראת שכינתו שבין ב' בדי הארון<sup data-n=\"90\">89</sup>",[["78","78","<b>דנ\"ט</b>: בתו\"א ניתוסף: ע\"א."],["79","79","<b>שהאוי\"ר נק' גדפין</b>: ראה תניא פ\"מ. פמ\"א ובמ\"מ הגהות והע\"ק שם ע' רסט. מאמרי אדה\"א בראשית ע' עה. וש\"נ."],["80","77","<b>והנה. . בזהר. . לעילא</b>: לשון <a class=\"ft-cite\" href=\"#/read/torah-or/3901370355\" data-slug=\"torah-or\" data-id=\"3901370355\">תו\"א תרומה עט, ד</a> (בשינוי)."],["81","80","<b>התומ\"צ. . בזמן התפלה. . עולת תמיד</b>: פינחס כח, ו. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. פלח הרמון בהר ע' שצב. וש\"נ."],["82","81","<b>שאהבה. . רמ\"ח מ\"ע ויראה. . שס\"ה ל\"ת</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא</a> פ\"ד ובמ\"מ, הגהות והע\"ק לשם. של\"ה מאמר ג ומאמר ד נא, ב. מאמרי אדה\"א קונטרסים ע' פז. וש\"נ."],["83","83","<b>הוי<sup data-n=\"e44\">ז</sup> זהירין במצות</b>: בתנחומא: היו מכבדין את המצות — וכ\"ה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 175."],["84","82","<b>במדרש תנחומא הוי זהירין במצות</b>: ויגש<sup data-n=\"e45\">ו</sup> ו. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380082\" data-slug=\"likkutei-torah\" data-id=\"4001380082\">לקו\"ת ויקרא ב, א</a>. סה\"מ תרל\"ג ח\"א ע' נג. וש\"נ (ובריש המאמר שם). המשך מים רבים תרל\"ו ע' קצח. סה\"מ תרפ\"ט ע' 7."],["85","85","<b>וכמשי\"ת לקמן. . הראני את מראיך</b>: שה\"ש ב, יד. לשון אוה\"ת כאן כנ\"ל בהערה שלפנ\"ז. ראה גם לקמן מאמר ד\"ה וזהו שרש יונתי ובהערה 3."],["86","84","<b>סוככי'. . יותר</b>: לשון אוה\"ת שה\"ש כאן ע' שיב (בשינויים)."],["87","87","<b>כשנגנז הארון</b>: יומא (נג, ב) נד, א."],["88","88","<b>אין להקב\"ה. . ד\"א של הלכה</b>: ראה ברכות ח, א. מאמרי אדה\"ז תקע\"א ע' צח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550570\" data-slug=\"torat-chaim\" data-id=\"2300550570\">תו\"ח תרומה ח\"ב שיז, ב</a> ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. הנחות תקע\"ז ע' ש. וש\"נ."],["89","86","<b>וגם עכשיו. . הלכה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370356\" data-slug=\"torah-or\" data-id=\"3901370356\">תו\"א תרומה פ, א</a>."],["90","89","<b>והשראת שכינתו שבין ב' בדי הארון</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 227.\n\n<b>ז</b>  בהמשך יונתי הנדפס: הוו.\n\n<b>ו</b>  בהמשך תער\"ב ח\"ג ע' א'שנא: במד\"ת פ' עקב כבדו את המצות."]]],[2000480080,"הוא עכשיו בד' אמות של הלכה, והמצות שהם גדפין בחי' כנפי' העליונים, הם סוככים בכנפיהם על הכפורת &lt;5&gt;\nּ והארון והלוחות שהוא ענין ד\"א של הלכה דעכשיו כו', בבחי' לימוד התורה לשמה שבה שורה אוא\"ס דאורייתא וקוב\"ה כולא חד<sup data-n=\"91\">90</sup> כו', וארז\"ל א\"ת חרות<sup data-n=\"92\">92</sup> כו' שאין לך בן חורין אלא מי שעוסק בתורה (בפ\"ו דאבות)<sup data-n=\"93\">91</sup> וכל א' מישראל מקיים לימוד התורה ע\"פ הדחק ע\"י שהוקבע בסדר התפלה<sup data-n=\"94\">93</sup> דברי רז\"ל<sup data-n=\"95\">94</sup>, וע' בסוף מנחות בענין הלכה ואין מורין כן<sup data-n=\"96\">95</sup>, ופי' מלאים מצות כרמון<sup data-n=\"97\">96</sup> כו', ולכן המשל דומה לנמשל מה יונה כנפי' מגינות כו' כך ישראל מצות מגינות כו'.\n<b></b>קיצור. לפי פי' הרמב\"ם ז\"ל רוח הוא הרצון, א\"כ מצות שהם רצה\"ע הם עצמם בחי' רוח, ובכלליות הגדפי' דכרובי' מקיפי' גם על יסו\"א הן בהעלאה והן בהמשכה, וזהו מה יונה כו' כך ישראל מצות מגינות עליהם כו'.",[["91","90","דאורייתא וקוב\"ה כולא חד: מובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא (פ\"ד</a> ופכ\"ג) בשם הזהר. ראה מאמרי אדה\"א ויקרא ח\"א ע' רפה. וש\"נ. אוה\"ת חוקת ע' תשס."],["92","92","<b>חרות</b>: תשא לב, טז."],["93","91","<b>א\"ת חרות. . שעוסק בתורה<sup data-n=\"e46\">ח</sup> (בפ\"ו דאבות)</b>: ה\"ב [ושם: בתלמוד תורה<sup data-n=\"e47\">ט</sup>. ראה שינוי נוסחאות לשם]."],["94","93","<b>וכל א' מישראל מקיים לימוד התורה. . התפלה</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן. לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"ס על יד הערות 1713-1714."],["95","94","<b>רז\"ל</b>: בהמשך הנדפס: חז\"ל."],["96","95","<b>בסוף מנחות בענין הלכה ואין מורין כן</b>: וכ\"ה בהמשך הנדפס. ראה שם צט, ב (לדעת ר\"י בשם רשב\"י). לו, ב. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן."],["97","96","<b>מלאים מצות כרמון</b>: חגיגה כז, א. ראה גם מאמרי אדה\"א דברים ח\"א ע' נב. וש\"נ. דרושי חתונה ח\"ב ריש ע' תמח. וש\"נ. הנחות תקע\"ז ריש ע' רכו. סה\"מ תרל\"ח ס\"ע שעט ואילך.\n\n<b>ח</b>  וכ\"ה בכ\"מ ומהם: אוה\"ת תשא ע' ב'כב. ויקרא ע' קיח. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 183. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111105\" data-slug=\"likkutei-sichot\" data-id=\"1300111105\">לקו\"ש עקב כרך ב ע' 371</a>*. משפטים כרך יא ע' 97 הערה 57*. כרך כז ל\"ג בעומר ע' 292*.\n\n<b>ט</b>  וכ\"ה בסה\"מ מלוקט ד' ע' רעט*. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271306\" data-slug=\"likkutei-sichot\" data-id=\"1300271306\">לקו\"ש</a> חג הפסח כרך יז ע' 75*. ויגש כרך לה ע' 204."]]],[2000480081,"<h3>[ואהבת את ה' אלקיך] והנה כמו שנמשלו המצות בנר</h3>\n<b>בס\"ד פ' עקב</b>\nד) <b>והנה</b> כמו שנמשלו המצות בנר<sup data-n=\"98\">97</sup> כמ\"ש כי נר מצוה וכנ\"ל, כך נשמות נמשלו ג\"כ לנר, כמ\"ש נר ה' נשמת אדם<sup data-n=\"99\">98</sup> כו' שנמשלה נשמת אדם לנר, ולא עוד אלא שנמשלה לנר הוי', וצ\"ל ענינם. ויובן בתחלה ענין נר<sup data-n=\"100\">99</sup>, שעם היות שלכאו'",[["98","97","<b>והנה כמו שנמשלו המצות בנר</b>: מכאן מתחיל מאמר הב' מהמשך יונתי (הכולל פרקים ד-ז).\nלמאמר זה ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370174\" data-slug=\"torah-or\" data-id=\"3901370174\">תו\"א מקץ לח, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370178\" data-slug=\"torah-or\" data-id=\"3901370178\">ג. לט, סע\"ב</a> ואילך.\nמאמר זה הובא בסה\"מ מלוקט ב' ס\"ע קכה ובהערה 64. ריש ע' קכז ובהערה 76.\nהנחת<sup data-n=\"e48\">*</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן (בחלק הנחותיו) ושם הפתיחא: ואהבת את ה' אלקיך."],["99","98","<b>נר ה' נשמת אדם</b>: משלי כ, כז."],["100","99","<b>ענין נר</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370174\" data-slug=\"torah-or\" data-id=\"3901370174\">תו\"א מקץ לח, ב</a>."],["e48","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000480082,"עיקר הנר הוא השמן או החלב שממנה נעשית הנר, עכ\"ז באמת העיקר הוא הפתילה שהרי השמן או החלב בפ\"ע לא ידליק כלל וכלל, ועיקר דליקתם הוא באמצעית הפתילה דוקא, והגם שא\"א להכחיש שכשהשמן לא טוב הוא אין האור דולק יפה אמנם כמו\"כ הוא שכאשר הפתילה לא טוב הוא ג\"כ לא טוב הוא ולכן ארז\"ל פתילות ושמנים שאמרו חכמים<sup data-n=\"101\">100</sup> אין מדליקין בהם בשבת כו' שאסרו חכמים להדליק בהם מפני שאינם נמשכים אחר הפתילה והפתילות ג\"כ יש שאינם דולקים יפה, שבזה שניהם שוה, ועכ\"ז יש יתרון לפתילה על השמן שהאור נאחז בפתילה דוקא והיא ג\"כ המושכת את השמן או החלב, וגם אינה מנחת שיבא האור להשמן או להחלב שאם בא יבא האור להם יכבה ע\"י שיטבע בהן כו', ונמצא כי הפתילה ה\"ה כמו ממוצע בין שמן לאור ובה נאחז האור כו' ופעולת השמן או החלב הוא שידלק הרבה, שהרי הפתילה עצמה היתה דולקת מהר, גם ע\"י השמן והחלב ירבה עצם אורה, אך ג\"ז תלוי בפתילה ג\"כ שהרי כשהפתילה לא טובה לא תבהיק אורה כו'.\n<b>וככל</b> המשל הזה נבין ג\"כ בנשמה שקרוי' נר, ושז\"ע שקרוי' נר הוי' דוקא, דהנה כתי' כי חלק הוי' עמו<sup data-n=\"102\">101</sup>, שכאו\"א הוא חלק ה' ממש<sup data-n=\"103\">102</sup>, ולכן גם בתמונת הגוף יש שם הוי'<sup data-n=\"104\">103</sup> שהראש הוא כמו יו\"ד, וה' אצבעות דיד ודרגל<sup data-n=\"105\">104</sup> הם ה'<sup data-n=\"106\">105</sup> כמו ב' ההי\"ן ה' עילאה וה' תתאה והגוף תמונתו כמו וא\"ו ובראשו יו\"ד הוא הראש כו', והיינו מפני שהגוף יהי' חומר מוכן לקבל צורת הנפש שהיא חלק הוי' ממש, והמופת לזה הוא &lt;6&gt;\nּ מעונש הגלגולים שהוא עונש מר ממות כו', והוא מה שמתגלגל נפש",[["101","100","<b>פתילות ושמנים שאמרו חכמים</b>: שבת כא, א."],["102","101","<b>כי חלק הוי' עמו</b>: האזינו לב, ט. ראה גם לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים סוף פיסקא א."],["103","102","<b>חלק ה' ממש</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 395."],["104","103","<b>בתמונת הגוף יש שם הוי'</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך כאן על יד הערה 11. סה\"מ תרצ\"ז ע' 208 בשם הזהר<sup data-n=\"e49\">א</sup>. אוה\"ת בשלח כרך ז' ע' ב'תרעב בשם הר\"ח שע\"א, פ\"א<sup data-n=\"e50\">ב</sup>. יתרו ע' תשכה בשם הר\"ח שער היראה פ\"ז<sup data-n=\"e51\">ג</sup>. בא כרך ח ריש ע' ב'תתקלב. תזריע כרך ב ע' תקכד. סה\"מ תרכ\"ז ע' רכו. תרכ\"ט ע' יח. ע' ריז. ס\"ע שא ואילך. ע' שצד. תרמ\"ד ע' רכג. תרנ\"ו ע' שכ. תש\"ח ע' 66. סה\"מ מלוקט ד' ע' עדר. מאמר ד\"ה אנכי ה\"א תשכ\"ו. וראה גם סד\"ה שובה ישראל תשמ\"ט<sup data-n=\"e52\">ד</sup>. סה\"ש תש\"נ ח\"א ע' 381 בפנים<sup data-n=\"e53\">ה</sup>."],["105","104","<b>וה' אצבעות דיד ודרגל</b>: השווה לזהר ופי' רא\"ג ולהדרושים שבהערה שלפנ\"ז. וראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן: והגם שאין זה תמונת ה' מ\"מ הוא מספר ה."],["106","105","<b>ה'</b>: בהמשך יונתי הנדפס ליתא.\n\n<b>א</b>  <b>רע\"מ בא מב, סע\"א (הועתק בר\"ח שער היראה פ\"א — בשינוי קל). ושם</b>: יו\"ד איהו דיוקנא דרישא. . ה' ה' דיוקנא דה' אצבעאן דימינא וה' דשמאלא ו' דיוקנא דגופא. וראה גם פי' רא\"ג באור החמה שם.\n\n<b>ב</b>  ד\"ה עוד נתייחס (ח, ב).\n\n<b>ג</b>  <b>כנצ\"ל</b>: פ\"א כבאוה\"ת בשלח.\n\n<b>ד</b>  <b>ושם</b>: שלכל פרצוף. . השם הוי'. העינים לראות — היו\"ד. אזנים לשמוע — ה\"א ראשונה. חוטם — וא\"ו (ציור החוטם כוא\"ו). פה — ה\"א אחרונה (ה' מוצאות הפה).\n\n<b>ה</b>  <b>ושם</b>: דער ציור גוף הגשמי (דער פנים) איז בדוגמת הציור פון די ד' אותיות שם הוי' — ומציין לע\"ח היכל א' שער ד' פ\"א ואילך [ושם: ראי' שמיעה ריחא דבור והם ד' אותיות הוי']."]]],[2000480083,"האדם בבע\"ח<sup data-n=\"107\">106</sup> או בצומח או בדומם<sup data-n=\"108\">107</sup>, ואם נאמר שהנפש א\"צ חומר, שיהי' בו צורה כצורת הנפש מהו העונש והצער שיש לנשמה מזה שאם נאמר שזהו רק מה שא\"א לה להשיג ולהגיע למדריגתה ברוחני' הלא הנשמות הנדחי' הפורחים באויר השמים עונשם קל יותר מנשמות המגולגלות<sup data-n=\"109\">108</sup>, אלא מפני שהנשמות המגולגלות בבע\"ח שמפני שתמונת<sup data-n=\"110\">109</sup> גופם<sup data-n=\"111\">110</sup> הוא ע\"פ ציור נפשם המחי' אותם שהוא מעולם התהו ממה שנפל בשבה\"כ כנודע, אשר בתהו לא יש בחי' היושר כ\"א בחי' עיגולים ולכן הראש שוה לזנבה בבהמה ובחי' כו', משא\"כ באדם<sup data-n=\"112\">111</sup> דתיקון שהוא בבחי' יושר הראש למעלה והרגלים למטה, ולכן כאשר מתגלגל נפש האדם בבהמה עונשה מר ממות לפי שקשה וגדול צערה מאד מאד כו', וכמשנ\"ת מזה בד\"ה קדש ישראל לה' (י\"ד) ובד\"ה פתילות ושמנים (ך\"ט) באריכות<sup data-n=\"113\">112</sup> ע\"ש. שזהו מטעם הנ\"ל שהגוף צ\"ל חומר מוכן לקבל צורת הנפש, שנמצא מפני כי חלק הוי' עמו לכן גם בגוף האדם יש בו תמונת ש' הוי' כו'.\n<b></b>קיצור. שכמו שהמצות נק' נרות כך הנשמה קרוי' נר, נר הוי', שחלק ה' עמו, ולכן גם תמונת הגוף הוא חומר מוכן לקבל צורת הנפש והראי' מגלגולים כו'.\nה) <b>וענין</b> בחי' שם הוי' שבנפש האדם<sup data-n=\"114\">113</sup>, הנה היו\"ד הוא בחי' חכ'<sup data-n=\"115\">114</sup> שבעצם בחי' החכ' היא עדיין למעלה משכל המושג ומובן כו', כ\"א בחי' ברק המבריק<sup data-n=\"116\">115</sup>",[["107","106","<b>שמתגלגל. . בבע\"ח</b>: ראה ת\"ז ת\"ע קלג, א ובכס\"מ שם אות ת (קעח, א). סה\"מ תרכ\"ט ע' יח. וש\"נ. ע' ריח. וש\"נ. ע' שצה. פלח הרמון בהר ע' שצו. וש\"נ."],["108","107","<b>שמתגלגל. . בדומם</b>: ראה מאמרי אדה\"א קונטרסים ע' ה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670317\" data-slug=\"torat-chaim\" data-id=\"2300670317\">תו\"ח נח סח, ב</a> ובהערה 9. שמות ח\"א כח, ב. וש\"נ."],["109","108","<b>הנשמות הנדחי' הפורחים באויר.. המגולגלות</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 15."],["110","109","<b>בבע\"ח שמפני שתמונת גופם. . בד\"ה קדש ישראל לה' (י\"ד)</b>: ראה בקיצור ממאמר ד\"ה ויגש תרכ\"ט (סה\"מ תרכ\"ט) ע' יח: כמשנ\"ת ענין זה באריכות בד\"ה קדש ישראל דתרי\"ד. שם ע' שצה: וע' מזה בד\"ה קדש ישראל דתרי\"ד. הנחת כ\"ק אדמו\"ר מהר\"ש מדרוש זה נדפסה במאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' כא [ושם רק נזכר]."],["111","110","<b>בבע\"ח שמפני שתמונת גופם. . ובד\"ה פתילות ושמנים (ך\"ט)</b>: בסה\"מ תר\"ל ע' רצב: ומעט נת' מזה בד\"ה ויגש אליו יהודה (כ\"ט) — ראה בהערה שלפנ\"ז."],["112","111","<b>הראש שוה לזנבה בבהמה. . משא\"כ באדם</b>: ראה גם לקמן מאמר ד\"ה ויאמר כו' לך לך על יד הערה 40. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 21. ד\"ה ויאמר כו' לך לך על יד הערה 62. מאמרי אדה\"א במדבר ח\"ג ע' תתצו ואילך. ע' תתקטז ואילך. שע\"ת סא, ג ואילך."],["113","112","<b>באריכות</b>: ראה הערה 109."],["114","113","<b>שם הוי' שבנפש האדם</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">לקו\"ת פ' ראה יח, א</a>. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהנסמן שם."],["115","114","<b>היו\"ד. . חכ'</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38. (לעיל הערה 26)."],["116","115","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק לקמן רפ\"י. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך כאן על יד הערה 25. הנחה ד\"ה יפה שעה אחת הא' על יד הערה 97. (בחלק ההנחות) ד\"ה יפה שעה אחת הא' על יד הערה 109. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 21. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540888\" data-slug=\"torat-chaim\" data-id=\"2300540888\">תו\"ח בשלח ח\"א קצז, ב</a>. וש\"נ. סה\"מ תרל\"ח ע' פא. וש\"נ. פלח הרמון אמור ע' של."]]],[2000480084,"לבד, וקוש\"י הוא הרצון שלמעלה מהטו\"ד<sup data-n=\"117\">116</sup> לגמרי, וכמ\"ש כי עם קשה עורף הוא ולכן וסלחת<sup data-n=\"118\">117</sup> כמ\"ש במ\"א, וה' ראשונה הוא בחי' ההתבוננות בגדולת ה' איך שמה רבו מעשיך ה'<sup data-n=\"119\">118</sup>, וכתי' מה גדלו מעשיך ה'<sup data-n=\"120\">119</sup>, וההפרש שביניהם שמה גדלו קאי על עולמות עליונים והנבראי' היותר גדולים<sup data-n=\"121\">120</sup> כמלאכים ושמש וירח כו' שהמלאך בשליש העולם עומד<sup data-n=\"122\">121</sup> כו' כמ\"ש במ\"א, ע' בלק\"ת בד\"ה יונתי<sup data-n=\"123\">122</sup> בחגוי הסלע, וכן השמש היא גדולה מאד כמ\"ש הרמב\"ם ז\"ל בפ\"ג ה\"ח מה' יסוה\"ת כמו ק\"ע פעמים<sup data-n=\"124\">123</sup> מהארץ והארץ גדולה מהירח כמו ארבעים פעמים כו' ע\"ש, ועליהם אמר המשורר מה גדלו מעשיך ה' שהם נבראים הגדולים כנ\"ל, וכאשר התבונן על ריבוי התהוות הנבראים שנתהוו ריבוי מיני דצח\"מ כו', כמו בדומם<sup data-n=\"125\">124</sup> מן האבנים הפשוטי' עד האבנים היקרות שבחשן ואפוד יש ריבוי מינים עד אין שיעור והכל בסוג הדומם, שאין יתרון לשוהם עד\"מ על האבן הפשוט בסוג מין הדומם שהכל א' הוא, רק שזה פשוט ובנמצא הרבה וזה טוב ויקר המציאות וטורח רב להשיגו כו', וכן בצומח יש צמחים רבים עד אין שיעור שיש ריבוי מיני עשבים<sup data-n=\"126\">126</sup> זרעוני גינה וריבוי מיני אילנות<sup data-n=\"127\">125</sup> סרק ופירות, וצמח התבואות והכל בסוג א' שהוא ממין הצומח כו', וכן בע\"ח הם רבים במספר עד אין שיעור למיניהם חלוקים זה מזה בהמות דקות וגסות",[["117","116","<b>וקוש\"י הוא הרצון שלמעלה מהטו\"ד</b>: ראה זהר ויקרא י, ב. פרדס שער שם בן ד' שי\"ט, פ\"ב. הנסמן במאמרי אדה\"א קונטרסים ע' תכז."],["118","117","<b>כי עם קשה עורף. . וסלחת</b>: תשא לד, ט. ראה שמו\"ר פמ\"ב, ט. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380589\" data-slug=\"likkutei-torah\" data-id=\"4001380589\">לקו\"ת בלק סז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380603\" data-slug=\"likkutei-torah\" data-id=\"4001380603\">עא, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550766\" data-slug=\"torat-chaim\" data-id=\"2300550766\">תו\"ח תצוה ח\"ב שעט, ד</a>. וש\"נ. סה\"מ תרכ\"ז ס\"ע עד ואילך. וש\"נ. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 27."],["119","118","<b>שמה רבו מעשיך ה'</b>: תהלים קד, כד. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370252\" data-slug=\"torah-or\" data-id=\"3901370252\">תו\"א וארא נו, ב</a>. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהנסמן שם."],["120","119","<b>מה גדלו מעשיך ה'</b>: תהלים צב, ו. ראה בהערה שלפנ\"ז."],["121","120","<b>וההפרש. . שמה גדלו. . עולמות עליונים והנבראי' היותר גדולים. . מה רבו. . ריבוי התהוות הנבראים</b>: ראה לקמן מאמר ד\"ה וזהו שרש יונתי על יד הערה 24. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה ויאמר משה על יד הערה 24 ואילך. סה\"מ תרכ\"ט ע' קנט. תרל\"ב ח\"א ע' רג. המשך מים רבים תרל\"ו ספקנ\"ו: כנודע ההפרש וההבדל בין מה רבו למה גדלו. . כמ\"ש מזה בד\"ה מי יתנך<sup data-n=\"e54\">ו</sup> ובהביאור וההגהות לשם. ראה בהערות שלפנ\"ז."],["122","121","<b>שהמלאך בשליש העולם עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול הערה 44."],["123","122","<b>שהמלאך בשליש העולם. . בלק\"ת בד\"ה יונתי</b>: שה\"ש טז, ד. ראה גם המשך מים רבים תרל\"ו ספקנ\"ו."],["124","123","<b>השמש. . כמו ק\"ע פעמים</b>: ראה לקמן מאמר ד\"ה וזהו שרש יונתי על יד הערה 27: ”בערך קס\"ז פעמים\". שער היחוה\"א פ\"ז<sup data-n=\"e55\">ז</sup> ובשיעורים בספר התניא שם ע' 848. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101180\" data-slug=\"likkutei-sichot\" data-id=\"1300101180\">לקו\"ש בראשית כרך י ע' 180</a> ואילך. מ\"מ הגהות והע\"ק לסש\"ב שם (ע' שפד). לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 32."],["125","124","<b>ריבוי. . בדומם</b>: ראה גם לעיל מאמר ד\"ה ואעשך לגוי גדול ובהערה 37."],["126","126","<b>ריבוי מיני עשבים</b>: ראה גם פי' הראב\"ד לס\"י פ\"א, מ\"א. ביאוה\"ז נשא כרך א ע' תעב."],["127","125","<b>בצומח. . עשבים. . אילנות</b>: ראה גם פלח הרמון וארא ע' נח: בסוג הצומח מנו חכמי המחקר ס\"ז אלף מינים ובודאי יש יותר רק שבזמנם לא השיגו יותר. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך שם.\n\n<b>ו</b>  ראה מאמר ד\"ה שאו את ראש (שלאחרי הפתיחא מתחיל מי יתנך) תרכ\"ו ריש ע' קה.\n\n<b>ז</b>  ראה גם סה\"מ תרל\"ג ח\"ב ע' תקמט. תרכ\"ז ע' תפ. לקוטי לוי יצחק הערות לתניא שם ע' כז."]]],[2000480085,"טמאות וטהורות וחיות קטנות וגדולים ועופות טמאי' &lt;7&gt;\nּ וטהורין והכל בסוג בע\"ח, וכן מין האדם<sup data-n=\"128\">127</sup> אם כי בכלל אחד הוא ועכ\"ז יש מינים חלוקים הן בטבעית והן גם בציור גופם חלוקים זמ\"ז וכמ\"ש בספרי המסע שיש מיני בנ\"א שונות בעיניהם<sup data-n=\"129\">128</sup> וכדומה כו', וכאשר התבונן בכ\"ז אמר מה רבו מעשיך ה' שיש ריבוי התהוות הנבראים לאין שיעור כלל וכלל, ואי לזאת כשיתבונן האדם בכ\"ז יבוא אח\"כ גם להתבונן במ\"ש שאו מרום עיניכם<sup data-n=\"130\">129</sup> וראו כו' שהרי אין לך עשב<sup data-n=\"131\">130</sup> מלמטה שאין לו מזל ברקיע המכה בו ואומר לו גדל, ובהעמקת הדעת בהתבוננות איך שלכולם בשם יקרא איש לא נעדר<sup data-n=\"132\">131</sup> פי' איש הוא כח שלמעלה השולט על העשב שלמטה המכה בו וא\"ל גדל, כמו האיש אדוני הארץ<sup data-n=\"133\">132</sup>, איש האלקי'<sup data-n=\"134\">133</sup>, ובדרז\"ל אישי כה\"ג<sup data-n=\"135\">134</sup>, הנה עי\"ז יבין גדולת הבורא בטוב טעם ודעת אשר כל מגמתו יהי' לדבקה בו ית' כו', וזהו בחי' ה' עילאה בינה התבוננות כו'.\n<b>וענין</b> בחי' ו\"ה הוא מדות ודבור, מה הוא רחום<sup data-n=\"136\">135</sup> אף אתה הוי רחום כו', ובכלל הוא בחי' קול ודבור שיהי' קולו בד\"ת ודבורו בדבור התו' והתפלה בחי' הקל קול יעקב<sup data-n=\"137\">136</sup>, ובד\"פ וא\"ו הוא בחי' תורה קול מלא וא\"ו, וה' אחרונה מצות הצדקה שכל המצות נק' בשם צדקה כנ\"ל, וז\"ע ש' הוי' שבנפש אשר בכדי שיהי' יוצא מכח אה\"פ נעשה הגוף ג\"כ חומר מוכן לקבל צורת הנפש כו'.\n<b></b>קיצור. ש' הוי' שבנפש, יו\"ד ביטול ה' התבוננות כו' ו\"ה תומ\"צ כו'.\nואו) <b>ואמנם</b> הנה נודע כי באדם יש ב' נפשות נה\"א ונה\"ב כדכתי' ונשמות אני עשיתי<sup data-n=\"138\">137</sup>, ובזה יובן מ\"ש ואהבת את ה' אלקיך בכל לבבך וארז\"ל במשנה בסוף ברכות בשני יצריך<sup data-n=\"139\">138</sup> ביצ\"ט וביצה\"ר, אשר לכאו' יפלא איך יבוא היצה\"ר לאהוב את ה' הלא הוא מכנה אותו בשם רע על פעולתו הרעה ואיך יבוא",[["128","127","<b>בע\"ח הם רבים במספר. . וכן מין האדם</b>: ראה גם לעיל שם. וש\"נ."],["129","128","<b>וכמ\"ש בספרי המסע שיש מיני בנ\"א שונות בעיניהם</b>: ראה גם שבת לא, א. ראה גם לקמן מאמר ד\"ה וזהו שרש יונתי על יד הערה 36 (לכללות הענין) בספרי המדע והמחקר. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 41 בס' המסעות. . מיני ברואים בעין א' ובג' עינים."],["130","129","<b>שאו מרום עיניכם</b>: ישעי' מ, כו."],["131","130","<b>אין לך עשב</b>: ראה ב\"ר פ\"י, ו. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 549."],["132","131","<b>שלכולם בשם יקרא איש לא נעדר</b>: המשך הכתוב ישעי' שם [בדילוג]."],["133","132","<b>האיש אדוני הארץ</b>: מקץ מב, ל."],["134","133","<b>איש האלקי'</b>: ברכה לג, א."],["135","134","<b>אישי כה\"ג</b>: יומא פ\"א, מ\"ג. מ\"ה."],["136","135","<b>מה הוא רחום</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380642\" data-slug=\"likkutei-torah\" data-id=\"4001380642\">לקו\"ת פינחס פ, ג</a>. שבת קלג, ב. ספרי עקב יא, כב."],["137","136","<b>הקל קול יעקב</b>: תולדות כז, כב. ראה סידור שער התפלה יט, סע\"א ואילך. מאמרי אדה\"א בראשית ע' שמח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680453\" data-slug=\"torat-chaim\" data-id=\"2300680453\">תו\"ח מקץ רכז, ב</a> ובהערות 32-4."],["138","137","<b>ב' נפשות. . ונשמות אני עשיתי</b>: ישעי' נז, טז. ראה תניא פ\"א<sup data-n=\"e56\">ח</sup>."],["139","138","<b>ואהבת. . בשני יצריך</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 18.\n\n<b>ח</b>  וראה גם במ\"מ הגהות והע\"ק ובליקוט פירושים שם."]]],[2000480086,"לאהבה את ה', ואם מתהפך לטוב מדוע יקרא יצר הרע כו', אך הענין הוא שבכל נפש משתי הנפשות הנ\"ל יש שני בחי' בכלל, והם שכל ומדות, אשר בנה\"א יש בחי' שכל ומדות וכן גם בנה\"ב יש ג\"כ שכל ומדות כו', אמנם הנה הם הפכים זמ\"ז לגמרי ורחוקי' בתכלית הריחוק זמ\"ז עד שנק' זה לעומ\"ז<sup data-n=\"140\">139</sup> כו', והנה בשני הבחי' שיש בכל נפש מהנפשות הנ\"ל העיקר הוא השכל שהוא המנהיג את המדה ומובילה לאיזה צד שירצה כו', ולכן הנה\"א שעיקר השכלתה והתבוננותה הוא בגדולת א\"ס ב\"ה כנ\"ל בענין מה רבו כו' ומה גדלו הנה היא תקועה בחוזק בדביקת האלקות, ולכן הולדת האהוי\"ר שנולדים מהשכלה זו הם לאהבה אותו ולירא ממנו ולדבקה בו כו', אמנם שכל הנה\"ב הוא להשכיל השכלות שבעניני העוה\"ז החומרי שכולו מלא שקרים<sup data-n=\"141\">140</sup> שכל הטוב הוא כמו המרבה לאכול דבש מחמת מתיקותו עד שיחלה, כן כל עניני העוה\"ז העריבים על האדם &lt;8&gt;\nּ באמת סופם לקוץ בהם כו' אך ב\"כ<sup data-n=\"142\">141</sup> מראה לו איך שטוב לפניו ונולדים מזה מדות הרעות לאהוב מה שאינו שלו ולשנוא זולתו מה<sup data-n=\"143\">142</sup> שיש לו דבר זה, כי מדוע מונע ממנו ג\"כ הדבר הזה, ומדוע לא יגיע לו ככה עד שבא לכעוס עליו ולשנוא אותו וכדומה להתפאר במה ששקר וכזב וכדומה, ולזאת ירדה הנשמה היא הנה\"א מבחי' עמידתה שעמדה באהוי\"ר לפניו ית' כמ\"ש חי ה' אשר עמדתי לפניו<sup data-n=\"144\">143</sup> להתלבש בגוף ונה\"ב בכדי לברר גם נה\"ב ולהבינה במה שהיא יכולה להבין בבחי' ההתבוננות דמה רבו ומה גדלו לפי ערכה עד שתוליד גם הנה\"ב מדות דקדושה לירא מפניו ולאהבה אותו כו', והוא ע\"י הקדמת פסוק ראשון דק\"ש שמע ישראל<sup data-n=\"145\">144</sup> כו' פי' שמע הוא לשון השגה והבנה<sup data-n=\"146\">145</sup> כמו הסכת ושמע<sup data-n=\"147\">146</sup>, וגם מל' אסיפה וקיבוץ<sup data-n=\"148\">147</sup> כמו וישמע שאול<sup data-n=\"149\">148</sup> ושניהם ענינם א', והיינו להתבונן ולאסוף כל הכחות בהתבוננות זו להשכיל ולהבין איך שהוי' אלקינו הוא ה' אחד, פי' ה' אלקינו, אלקינו הוא בחי' סוכ\"ע וממכ\"ע<sup data-n=\"150\">149</sup> וה' הוא אלקינו שבחי' סוכ\"ע וממכ\"ע נמשך תמיד מאין ליש, ובטובו מחדש בכי\"ת מע\"ב<sup data-n=\"151\">150</sup>, ואלמלא נסתלק כרגע הי' אין ואפס, והוא ה' אחד שאתה הוא קודם שנבה\"ע<sup data-n=\"152\">151</sup> ואתה הוא לאחר שנבה\"ע בלי שום שינוי כלל, כי לא מחשבותי מחשבותיכם<sup data-n=\"153\">152</sup> כו' ומיד שעלה ברצונו נתהוה הכל",[["140","139","<b>זה לעומ\"ז</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד."],["141","140","<b>העוה\"ז. . שכולו מלא שקרים</b>: ראה ויק\"ר פכ\"ו, ז."],["142","141","<b>ב\"כ</b>: בין כך. בהמשך הנדפס: בד\"כ בדרך כלל."],["143","142","<b>מה</b>: ניתוסף ע\"פ המשך הנדפס."],["144","143","<b>חי ה' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["145","144","<b>שמע ישראל</b>: ואתחנן ו, ד."],["146","145","<b>שמע. . השגה והבנה</b>: ראה זהר אד\"ר נשא קלח, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תשלו. וש\"נ. הנחות תקע\"ז ע' קמח. וש\"נ."],["147","146","<b>הסכת ושמע</b>: תבוא כז, ט."],["148","147","<b>ושמע. . אסיפה וקיבוץ</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381012\" data-slug=\"likkutei-torah\" data-id=\"4001381012\">לקו\"ת האזינו עב, ב</a>. שע\"ת ס, ג ובהערה 8."],["149","148","<b>וישמע שאול</b>: שמואל-א טו, ד."],["150","149","<b>סוכ\"ע וממכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["151","150","<b>ובטובו מחדש בכי\"ת מע\"ב</b>: ברכת יוצר. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה להבין ענין ר\"ח ובהערה 43."],["152","151","<b>שאתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["153","152","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381199\" data-slug=\"likkutei-torah\" data-id=\"4001381199\">לקו\"ת שה\"ש יז, ג</a> ואילך. (הועתק) לעיל ח\"א (בחלק המאמרים) המשך מצה זו על יד הערה 358 ואילך ובהנסמן שם."]]],[2000480087,"וכמ\"ש בזהר שבמח' אחת נבראו כל העולמות<sup data-n=\"154\">153</sup>, וממוצא דבר נשמע שאינו תופס מקום שהרי אפי' לגבי האדם אינו תופס מקום מח' אחת וכ\"ש לגבי' ית', וגם כי לא מח' מחשבותיכם שהאדם כשחושב איזה דבר ה\"ה מלובש ומשוקע במח' זו כו', משא\"כ למעלה הרי אינו מלובש כלל והוא הי' הוה ויהי' כא'<sup data-n=\"155\">154</sup>, ובחי' כח הפועל בנפעל<sup data-n=\"156\">155</sup> זהו במדת מלכותו<sup data-n=\"157\">156</sup> ית' לבד, וזהו בשכמל\"ו, פי' שלמה הוא ה' אחד לפי שבשכמל\"ו שכלליות ההשתלשלו' הוא מבחי' שם כבוד מל', שם הוא הארה כנודע, וכבוד הוא לבוש שהוא ג\"כ חיצוני' והארה, ומל' הוא ג\"כ הארה שהרי מלך שמו נקרא עליהם<sup data-n=\"158\">158</sup> א\"כ זהו רק הארה דהארה דהארה<sup data-n=\"159\">157</sup> כו' וכאשר יעמיק דעתו ויתקע מח' בעומק בד\"ז בהתבוננות ובהתקשרות בחוזק אזי גם נפשו הבהמית תשכיל ותתבונן איך שאין טוב לפניו כ\"א לדבקה בו ותוליד מדת האהבה ברשפי אש ובתשוקה נפלאה להיות בבחי' כלתה נפשי<sup data-n=\"160\">159</sup> כו' ועמך לא חפצתי<sup data-n=\"161\">160</sup> כו' שכל מה שהוא עמך בטל וטפל לך לא חפצתי כ\"א לדבקה בו כו', וזהו ואהבת בכל לבבך בשני יצריך כו', ועכ\"ז גם אחרי שיבין שמו שנק' יצה\"ר לא זז כו' מפני שארז\"ל אל תאמין בעצמך<sup data-n=\"162\">161</sup> כו'.\n<b></b>קיצור. שבכל נפש יש ב' בחי' שכל ומדות, והשכל הוא המנהיג, ושכל נה\"ב הוא היפך שכל הנה\"א, אך כאשר יעמיק דעתו בהתבוננות ה' אחד, ובשכמל\"ו גם הנה\"ב יבין ויוליד מדת אהבה ברשפי אש כו'.\n&lt;9&gt;\nּז) והנה ע\"י בירור נה\"ב עי\"ז נעשה הנשמה בחי' נר הוי' שיהי' השמן נמשך אחר הפתילה, דעם היות הנשמה היא הנה\"א נק' בשם נר, וכמו שנת\"ל שעיקר הנר היא הפתילה<sup data-n=\"163\">162</sup> וזהו שנק' הנה\"א בשם נר ה' לפי שלעצמה א\"צ תיקון<sup data-n=\"164\">163</sup> כלל, משא\"כ הנה\"ב א\"א לקרות בשם נר לפי שעדיין לא נתבררה כו', אך ע\"י ירידת הנה\"א בגוף לבררו עם הנה\"ב זהו כמו הנר שנותנים בו שמן או חלב בכדי שידלק הפתילה הרבה ותאיר אורה אור רב, והיינו ע\"י בחי' בירור חכ' דנה\"ב שגם הוא",[["154","153","<b>שבמח' אחת נבראו כל העולמות</b>: ראה זהר שמות כ, א. שם תוספות רעו, סע\"ב. סידור שער התפלה יח, סע\"ד. סהמ\"צ להצ\"צ ע' קעח ואילך. מאמרי אדה\"א קונטרסים ע' תלג. וש\"נ."],["155","154","<b>הי' הוה ויהי' כא'</b>: ראה שער היחוד והאמונה פ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680292\" data-slug=\"torat-chaim\" data-id=\"2300680292\">תו\"ח מקץ ריט, ד</a> הערה 62."],["156","155","<b>כח הפועל בנפעל</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a>: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת ) סוף ש\"ג."],["157","156","<b>כח הפועל. . מלכותו</b>: ראה גם סה\"מ תרל\"ח ע' קב."],["158","158","<b>מלך שמו נקרא עליהם</b>: ראה פיוט אדון עולם. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 16."],["159","157","<b>בשכמל\"ו. . דהארה</b>: פסחים נו, א (נוסח ק\"ש). ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וירא העם וינועו ובהערה 76."],["160","159","<b>כלתה נפשי</b>: תהלים פד, ג."],["161","160","<b>ועמך לא חפצתי</b>: תהלים עג, כה."],["162","161","<b>אל תאמין בעצמך</b>: אבות פ\"ב, מ\"ד."],["163","162","<b>וכמו שנת\"ל. . הפתילה</b>: רפ\"ד."],["164","163","<b>הנה\"א. . א\"צ תיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>). <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">ש\"א ט, א</a> הערה 4."]]]]});
